def get_player_level(xp):
    """Return the player's level (1-9) for the given XP total."""
    if not isinstance(xp, int):
        raise TypeError("xp must be an integer")
    if xp < 0:
        raise ValueError("xp must not be negative")
    level = 1
    if xp >= 1000:
        level = 2
    if xp >= 2500:
        level = 3
    if xp >= 5000:
        level = 4
    if xp >= 10000:
        level = 5
    if xp >= 25000:
        level = 6
    if xp >= 50000:
        level = 7
    if xp >= 100000:
        level = 8
    if xp >= 250000:
        level = 9
    return level


def level_threshold(level):
    """Return the XP needed to reach the given level (1-9)."""
    thresholds = {
        1: 0,
        2: 1000,
        3: 2500,
        4: 5000,
        5: 10000,
        6: 25000,
        7: 50000,
        8: 100000,
        9: 250000,
    }
    if level not in thresholds:
        raise ValueError("level must be between 1 and 9")
    return thresholds[level]


def xp_to_next_level(xp):
    """Return XP still needed for the next level, or 0 at the maximum level."""
    level = get_player_level(xp)
    if level == 9:
        return 0
    return level_threshold(level + 1) - xp


def level_progress(xp):
    """Return the fraction (0.0-1.0) of progress through the current level."""
    level = get_player_level(xp)
    if level == 9:
        return 1.0
    start = level_threshold(level)
    span = level_threshold(level + 1) - start
    return (xp - start) / span


def format_player_report(name, xp):
    level = get_player_level(xp)
    bar_width = 20
    filled = int(round(level_progress(xp) * bar_width))
    bar = "#" * filled + "-" * (bar_width - filled)
    remaining = xp_to_next_level(xp)
    tail = "MAX" if remaining == 0 else "%d XP to level %d" % (remaining, level + 1)
    return "%-8s lvl %d  [%s]  %7d XP  %s" % (name, level, bar, xp, tail)


def main():
    players = [
        ("Ana", 0),
        ("Bo", 999),
        ("Cleo", 5000),
        ("Dan", 17500),
        ("Eve", 100000),
        ("Finn", 999999),
    ]
    for name, xp in players:
        print(format_player_report(name, xp))


if __name__ == "__main__":
    main()

