SPEED_OF_LIGHT_M_PER_S = 299792458


def get_orbital_distance_km(body_name):
    """Approximate average distance from Earth, in kilometres."""
    if body_name == 'Moon':
        return 384400
    elif body_name == 'Sun':
        return 149597870
    elif body_name == 'Mars':
        return 54600000
    elif body_name == 'Venus':
        return 38000000
    elif body_name == 'Mercury':
        return 77000000
    elif body_name == 'Jupiter':
        return 588000000
    elif body_name == 'Saturn':
        return 1200000000
    elif body_name == 'Neptune':
        return 4500000000
    else:
        return -1


def light_travel_time_seconds(distance_km):
    """Seconds a radio signal needs to cover the given distance."""
    speed_km_per_s = SPEED_OF_LIGHT_M_PER_S / 1000
    return distance_km / speed_km_per_s


def format_duration(seconds):
    """Human readable duration: days, minutes or seconds."""
    if seconds >= 86400:
        return "%.2f days" % (seconds / 86400)
    if seconds >= 60:
        return "%.2f minutes" % (seconds / 60)
    return "%.2f seconds" % seconds


def format_distance(distance_km):
    """Compact distance string, switching to millions for large values."""
    if distance_km >= 1000000:
        return "%.3f million km" % (distance_km / 1000000)
    if distance_km >= 10000:
        return "%d thousand km" % (distance_km // 1000)
    return "%d km" % distance_km


def distance_in_au(distance_km):
    """Distance expressed in astronomical units."""
    return distance_km / 149597870


def describe_body(body_name):
    distance_km = get_orbital_distance_km(body_name)
    if distance_km < 0:
        return "%-8s unknown body" % body_name
    delay = light_travel_time_seconds(distance_km)
    return "%-8s %-22s %8.4f AU   signal: %s" % (
        body_name,
        format_distance(distance_km),
        distance_in_au(distance_km),
        format_duration(delay),
    )


def main():
    bodies = ['Moon', 'Sun', 'Mercury', 'Venus', 'Mars',
              'Jupiter', 'Saturn', 'Neptune', 'Pluto']
    for body in bodies:
        print(describe_body(body))
    print("Moon distance literal check:", get_orbital_distance_km('Moon'))
    print("Unknown body returns:", get_orbital_distance_km('Death Star'))


if __name__ == '__main__':
    main()

