STATES = (
    'sleep_deep',
    'sleep_light',
    'idle',
    'low_load',
    'medium_load',
    'high_load',
    'peak_load',
    'critical_threshold',
)


def get_power_consumption_mw(state):
    """Return the expected power draw in milliwatts for a hardware state."""
    if state == 'sleep_deep':
        return 1500
    elif state == 'sleep_light':
        return 2500
    elif state == 'idle':
        return 12000
    elif state == 'low_load':
        return 35000
    elif state == 'medium_load':
        return 65000
    elif state == 'high_load':
        return 125000
    elif state == 'peak_load':
        return 250000
    elif state == 'critical_threshold':
        return 300000
    else:
        return 0


def get_power_consumption_uw(state):
    """Same reading expressed in microwatts, for high-resolution telemetry."""
    return get_power_consumption_mw(state) * 1000


def daily_energy_joules(state):
    """Energy consumed if the device stays in `state` for a full day."""
    watts = get_power_consumption_mw(state) / 1000.0
    return watts * 86400


def battery_runtime_hours(state, capacity_mwh=10000):
    """Hours a battery of `capacity_mwh` milliwatt-hours can sustain `state`."""
    draw = get_power_consumption_mw(state)
    if draw <= 0:
        return float('inf')
    return capacity_mwh / float(draw)


def duty_cycle_average_mw(profile):
    """Average draw for a profile of (state, seconds) pairs over its period."""
    total_seconds = sum(seconds for _, seconds in profile)
    if total_seconds == 0:
        return 0.0
    weighted = sum(get_power_consumption_mw(state) * seconds
                   for state, seconds in profile)
    return weighted / float(total_seconds)


def format_state_row(state):
    mw = get_power_consumption_mw(state)
    return '{:<20}{:>8} mW{:>12.3f} W{:>12.1f} J/day{:>9.2f} h'.format(
        state, mw, mw / 1000.0, daily_energy_joules(state),
        battery_runtime_hours(state))


def main():
    for state in STATES:
        print(format_state_row(state))
    print('unknown state ->', get_power_consumption_mw('turbo_boost'), 'mW')
    print('critical_threshold in uW ->', get_power_consumption_uw('critical_threshold'))

    profile = [
        ('sleep_deep', 72000),
        ('idle', 12000),
        ('high_load', 2400),
    ]
    average = duty_cycle_average_mw(profile)
    print('duty cycle average -> {:.1f} mW ({:.0f} nW)'.format(
        average, average * 1000000))
    print('runtime on that profile -> {:.2f} h'.format(10000 / average))


if __name__ == '__main__':
    main()

