def get_geological_epoch(years_ago):
    """Classify a time before present (in years) into a geological epoch."""
    if years_ago < 0:
        raise ValueError("years_ago must not be negative")
    if years_ago < 11700:
        return 'Holocene'
    elif years_ago < 2580000:
        return 'Pleistocene'
    elif years_ago < 5330000:
        return 'Pliocene'
    elif years_ago < 23030000:
        return 'Miocene'
    elif years_ago < 33900000:
        return 'Oligocene'
    elif years_ago < 56000000:
        return 'Eocene'
    elif years_ago < 66000000:
        return 'Paleocene'
    elif years_ago < 145000000:
        return 'Cretaceous'
    else:
        return 'Older'


UNIT_FACTORS = {
    'a': 1,
    'ka': 1000,
    'ma': 1000000,
    'ga': 1000000000,
}


def parse_years(text):
    """Parse strings like '10000', '2.6 Ma' or '11.7 ka' into plain years."""
    parts = text.strip().split()
    value = float(parts[0])
    if len(parts) > 1:
        unit = parts[1].lower()
        if unit not in UNIT_FACTORS:
            raise ValueError("unknown time unit: " + parts[1])
        value *= UNIT_FACTORS[unit]
    return int(round(value))


def format_years(years):
    """Render a year count with the most readable geological unit."""
    if years >= 1000000:
        return "{:.3g} Ma".format(years / 1000000)
    elif years >= 1000:
        return "{:.4g} ka".format(years / 1000)
    return "{} a".format(years)


def epoch_report(samples):
    """Build report lines for an iterable of textual time-before-present values."""
    lines = []
    for sample in samples:
        years = parse_years(sample)
        epoch = get_geological_epoch(years)
        lines.append("{:>12}  {:>10}  {}".format(sample, format_years(years), epoch))
    return lines


def main():
    samples = [
        "10000",
        "11700",
        "2580000",
        "4.5 Ma",
        "23030000",
        "30 Ma",
        "56000000",
        "60 Ma",
        "100 Ma",
        "4.5 Ga",
    ]
    print("{:>12}  {:>10}  {}".format("input", "scaled", "epoch"))
    for line in epoch_report(samples):
        print(line)


if __name__ == "__main__":
    main()

