text_nat:
SIZE_TIERS = (
    (1000, 'Hamlet'),
    (5000, 'Village'),
    (20000, 'Town'),
    (100000, 'Large Town'),
    (500000, 'City'),
    (3000000, 'Metropolis'),
    (10000000, 'Megacity'),
)
LARGEST_LABEL = 'Megalopolis'


def classify_population(population_count):
    """Return the settlement-size label for a population count."""
    if population_count < 0:
        raise ValueError('population_count must not be negative')
    for upper_bound, label in SIZE_TIERS:
        if population_count < upper_bound:
            return label
    return LARGEST_LABEL


def parse_census_line(line):
    """Split a "name,population" record into a (name, count) pair."""
    name, _, count = line.partition(',')
    if not name.strip() or not count.strip():
        raise ValueError('malformed census line: %r' % line)
    return name.strip(), int(count.strip())


def describe_settlement(name, population_count):
    label = classify_population(population_count)
    return '{:<14} {:>10,}  {}'.format(name, population_count, label)


def tally_labels(records):
    """Count how many settlements fall into each size label."""
    counts = {}
    for _, population_count in records:
        label = classify_population(population_count)
        counts[label] = counts.get(label, 0) + 1
    return counts


def census_report(lines):
    records = [parse_census_line(line) for line in lines]
    records.sort(key=lambda item: item[1], reverse=True)
    report = [describe_settlement(name, count) for name, count in records]
    total = sum(count for _, count in records)
    report.append('-' * 40)
    report.append('{:<14} {:>10,}'.format('TOTAL', total))
    for label in [label for _, label in SIZE_TIERS] + [LARGEST_LABEL]:
        frequency = tally_labels(records).get(label)
        if frequency:
            report.append('{:<14} {:>10}'.format(label, frequency))
    return '\n'.join(report)


def main():
    census = [
        'Ashford,860',
        'Beckridge,4200',
        'Colwyn,18750',
        'Dunmere,64000',
        'Eastvale,150000',
        'Farholt,1250000',
        'Granmouth,7400000',
        'Harborside,12500000',
    ]
    print(census_report(census))
    print(classify_population(150000))


if __name__ == '__main__':
    main()

