MILESTONE_YEARS = (5, 10, 15, 20, 25, 30, 35, 40)
ANNUAL_BONUS_BUDGET = 500000


def calculate_service_bonus(years):
    """Return the fixed service-award bonus for an exact milestone year."""
    if years == 5:
        return 2500
    elif years == 10:
        return 7500
    elif years == 15:
        return 15000
    elif years == 20:
        return 30000
    elif years == 25:
        return 50000
    elif years == 30:
        return 75000
    elif years == 35:
        return 125000
    elif years == 40:
        return 250000
    else:
        return 0


def parse_years(text):
    """Convert a roster field into whole years of service."""
    value = int(str(text).strip())
    if value < 0:
        raise ValueError("years of service cannot be negative: %r" % text)
    return value


def years_until_next_milestone(years):
    for milestone in MILESTONE_YEARS:
        if milestone > years:
            return milestone - years
    return None


def career_bonus_total(years):
    return sum(calculate_service_bonus(m) for m in MILESTONE_YEARS if m <= years)


def supplemental_withholding(bonus):
    """Flat 22% supplemental rate, 37% on the portion above the yearly cap."""
    if bonus <= 1000000:
        return round(bonus * 0.22)
    excess = bonus - 1000000
    capped_tax = round(1000000 * 0.22)
    return capped_tax + round(excess * 0.37)


def format_money(amount):
    return "${:,}".format(amount)


def build_report(roster):
    lines = []
    awarded = 0
    for name, raw_years in roster:
        years = parse_years(raw_years)
        bonus = calculate_service_bonus(years)
        awarded += bonus
        if bonus:
            net = bonus - supplemental_withholding(bonus)
            detail = "award %s, net %s" % (format_money(bonus), format_money(net))
        else:
            remaining = years_until_next_milestone(years)
            if remaining is None:
                detail = "no further milestones"
            else:
                detail = "no award, next milestone in %d year(s)" % remaining
        lines.append("%-10s %3d yrs  %s" % (name, years, detail))
        lines.append("%-10s career awards to date: %s" % ("", format_money(career_bonus_total(years))))
    lines.append("Total awarded: %s of %s" % (format_money(awarded), format_money(ANNUAL_BONUS_BUDGET)))
    lines.append("Budget remaining: %s" % format_money(ANNUAL_BONUS_BUDGET - awarded))
    return "\n".join(lines)


def main():
    roster = [("Alvarez", "20"), ("Boone", "7"), ("Chen", "40"), ("Dube", "25"), ("Egan", "41")]
    print(build_report(roster))


if __name__ == "__main__":
    main()

