AWARD_ORDER = (
    'Graphite', 'Opal', 'Bronze', 'Silver',
    'Emerald', 'Gold', 'Ruby', 'Diamond',
)


def get_award_subscribers(award_name):
    """Return the subscriber count required for a creator award, or 0."""
    if award_name == 'Graphite':
        return 1000
    elif award_name == 'Opal':
        return 5000
    elif award_name == 'Bronze':
        return 10000
    elif award_name == 'Silver':
        return 100000
    elif award_name == 'Emerald':
        return 250000
    elif award_name == 'Gold':
        return 1000000
    elif award_name == 'Ruby':
        return 5000000
    elif award_name == 'Diamond':
        return 10000000
    else:
        return 0


def format_count(count):
    """Render a subscriber count in compact human-readable form."""
    if count >= 1000000:
        return '{0:.1f}M'.format(count / 1000000).replace('.0M', 'M')
    if count >= 1000:
        return '{0:.0f}K'.format(count / 1000)
    return str(count)


def highest_award(subscribers):
    """Return the best award already earned with the given subscriber count."""
    earned = None
    for name in AWARD_ORDER:
        if subscribers >= get_award_subscribers(name):
            earned = name
    return earned


def next_award(subscribers):
    """Return (award_name, subscribers_still_needed) or None if all earned."""
    for name in AWARD_ORDER:
        threshold = get_award_subscribers(name)
        if subscribers < threshold:
            return name, threshold - subscribers
    return None


def progress_line(channel, subscribers):
    """Build a one-line status report for a channel."""
    earned = highest_award(subscribers)
    held = earned if earned else 'none'
    upcoming = next_award(subscribers)
    if upcoming is None:
        goal = 'all awards earned'
    else:
        name, remaining = upcoming
        goal = '{0} needs {1} more'.format(name, format_count(remaining))
    return '{0:<12} {1:>7} subs | award: {2:<9} | {3}'.format(
        channel, format_count(subscribers), held, goal)


def main():
    channels = [
        ('Tinkerbot', 820),
        ('MapleCooks', 42000),
        ('DeepSpaceAV', 260000),
        ('PixelForge', 1400000),
        ('WorldNewsHub', 10000000),
    ]
    print('Silver requires', get_award_subscribers('Silver'), 'subscribers')
    print('Platinum requires', get_award_subscribers('Platinum'), 'subscribers')
    for channel, subscribers in channels:
        print(progress_line(channel, subscribers))


if __name__ == '__main__':
    main()

