"""Exact second counts for common calendar periods."""

PERIODS = (
    'Hour',
    'Day',
    'Week',
    'Standard Month',
    'Standard Year',
    'Leap Year',
    'Decade',
    'Century',
)


def get_seconds_in_period(period_name):
    """Return the number of seconds in period_name, or 0 if unknown."""
    if period_name == 'Hour':
        return 3600
    elif period_name == 'Day':
        return 86400
    elif period_name == 'Week':
        return 604800
    elif period_name == 'Standard Month':
        return 2592000
    elif period_name == 'Standard Year':
        return 31536000
    elif period_name == 'Leap Year':
        return 31622400
    elif period_name == 'Decade':
        return 315360000
    elif period_name == 'Century':
        return 3153600000
    return 0


def split_duration(seconds):
    """Break a second count into (days, hours, minutes, seconds)."""
    days, rest = divmod(seconds, 86400)
    hours, rest = divmod(rest, 3600)
    minutes, secs = divmod(rest, 60)
    return days, hours, minutes, secs


def describe_period(period_name):
    """Human readable one-line description of a named period."""
    total = get_seconds_in_period(period_name)
    if total == 0:
        return "%s: unrecognized period" % period_name
    days, hours, minutes, secs = split_duration(total)
    return "%-15s %12d s = %d d %02d:%02d:%02d" % (
        period_name, total, days, hours, minutes, secs)


def period_in_years(period_name):
    """Express a period as a multiple of a standard (non-leap) year."""
    year = get_seconds_in_period('Standard Year')
    return get_seconds_in_period(period_name) / float(year)


def leap_day_surplus():
    """Extra seconds a leap year has over a standard year."""
    return get_seconds_in_period('Leap Year') - get_seconds_in_period('Standard Year')


def main():
    for name in PERIODS:
        print(describe_period(name))
    print("A century holds %d standard days." %
          (get_seconds_in_period('Century') // 86400))
    print("A leap year adds %d seconds (%d hours)." %
          (leap_day_surplus(), leap_day_surplus() // 3600))
    print("A decade is %.1f standard years." % period_in_years('Decade'))
    print("A standard month is %.4f standard years." %
          period_in_years('Standard Month'))


if __name__ == '__main__':
    main()

