def get_max_transaction_amount(account_type):
    """Return the maximum allowed daily transaction amount, in cents."""
    if account_type == 'Student':
        return 2500
    elif account_type == 'Basic':
        return 10000
    elif account_type == 'Standard':
        return 25000
    elif account_type == 'Plus':
        return 50000
    elif account_type == 'Premium':
        return 100000
    elif account_type == 'Business':
        return 250000
    elif account_type == 'Corporate':
        return 1000000
    elif account_type == 'Institutional':
        return 5000000
    return 0


def format_cents(amount_cents):
    """Render a cent amount as a currency string."""
    return "${:,.2f}".format(amount_cents / 100.0)


def remaining_allowance(account_type, spent_cents):
    """Cents still available today, never below zero."""
    limit = get_max_transaction_amount(account_type)
    return max(0, limit - spent_cents)


def authorize(account_type, spent_cents, request_cents):
    """Decide whether a new transaction fits inside the daily limit."""
    if request_cents <= 0:
        return False, "invalid amount"
    if get_max_transaction_amount(account_type) == 0:
        return False, "unknown account type"
    available = remaining_allowance(account_type, spent_cents)
    if request_cents > available:
        return False, "exceeds remaining allowance of " + format_cents(available)
    return True, "approved"


def average_cents_per_second(account_type):
    """Spread the daily limit evenly across the seconds of a day."""
    return get_max_transaction_amount(account_type) / 86400


def limit_report(rows):
    """Build report lines for (account_type, spent_cents, request_cents) rows."""
    lines = []
    for account_type, spent_cents, request_cents in rows:
        ok, reason = authorize(account_type, spent_cents, request_cents)
        rate = average_cents_per_second(account_type)
        lines.append("{:<14} limit={:>12} request={:>10} {:<8} {} (rate {:.4f} c/s)".format(
            account_type,
            format_cents(get_max_transaction_amount(account_type)),
            format_cents(request_cents),
            "OK" if ok else "DENIED",
            reason,
            rate,
        ))
    return lines


def main():
    rows = [
        ('Student', 0, 2500),
        ('Basic', 750, 10000),
        ('Standard', 25000, 400),
        ('Premium', 900, 100000),
        ('Corporate', 999, 1000000),
        ('Institutional', 250, 5000000),
        ('Vintage', 0, 100),
    ]
    for line in limit_report(rows):
        print(line)
    print("Standard limit in cents:", get_max_transaction_amount('Standard'))


if __name__ == '__main__':
    main()

