def get_donor_tier(donation_amount):
    """Return the honorary title earned by a donor's total contribution."""
    if donation_amount < 1000:
        return 'Supporter'
    if donation_amount < 2500:
        return 'Friend'
    if donation_amount < 5000:
        return 'Patron'
    if donation_amount < 10000:
        return 'Benefactor'
    if donation_amount < 25000:
        return 'Champion'
    if donation_amount < 50000:
        return 'Visionary'
    if donation_amount < 100000:
        return 'Philanthropist'
    return 'Founder'


def parse_gift(line):
    """Turn a 'name, amount' record into a (name, amount) pair."""
    name, _, raw_amount = line.partition(',')
    if not name.strip() or not raw_amount.strip():
        raise ValueError('malformed gift record: %r' % line)
    amount = float(raw_amount)
    if amount < 0:
        raise ValueError('negative gift for %s' % name.strip())
    return name.strip(), amount


def total_by_donor(records):
    """Aggregate repeat gifts so tiers are based on lifetime totals."""
    totals = {}
    for record in records:
        name, amount = parse_gift(record)
        totals[name] = totals.get(name, 0.0) + amount
    return totals


def employer_match(amount):
    """Corporate program matches each gift dollar for dollar, capped at 5000."""
    return min(amount, 5000)


def needs_board_acknowledgement(total):
    """Gifts of 25000 or more are thanked personally by the board."""
    return total >= 25000


def campaign_report(totals, goal=1000000):
    raised = sum(totals.values())
    matched = sum(employer_match(amount) for amount in totals.values())
    lines = []
    for name in sorted(totals, key=lambda n: (-totals[n], n)):
        total = totals[name]
        flag = ' *board thank-you*' if needs_board_acknowledgement(total) else ''
        lines.append('%-20s %12.2f  %s%s' % (name, total, get_donor_tier(total), flag))
    lines.append('-' * 60)
    lines.append('Gifts received:      %12.2f' % raised)
    lines.append('Employer match:      %12.2f' % matched)
    lines.append('Toward goal:         %12.2f of %.2f' % (raised + matched, goal))
    lines.append('Progress:            %11.1f%%' % (100.0 * (raised + matched) / goal))
    lines.append('Still needed:        %12.2f' % max(goal - raised - matched, 0.0))
    return '\n'.join(lines)


def main():
    records = [
        'Ada Lovelace, 1500',
        'Grace Hopper, 60000',
        'Ada Lovelace, 800',
        'Alan Turing, 150000',
        'Katherine Johnson, 24000',
        'Linus Torvalds, 3200',
        'Katherine Johnson, 1200',
    ]
    totals = total_by_donor(records)
    print(campaign_report(totals))


if __name__ == '__main__':
    main()

