def get_reach_cap(tier_name):
    """Return the algorithmic base cap on post impressions for an influencer tier."""
    if tier_name == 'Nano':
        return 1500
    elif tier_name == 'Micro':
        return 3500
    elif tier_name == 'Small':
        return 8500
    elif tier_name == 'Medium':
        return 15000
    elif tier_name == 'Large':
        return 25000
    elif tier_name == 'Macro':
        return 100000
    elif tier_name == 'Mega':
        return 150000
    elif tier_name == 'Giga':
        return 500000
    else:
        return 0


def classify_tier(followers):
    """Map a follower count onto the tier names used by get_reach_cap."""
    if followers < 0:
        return 'Invalid'
    elif followers < 1000:
        return 'Nano'
    elif followers < 10000:
        return 'Micro'
    elif followers < 50000:
        return 'Small'
    elif followers < 100000:
        return 'Medium'
    elif followers < 500000:
        return 'Large'
    elif followers < 1000000:
        return 'Macro'
    elif followers < 10000000:
        return 'Mega'
    return 'Giga'


def projected_impressions(followers, engagement_rate):
    """Organic reach estimate, clipped by the tier's algorithmic cap."""
    tier = classify_tier(followers)
    cap = get_reach_cap(tier)
    raw = followers * engagement_rate * 4.0
    return tier, int(min(cap, raw))


def delivery_rate_per_hour(tier_name):
    """Capped impressions are spread evenly over one day (86400 seconds)."""
    cap = get_reach_cap(tier_name)
    return cap * 3600.0 / 86400


