    tier, reach = projected_impressions(followers, engagement_rate)
    cap = get_reach_cap(tier)
    saturation = 100.0 * reach / cap if cap else 0.0
    return "{:<12} {:>10,} {:<7} {:>9,} {:>7.1f}% {:>9.0f}/h".format(
        handle, followers, tier, reach, saturation, delivery_rate_per_hour(tier))


