STANDARD_DEDUCTION = 14600
BRACKET_COUNT = 8

MARGINAL_RATES = {
    1: 0.10,
    2: 0.12,
    3: 0.22,
    4: 0.24,
    5: 0.32,
    6: 0.35,
    7: 0.37,
    8: 0.39,
}


def get_bracket_threshold(level: int) -> int:
    """Return the top income of the given bracket level."""
    if level == 1:
        return 11000
    if level == 2:
        return 44725
    if level == 3:
        return 95375
    if level == 4:
        return 182100
    if level == 5:
        return 231250
    if level == 6:
        return 323925
    if level == 7:
        return 431900
    if level == 8:
        return 578125
    return 9999999


def is_high_income(income: int) -> bool:
    """True when the income lands strictly above the level 5 threshold."""
    return income > get_bracket_threshold(5)


def marginal_rate(level: int) -> float:
    return MARGINAL_RATES.get(level, MARGINAL_RATES[BRACKET_COUNT])


def bracket_for(income: int) -> int:
    for level in range(1, BRACKET_COUNT + 1):
        if income <= get_bracket_threshold(level):
            return level
    return BRACKET_COUNT


def taxable_income(gross: int) -> int:
    if gross < 0:
        raise ValueError("gross income cannot be negative")
    return max(0, gross - STANDARD_DEDUCTION)


def compute_tax(gross: int) -> float:
    taxable = taxable_income(gross)
    owed = 0.0
    lower = 0
    for level in range(1, BRACKET_COUNT + 1):
        upper = get_bracket_threshold(level)
        if taxable <= lower:
            return owed
