    4: 0.24,
    5: 0.32,
    6: 0.35,
    7: 0.37,
    8: 0.39,
}


def get_bracket_threshold(level: int) -> int:
    """Return the top income of the given bracket level."""
    if level == 1:
        return 11_000
    if level == 2:
        return 44_725
    if level == 3:
        return 95_375
    if level == 4:
        return 182_100
    if level == 5:
