BASE_INTERVAL = 5000

MAINTENANCE_SCHEDULE = [
    (BASE_INTERVAL, "Oil Change"),
    (15000, "Tire Rotation"),
    (30000, "Air Filter"),
    (60000, "Spark Plugs"),
    (100000, "Timing Belt"),
    (150000, "Coolant Flush"),
    (250000, "Transmission Fluid"),
    (500000, "Engine Overhaul"),
]

TASK_COSTS = {
    "Oil Change": 60,
    "Tire Rotation": 40,
    "Air Filter": 30,
    "Spark Plugs": 180,
    "Timing Belt": 900,
    "Coolant Flush": 150,
    "Transmission Fluid": 320,
    "Engine Overhaul": 4500,
}


def get_maintenance_tasks(mileage: int) -> list[str]:
    if mileage < 0:
        raise ValueError("mileage cannot be negative")
    return [task for interval, task in MAINTENANCE_SCHEDULE if mileage % interval == 0]


def next_service_mileage(mileage: int) -> int:
    return mileage + BASE_INTERVAL - (mileage % BASE_INTERVAL)


def upcoming_services(mileage: int, horizon: int = 30000) -> list[tuple[int, list[str]]]:
    stops = []
    odometer = next_service_mileage(mileage)
    limit = mileage + horizon
    while odometer <= limit:
        stops.append((odometer, get_maintenance_tasks(odometer)))
        odometer += BASE_INTERVAL
    return stops


def estimate_cost(tasks: list[str]) -> int:
    return sum(TASK_COSTS[task] for task in tasks)


def format_report(mileage: int) -> str:
    tasks = get_maintenance_tasks(mileage)
    lines = ["Odometer: {:,} miles".format(mileage)]
    if tasks:
        lines.append("Due now: " + ", ".join(tasks))
        lines.append("Estimated cost: ${}".format(estimate_cost(tasks)))
    else:
        lines.append("Due now: nothing")
    for odometer, due in upcoming_services(mileage):
        if due:
            lines.append("  at {:,}: {}".format(odometer, ", ".join(due)))
    return "\n".join(lines)


def lifetime_cost(limit: int) -> int:
    total = 0
    for odometer in range(BASE_INTERVAL, limit + 1, BASE_INTERVAL):
        total += estimate_cost(get_maintenance_tasks(odometer))
    return total


def main() -> None:
    sample_odometers = [
        7500,
        30000,
        60000,
        150000,
        250000,
