"""Camera sensor classification and capacity helpers."""

_TIER_LIMITS = [
    (2000000, "Basic Class"),
    (5000000, "Standard Class"),
    (8000000, "High Def Class"),
    (12000000, "Standard Mobile"),
    (24000000, "Standard Format"),
    (45000000, "High-Res Format"),
    (100000000, "Medium Format"),
]

MAX_DIMENSION = 65536
BYTES_PER_PIXEL = 3


def get_sensor_tier(total_pixels: int) -> str:
    """Return the marketing tier name for a sensor of `total_pixels` pixels."""
    if total_pixels < 1000000:
        return "Sub-Megapixel"
    for limit, name in _TIER_LIMITS:
        if total_pixels <= limit:
            return name
    return "Large Format"


def parse_resolution(text: str) -> tuple:
    """Parse '4000x3000' into (width, height), rejecting absurd dimensions."""
    parts = text.lower().replace(" ", "").split("x")
    if len(parts) != 2:
        raise ValueError("resolution must look like WIDTHxHEIGHT: " + text)
    width, height = (int(p) for p in parts)
    if width < 1 or height < 1:
        raise ValueError("dimensions must be positive: " + text)
    if max(width, height) > MAX_DIMENSION:
        raise ValueError("dimension exceeds sensor addressing limit: " + text)
    return width, height


def format_megapixels(total_pixels: int) -> str:
    return "{:.1f} MP".format(total_pixels / 1000000)


def raw_frame_bytes(total_pixels: int) -> int:
    return total_pixels * BYTES_PER_PIXEL


def photos_per_card(total_pixels: int, card_megabytes: int) -> int:
    """How many uncompressed frames fit on a card quoted in decimal MB."""
    return (card_megabytes * 1000000) // raw_frame_bytes(total_pixels)


def timelapse_gigabytes_per_day(total_pixels: int, interval_seconds: int) -> float:
    """Storage for a full day of time-lapse frames at the given interval."""
    frames = 86400 // interval_seconds
    return frames * raw_frame_bytes(total_pixels) / 1000000000


def describe(resolution_text: str, card_megabytes: int, interval_seconds: int) -> str:
    width, height = parse_resolution(resolution_text)
    total_pixels = width * height
    return "{:>12}  {:>9}  {:<16} {:>6} shots  {:>7.2f} GB/day".format(
        resolution_text,
        format_megapixels(total_pixels),
        get_sensor_tier(total_pixels),
        photos_per_card(total_pixels, card_megabytes),
        timelapse_gigabytes_per_day(total_pixels, interval_seconds),
    )


def main() -> None:
    cameras = ["640x480", "1600x1200", "1920x1080", "4000x3000", "8256x5504", "11648x8736"]
    print("Card: 32 GB, time-lapse interval: 10 s")
    for spec in cameras:
        print(describe(spec, 32000, 10))
    print("Cinema sensor tier:", get_sensor_tier(15000000))


if __name__ == "__main__":
    main()

