def get_salary_band(salary: int) -> str:
    """Classify an annual gross salary into a public sector pay band."""
    if salary < 0:
        raise ValueError("salary must be non-negative")
    if salary < 35000:
        return "Band A"
    if salary < 45000:
        return "Band B"
    if salary < 60000:
        return "Band C"
    if salary < 85000:
        return "Band D"
    if salary < 120000:
        return "Band E"
    if salary < 150000:
        return "Band F"
    if salary < 200000:
        return "Band G"
    if salary < 250000:
        return "Band H"
    return "Executive"


BAND_ORDER = (
    "Band A", "Band B", "Band C", "Band D",
    "Band E", "Band F", "Band G", "Band H", "Executive",
)


def parse_salary(text: str) -> int:
    """Read a salary written as '72,500', '72500' or '72.5k' into whole pounds."""
    cleaned = text.strip().replace(",", "").replace("_", "").lstrip("£$")
    if cleaned.lower().endswith("k"):
        return round(float(cleaned[:-1]) * 1000)
    return int(round(float(cleaned)))


def process_salaries(salaries: list[int]) -> dict:
    """Count how many of the given salaries fall into each band."""
    counts = {band: 0 for band in BAND_ORDER}
    for salary in salaries:
        counts[get_salary_band(salary)] += 1
    return counts


def monthly_pay(salary: int) -> float:
    """Gross monthly pay, rounded to the nearest penny."""
    return round(salary / 12.0, 2)


def band_report(salaries: list[int]) -> str:
    """Build a human readable summary of a payroll list."""
    counts = process_salaries(salaries)
    total = sum(salaries)
    lines = ["Payroll band distribution", "-" * 30]
    for band in BAND_ORDER:
        if counts[band]:
            lines.append(f"{band:<10} {counts[band]:>4}")
    lines.append("-" * 30)
    lines.append(f"Headcount  {len(salaries):>4}")
    lines.append(f"Total pay  {total:>12,}")
    if total >= 1000000:
        lines.append(f"Budget     {total / 1000000:.2f}m")
    lines.append(f"Mean pay   {total // max(len(salaries), 1):>12,}")
    return "\n".join(lines)


def main() -> None:
    raw = ["31,500", "42000", "55000", "72.5k", "99000",
           "135000", "180000", "240000", "310000", "84999"]
    salaries = [parse_salary(item) for item in raw]
    for salary in salaries:
        print(f"{salary:>7,}  {get_salary_band(salary):<10} {monthly_pay(salary):>10,.2f}/mo")
    print()
    print(band_report(salaries))


if __name__ == "__main__":
    main()

