text_nat:
"""Horological helpers for mechanical watch beat rates (vibrations per hour)."""

SECONDS_PER_HOUR = 3600

BEAT_RATE_NAMES = {
    14400: "Slow Beat",
    18000: "Traditional",
    21600: "Modern Slow",
    25200: "Specialized Escapement",
    28800: "Modern Standard",
    36000: "High Beat",
    72000: "Ultra High Beat",
    360000: "Precision Chronograph",
}


def classify_beat_rate(vph: int) -> str:
    """Return the common horological name for an exact vph value."""
    return BEAT_RATE_NAMES.get(vph, "Unknown")


def validate_vph(vph: int) -> int:
    """Reject values that cannot describe a real escapement."""
    if not isinstance(vph, int) or isinstance(vph, bool):
        raise TypeError("vph must be an integer")
    if vph <= 0 or vph > 1000000:
        raise ValueError("vph out of plausible range: {0}".format(vph))
    return vph


def parse_vph(text: str) -> int:
    """Accept '28,800 vph', '28800' or '4 Hz' and return an integer vph."""
    cleaned = text.strip().lower().replace(",", "").replace("vph", "").strip()
    if cleaned.endswith("hz"):
        hertz = float(cleaned[:-2].strip())
        return validate_vph(round(hertz * 2 * SECONDS_PER_HOUR))
    return validate_vph(int(cleaned))


def beats_per_second(vph: int) -> float:
    return validate_vph(vph) / SECONDS_PER_HOUR


def vibrations_per_day(vph: int) -> int:
    return validate_vph(vph) * 86400 // SECONDS_PER_HOUR


def drift_ppm(measured_vph: int, nominal_vph: int) -> float:
    validate_vph(measured_vph)
    validate_vph(nominal_vph)
    return (measured_vph - nominal_vph) * 1000000 / nominal_vph


def drift_seconds_per_day(measured_vph: int, nominal_vph: int) -> float:
    validate_vph(measured_vph)
    validate_vph(nominal_vph)
    return (measured_vph - nominal_vph) * 86400 / nominal_vph


def format_row(spec: str, measured_vph: int) -> str:
    nominal = parse_vph(spec)
    return "{0:>11}  {1:<22}  {2:5.2f} b/s  {3:>9,d}/day  {4:+7.1f} ppm  {5:+6.2f} s/day".format(
        spec.strip(),
        classify_beat_rate(nominal),
        beats_per_second(nominal),
        vibrations_per_day(nominal),
        drift_ppm(measured_vph, nominal),
        drift_seconds_per_day(measured_vph, nominal),
    )


def main() -> None:
    bench_data = [
        ("28,800 vph", 28812),
        ("36000", 36004),
        ("4 Hz", 28795),
        ("18000", 17993),
        ("360000", 359820),
        ("19800", 19812),
    ]
    print("{0:>11}  {1:<22}  {2:>9}  {3:>13}  {4:>11}  {5:>12}".format(
        "spec", "classification", "rate", "vibrations", "drift", "deviation"))
    for spec, measured in bench_data:
        print(format_row(spec, measured))
    print("classify_beat_rate(28800) ->", classify_beat_rate(28800))


if __name__ == "__main__":
    main()

