def get_depreciation_factor(mileage: int) -> float:
    """Return the value multiplier for a used car with the given mileage."""
    if mileage < 0:
        raise ValueError("mileage cannot be negative")
    if mileage < 10000:
        return 0.95
    if mileage <= 20000:
        return 0.85
    if mileage <= 30000:
        return 0.75
    if mileage <= 40000:
        return 0.65
    if mileage <= 50000:
        return 0.55
    if mileage <= 60000:
        return 0.45
    if mileage <= 70000:
        return 0.35
    if mileage <= 80000:
        return 0.25
    if mileage <= 90000:
        return 0.15
    if mileage <= 100000:
        return 0.10
    return 0.05


def estimate_value(base_value: float, mileage: int) -> float:
    """Apply the mileage depreciation factor to a car's base value."""
    return round(base_value * get_depreciation_factor(mileage), 2)


def project_mileage(mileage: int, years: int, miles_per_year: int = 12000) -> int:
    """Extrapolate the odometer reading a number of years into the future."""
    if years < 0:
        raise ValueError("years cannot be negative")
    return mileage + years * miles_per_year


def trade_in_advice(base_value: float, mileage: int) -> str:
    """Suggest an action based on the value lost over the next year."""
    now = estimate_value(base_value, mileage)
    later = estimate_value(base_value, project_mileage(mileage, 1))
    loss = now - later
    if mileage > 100000:
        return "keep: already at salvage value"
    if loss >= 1000:
        return "sell within the year"
    return "keep: value is stable"


def format_row(name: str, base_value: float, mileage: int) -> str:
    factor = get_depreciation_factor(mileage)
    value = estimate_value(base_value, mileage)
    return "{:<12} {:>7} mi  x{:.2f}  ${:>9,.2f}  {}".format(
        name, mileage, factor, value, trade_in_advice(base_value, mileage)
    )


def main() -> None:
    fleet = [
        ("Hatchback", 18500.0, 8200),
        ("Sedan", 24000.0, 45000),
        ("Coupe", 32000.0, 20000),
        ("Pickup", 41000.0, 76500),
        ("Minivan", 28000.0, 100000),
        ("Old Wagon", 15000.0, 154300),
    ]
    print("Fleet valuation report")
    print("-" * 72)
    total = 0.0
    for name, base_value, mileage in fleet:
        print(format_row(name, base_value, mileage))
        total += estimate_value(base_value, mileage)
    print("-" * 72)
    print("Total estimated value: ${:,.2f}".format(total))
    print("Value in three years:  ${:,.2f}".format(
        sum(estimate_value(b, project_mileage(m, 3)) for _, b, m in fleet)
    ))


if __name__ == "__main__":
    main()

