CHALLENGE_TARGET = 50000
READING_WORDS_PER_MINUTE = 250


def categorize_manuscript(word_count: int) -> str:
    """Classify a manuscript by its length, checking the bands in order."""
    if word_count < 1000:
        return "Flash Fiction"
    if word_count <= 7500:
        return "Short Story"
    if word_count <= 10000:
        return "Long Short Story"
    if word_count <= 17500:
        return "Novelette"
    if word_count <= 40000:
        return "Novella"
    if word_count <= 80000:
        return "Novel"
    if word_count <= 110000:
        return "Epic"
    if word_count <= 150000:
        return "Massive Tome"
    return "Saga"


def check_challenge_winner(word_count: int) -> bool:
    """True when the draft reaches the writing-challenge target."""
    return word_count >= CHALLENGE_TARGET


def words_remaining(word_count: int) -> int:
    """How many words are still missing to win the challenge."""
    return max(0, CHALLENGE_TARGET - word_count)


def daily_pace(word_count: int, days_left: int) -> int:
    """Words per day needed to finish the challenge in the days that remain."""
    if days_left <= 0:
        return words_remaining(word_count)
    return -(-words_remaining(word_count) // days_left)


def estimate_reading_seconds(word_count: int) -> int:
    """Seconds a typical reader needs for the manuscript."""
    return round(word_count * 60 / READING_WORDS_PER_MINUTE)


def format_reading_time(word_count: int) -> str:
    """Render the reading estimate as hours and minutes."""
    seconds = estimate_reading_seconds(word_count)
    hours, remainder = divmod(seconds, 3600)
    minutes = remainder // 60
    if hours:
        return f"{hours}h {minutes:02d}m"
    return f"{minutes}m"


def describe(word_count: int) -> str:
    """One report line for a single draft."""
    if word_count < 0:
        raise ValueError("word_count must not be negative")
    if check_challenge_winner(word_count):
        status = "winner"
    else:
        status = f"needs {words_remaining(word_count)}"
    return (
        f"{word_count:>7} words | {categorize_manuscript(word_count):<17}"
        f" | read in {format_reading_time(word_count):>8} | {status}"
    )


def main() -> None:
    drafts = [420]
    drafts.append(7500)
    drafts.append(25000)
    drafts.append(48000)
    drafts.append(95000)
    drafts.append(160000)
    for count in drafts:
        print(describe(count))
    print("Pace with 5 days left:", daily_pace(48000, 5), "words/day")
    print("Target category:", categorize_manuscript(CHALLENGE_TARGET))


if __name__ == "__main__":
    main()

