import math


def validate_population(population: int) -> int:
    """Check that an estimated ancient population is a usable non-negative integer."""
    if isinstance(population, bool) or not isinstance(population, int):
        raise TypeError("population must be an integer")
    if population < 0:
        raise ValueError("population must not be negative")
    return population


def classify_city_size(population: int) -> str:
    """Categorise a settlement by its estimated population."""
    validate_population(population)
    if population < 1000:
        return "Hamlet"
    if population <= 5000:
        return "Village"
    if population <= 15000:
        return "Town"
    if population <= 40000:
        return "City"
    if population <= 100000:
        return "Large City"
    if population <= 250000:
        return "Metropolis"
    if population <= 500000:
        return "Megacity"
    if population <= 1000000:
        return "Empire Capital"
    return "Unprecedented"


def district_count(population: int) -> int:
    """Number of administrative districts, one per 10000 inhabitants."""
    validate_population(population)
    return math.ceil(population / 10000)


def annual_grain_tonnes(population: int) -> float:
    """Grain needed per year, assuming 200 kg of grain per person."""
    validate_population(population)
    return population * 200 / 1000


def aqueduct_flow_litres_per_second(population: int) -> float:
    """Steady aqueduct flow required for 15 litres per person per day."""
    validate_population(population)
    return population * 15 / 86400


def describe_city(name: str, population: int) -> str:
    """Build a one-line supply report for a single settlement."""
    label = classify_city_size(population)
    note = "beyond any attested scale" if population > 1000000 else label.lower()
    return (
        f"{name:<12} {population:>9,}  {label:<14} "
        f"districts={district_count(population):>3}  "
        f"grain={annual_grain_tonnes(population):>10,.1f} t  "
        f"aqueduct={aqueduct_flow_litres_per_second(population):>8.2f} L/s  ({note})"
    )


def main() -> None:
    cities = [
        ("Skara Brae", 60),
        ("Catalhoyuk", 6000),
        ("Athens", 30000),
        ("Teotihuacan", 125000),
        ("Babylon", 200000),
        ("Alexandria", 500000),
        ("Rome", 1000000),
        ("Trantor", 4000000),
    ]
    for name, population in cities:
        print(describe_city(name, population))
    print()
    print("classify_city_size(120000) ->", classify_city_size(120000))


if __name__ == "__main__":
    main()

