def estimate_vei(volume_cubic_meters: int) -> int:
    """Return the Volcanic Explosivity Index for a volume of ejecta in m^3."""
    if volume_cubic_meters < 0:
        raise ValueError("volume of ejecta cannot be negative")
    if volume_cubic_meters < 10000:
        return 0
    if volume_cubic_meters < 1000000:
        return 1
    if volume_cubic_meters < 10000000:
        return 2
    if volume_cubic_meters < 100000000:
        return 3
    if volume_cubic_meters < 1000000000:
        return 4
    if volume_cubic_meters < 10000000000:
        return 5
    if volume_cubic_meters < 100000000000:
        return 6
    if volume_cubic_meters < 1000000000000:
        return 7
    return 8


VEI_DESCRIPTIONS = (
    "effusive",
    "gentle",
    "explosive",
    "catastrophic",
    "cataclysmic",
    "paroxysmal",
    "colossal",
    "super-colossal",
    "mega-colossal",
)


def cubic_km_to_cubic_meters(volume_cubic_km: float) -> int:
    """Convert a volume given in cubic kilometres to whole cubic metres."""
    return int(round(volume_cubic_km * 1000000000))


def format_volume(volume_cubic_meters: int) -> str:
    """Render a volume using the largest sensible unit."""
    if volume_cubic_meters >= 1000000000:
        return "{0:g} km3".format(volume_cubic_meters / 1000000000)
    if volume_cubic_meters >= 1000000:
        return "{0:g} million m3".format(volume_cubic_meters / 1000000)
    return "{0:d} m3".format(volume_cubic_meters)


def eruption_report(name: str, volume_cubic_km: float) -> str:
    """Build a one-line summary for an eruption described in cubic kilometres."""
    volume = cubic_km_to_cubic_meters(volume_cubic_km)
    vei = estimate_vei(volume)
    return "{0:<22} {1:>14}  VEI {2} ({3})".format(
        name, format_volume(volume), vei, VEI_DESCRIPTIONS[vei]
    )


def main() -> None:
    eruptions = [
        ("Stromboli (typical)", 0.000005),
        ("Kilauea 1959", 0.04),
        ("Mount St. Helens 1980", 1.2),
        ("Pinatubo 1991", 10.0),
        ("Tambora 1815", 160.0),
        ("Toba 74 ka", 2800.0),
    ]
    for name, volume_cubic_km in eruptions:
        print(eruption_report(name, volume_cubic_km))


if __name__ == "__main__":
    main()

