def get_base_price_cents(carat_points: int) -> int:
    """Baseline price in cents for a flawless diamond of the given carat points."""
    if carat_points < 0:
        raise ValueError("carat_points must be non-negative")
    if carat_points < 25:
        return 1500
    if carat_points < 50:
        return 4500
    if carat_points < 75:
        return 9500
    if carat_points < 100:
        return 18000
    if carat_points < 150:
        return 35000
    if carat_points < 200:
        return 65000
    if carat_points < 300:
        return 120000
    if carat_points < 400:
        return 250000
    return 500000


CLARITY_FACTORS = {
    "FL": 1.00,
    "VVS": 0.85,
    "VS": 0.70,
    "SI": 0.50,
    "I": 0.30,
}


def adjusted_price_cents(carat_points: int, clarity: str) -> int:
    """Price for a stone of the given clarity grade, rounded to whole cents."""
    grade = clarity.upper()
    if grade not in CLARITY_FACTORS:
        raise ValueError("unknown clarity grade: " + clarity)
    base = get_base_price_cents(carat_points)
    return int(round(base * CLARITY_FACTORS[grade]))


def certification_fee_cents(price_cents: int) -> int:
    """Lab certification costs 2% of value, at least $15 and never above $750."""
    fee = price_cents * 2 // 100
    if fee < 1500:
        return 1500
    if fee > 75000:
        return 75000
    return fee


def format_cents(price_cents: int) -> str:
    """Render a cent amount as a dollar string."""
    return "${:,}.{:02d}".format(price_cents // 100, price_cents % 100)


def quote_lines(stones):
    """Build one report line per (points, clarity) pair, plus a total line."""
    lines = []
    total = 0
    for points, clarity in stones:
        value = adjusted_price_cents(points, clarity)
        fee = certification_fee_cents(value)
        total += value + fee
        lines.append(
            "{:>4} pts  {:<4}  {:>12}  (+{} cert)".format(
                points, clarity.upper(), format_cents(value), format_cents(fee)
            )
        )
    lines.append("TOTAL: " + format_cents(total))
    if total >= 1000000:
        lines.append("Shipment above the insured limit - armoured courier required.")
    return lines


def main():
    inventory = [
        (18, "FL"),
        (60, "VS"),
        (99, "VVS"),
        (140, "SI"),
        (250, "FL"),
        (410, "VVS"),
    ]
    for line in quote_lines(inventory):
        print(line)


if __name__ == "__main__":
    main()

