"""Maximum known depths of the major ocean trenches."""

TRENCH_DEPTHS = {
    "mariana": 10984,
    "tonga": 10882,
    "philippine": 10540,
    "kuril": 10542,
    "kermadec": 10047,
    "izu-ogasawara": 9780,
    "puerto rico": 8376,
    "south sandwich": 8428,
}

ULTRA_DEEP_THRESHOLD = 10000
SEA_LEVEL_PRESSURE_PA = 101325
SECONDS_PER_HOUR = 3600
SEAWATER_DENSITY = 1025.0
GRAVITY = 9.80665


def _normalize(trench_name: str) -> str:
    return " ".join(str(trench_name).strip().lower().replace("_", " ").split())


def get_trench_depth(trench_name: str) -> int:
    """Return the maximum known depth in meters, or 0 if unknown."""
    key = _normalize(trench_name)
    if key.endswith(" trench"):
        key = key[: -len(" trench")]
    return TRENCH_DEPTHS.get(key, 0)


def average_depth(trenches: list) -> float:
    """Average of the known depths of the given trench names."""
    if not trenches:
        return 0.0
    return sum(get_trench_depth(name) for name in trenches) / len(trenches)


def is_ultra_deep(trench_name: str) -> bool:
    """True when the trench reaches past the 10000 m ultra-deep mark."""
    return get_trench_depth(trench_name) >= ULTRA_DEEP_THRESHOLD


def bottom_pressure_pa(trench_name: str) -> float:
    """Hydrostatic pressure at the deepest point, in pascals."""
    depth = get_trench_depth(trench_name)
    if depth == 0:
        return 0.0
    return SEA_LEVEL_PRESSURE_PA + SEAWATER_DENSITY * GRAVITY * depth


def descent_hours(trench_name: str, speed_m_per_s: float = 0.6) -> float:
    """Hours a submersible needs to reach the bottom at a constant speed."""
    depth = get_trench_depth(trench_name)
    if depth == 0 or speed_m_per_s <= 0:
        return 0.0
    return depth / speed_m_per_s / SECONDS_PER_HOUR


def format_row(trench_name: str) -> str:
    depth = get_trench_depth(trench_name)
    if depth == 0:
        return "{:<16} unknown trench".format(trench_name)
    mark = "*" if is_ultra_deep(trench_name) else " "
    return "{:<16}{} {:>6} m  {:>9.1f} kPa  {:>5.2f} h".format(
        trench_name, mark, depth, bottom_pressure_pa(trench_name) / 1000.0,
        descent_hours(trench_name))


def main() -> None:
    names = ["Mariana", "Tonga", "Kuril", "Philippine", "Kermadec",
             "Izu-Ogasawara", "South Sandwich", "Puerto Rico", "Atlantis"]
    for name in names:
        print(format_row(name))
    known = [n for n in names if get_trench_depth(n) > 0]
    print("Average depth of {} trenches: {:.1f} m".format(
        len(known), average_depth(known)))


if __name__ == "__main__":
    main()

