MIN_ALTITUDE_FT = -1500
MAX_ALTITUDE_FT = 1000000

RULE_TABLE = (
    (1500, 'Pattern'),
    (10500, 'Light Aircraft'),
    (14500, 'Unpressurized Max'),
    (25500, 'Turboprop'),
    (35500, 'Domestic Jet'),
    (41500, 'International Jet'),
    (60500, 'Concorde'),
    (85500, 'Reconnaissance'),
)

TOP_RULE = 'Experimental'


def flight_level_rule(altitude_ft: int) -> str:
    """Return the operating rule that applies at the given pressure altitude."""
    if not isinstance(altitude_ft, int):
        raise TypeError('altitude must be an integer number of feet')
    if altitude_ft < MIN_ALTITUDE_FT or altitude_ft > MAX_ALTITUDE_FT:
        raise ValueError('altitude out of range: %d ft' % altitude_ft)
    for ceiling, rule in RULE_TABLE:
        if altitude_ft < ceiling:
            return rule
    return TOP_RULE


def feet_to_meters(altitude_ft: int) -> int:
    """Convert feet to whole metres using the exact factor 0.3048."""
    tenths_of_mm = altitude_ft * 3048
    return tenths_of_mm // 10000


def flight_level_label(altitude_ft: int) -> str:
    """Format an altitude either as a height in feet or as a flight level."""
    if altitude_ft < 1500:
        return '%d ft AGL/MSL' % altitude_ft
    return 'FL%03d' % (altitude_ft // 100)


def format_row(altitude_ft: int) -> str:
    return '%9d ft  %8d m  %-14s  %s' % (
        altitude_ft,
        feet_to_meters(altitude_ft),
        flight_level_label(altitude_ft),
        flight_level_rule(altitude_ft),
    )


def summarize(altitudes):
    counts = {}
    for altitude_ft in altitudes:
        rule = flight_level_rule(altitude_ft)
        counts[rule] = counts.get(rule, 0) + 1
    return counts


def main():
