    for altitude_ft in altitudes:
        print(format_row(altitude_ft))
    print()
    counts = summarize(altitudes)
    for rule in [name for _, name in RULE_TABLE] + [TOP_RULE]:
        if rule in counts:
            print('%-18s %d flight(s)' % (rule, counts[rule]))


if __name__ == '__main__':
