        raise ValueError("towing capacity cannot be negative")
    if capacity_lbs > MAX_RATED_CAPACITY:
        raise ValueError("towing capacity exceeds any rated truck")
    for limit, class_name in CLASS_LIMITS:
        if capacity_lbs < limit:
            return class_name
    return TOP_CLASS


def parse_capacity(entry) -> int:
    """Accept an int, or text such as '6,000 lbs' or '1.5 tons'."""
    if isinstance(entry, int):
        return entry
    text = entry.strip().lower().replace(",", "")
    if text.endswith("ton") or text.endswith("tons"):
        number = text.rstrip("tons ").strip()
        return int(round(float(number) * POUNDS_PER_TON))
    for suffix in ("lbs", "lb", "pounds"):
        if text.endswith(suffix):
            text = text[: -len(suffix)].strip()
            break
    return int(round(float(text)))


def classify_fleet(entries) -> dict:
    """Count how many capacities fall into each towing class."""
    counts = {name: 0 for _, name in CLASS_LIMITS}
    counts[TOP_CLASS] = 0
    for entry in entries:
        counts[vehicle_towing_class(parse_capacity(entry))] += 1
    return counts


def format_report(entries) -> str:
    capacities = [parse_capacity(entry) for entry in entries]
    counts = classify_fleet(capacities)
    lines = ["Fleet size: %d truck(s)" % len(capacities)]
    for name, count in counts.items():
        if count:
            lines.append("  %-12s %d" % (name, count))
    average = sum(capacities) // len(capacities)
    lines.append("Average capacity: %d lbs (%.1f tons)" % (average, average / POUNDS_PER_TON))
    heavy = sum(1 for cap in capacities if cap >= HEAVY_DUTY_THRESHOLD)
    lines.append("Class Five and above: %d truck(s)" % heavy)
    return "\n".join(lines)


def main() -> None:
    fleet = [
        1_800,
        "3,200 lbs",
        6_000,
        7_400,
        "5 tons",
        15_500,
        "9.5 tons",
        26_500,
        31_000,
    ]
    for entry in fleet:
        capacity = parse_capacity(entry)
        print("%6d lbs -> %s" % (capacity, vehicle_towing_class(capacity)))
    print()
    print(format_report(fleet))


if __name__ == "__main__":
    main()

