BAUD_RATES = {
    'Lunar': 85000,
    'Mars': 45000,
    'Jupiter': 25500,
    'Saturn': 15500,
    'Uranus': 8500,
    'Neptune': 4500,
    'Kuiper Belt': 2500,
    'Interstellar': 1200,
}

BITS_PER_BYTE = 8


def probe_baud_rate(region: str) -> int:
    """Return the maximum transmission rate in bits per second for a region."""
    if not isinstance(region, str):
        return 0
    return BAUD_RATES.get(region.strip(), 0)


def transmission_time(region: str, size_bytes: float) -> float:
    """Seconds needed to send size_bytes from the given region, or -1.0 if unknown."""
    rate = probe_baud_rate(region)
    if rate == 0:
        return -1.0
    if size_bytes < 0:
        raise ValueError("file size cannot be negative")
    return (size_bytes * BITS_PER_BYTE) / rate


def megabytes_to_bytes(megabytes: float) -> float:
    """Convert megabytes (decimal, as used in mission planning) to bytes."""
    return megabytes * 1000000


def format_duration(seconds: float) -> str:
    """Render a duration as days/hours/minutes/seconds."""
    if seconds < 0:
        return "n/a"
    total = int(round(seconds))
    days, total = divmod(total, 86400)
    hours, total = divmod(total, 3600)
    minutes, secs = divmod(total, 60)
    parts = []
    if days:
        parts.append(f"{days}d")
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    parts.append(f"{secs}s")
    return " ".join(parts)


def transfer_report(region: str, megabytes: float) -> str:
    """One-line summary of a downlink for a given payload size."""
    rate = probe_baud_rate(region)
    if rate == 0:
        return f"{region:<13} unknown region"
    seconds = transmission_time(region, megabytes_to_bytes(megabytes))
    return f"{region:<13} {rate:>6} bps   {megabytes:>6.1f} MB   {format_duration(seconds)}"


def main() -> None:
    payload_megabytes = 1500
    print(f"Downlink plan for a {payload_megabytes} MB payload")
    for region in BAUD_RATES:
        print(transfer_report(region, payload_megabytes))
    print(transfer_report('Andromeda', payload_megabytes))

    thumbnail_bytes = 65536
    print("\nThumbnail latency (64 KiB):")
    for region in ('Lunar', 'Saturn', 'Interstellar'):
        print(f"{region:<13} {format_duration(transmission_time(region, thumbnail_bytes))}")


if __name__ == '__main__':
    main()

