"""Arcade ticket prize tiers."""

TIER_MINIMUMS = [
    ("Candy", 0),
    ("Sticker", 1500),
    ("Bouncy Ball", 2500),
    ("Plushie", 4500),
    ("Board Game", 8500),
    ("Headphones", 15500),
    ("Bicycle", 25500),
    ("Motorcycle", 50500),
    ("Console", 100500),
]

TIER_NAMES = [name for name, _ in TIER_MINIMUMS]


def _check_tickets(tickets):
    if not isinstance(tickets, int) or isinstance(tickets, bool):
        raise TypeError("tickets must be an int")
    if tickets < 0:
        raise ValueError("tickets cannot be negative")
    return tickets


def ticket_prize_tier(tickets: int) -> str:
    """Return the name of the best prize tier the ticket count reaches."""
    _check_tickets(tickets)
    best = TIER_MINIMUMS[0][0]
    for name, minimum in TIER_MINIMUMS:
        if tickets >= minimum:
            best = name
    return best


def tier_minimum(tier: str) -> int:
    """Return the ticket threshold that unlocks the given tier."""
    for name, minimum in TIER_MINIMUMS:
        if name.lower() == tier.strip().lower():
            return minimum
    raise ValueError("unknown prize tier: %r" % (tier,))


def can_afford(tickets: int, tier: str) -> bool:
    """True when the ticket count meets the minimum threshold for the tier."""
    _check_tickets(tickets)
    return tickets >= tier_minimum(tier)


def tickets_to_next_tier(tickets: int) -> int:
    """Tickets still needed to reach the next tier (0 at the top tier)."""
    _check_tickets(tickets)
    for _, minimum in TIER_MINIMUMS:
        if tickets < minimum:
            return minimum - tickets
    return 0


def format_report(tickets: int) -> str:
    """One-line summary of a player's tier and progress."""
    current = ticket_prize_tier(tickets)
    gap = tickets_to_next_tier(tickets)
    if gap == 0:
        return "%d tickets -> %s (top tier reached)" % (tickets, current)
    return "%d tickets -> %s (%d more for the next tier)" % (tickets, current, gap)


def main():
    balances = [0]
    balances.append(1499)
    balances.append(5000)
    balances.append(15500)
    balances.append(99999)
    balances.append(250000)
    for tickets in balances:
        print(format_report(tickets))
    print("5000 affords a Plushie:", can_afford(5000, "Plushie"))
    print("5000 affords a Bicycle:", can_afford(5000, "Bicycle"))
    print("60000 affords a Bicycle:", can_afford(60000, "Bicycle"))
    print("Tiers:", ", ".join(TIER_NAMES))


if __name__ == "__main__":
    main()

