RIVER_LENGTHS_KM = {
    "Nile": 6650,
    "Amazon": 6400,
    "Yangtze": 6300,
    "Mississippi": 6275,
    "Yenisei": 5539,
    "Yellow": 5464,
    "Ob": 5410,
    "Amur": 4400,
}

LONG_RIVER_KM = 5000


def _normalize(river: str) -> str:
    """Accept sloppy user input such as ' amazon ' or 'YELLOW'."""
    return " ".join(str(river).split()).title()


def get_river_length_km(river: str) -> int:
    """Length of a major river in whole kilometres, or 0 if unknown."""
    return RIVER_LENGTHS_KM.get(_normalize(river), 0)


def total_length_km(rivers) -> int:
    """Sum of the lengths of every river in the given list."""
    return sum(get_river_length_km(name) for name in rivers)


def is_long_river(river: str) -> bool:
    """True for rivers reaching at least 5000 km."""
    return get_river_length_km(river) >= LONG_RIVER_KM


def drift_days(river: str, speed_kmh: float) -> float:
    """Days needed to drift the whole river at a constant speed."""
    length = get_river_length_km(river)
    if length == 0 or speed_kmh <= 0:
        return 0.0
    seconds_afloat = length / speed_kmh * 3600
    return seconds_afloat / 86400


def format_row(river: str) -> str:
    length = get_river_length_km(river)
    if length == 0:
        return "{:<12} {:>6}".format(_normalize(river), "unknown")
    mark = "major" if is_long_river(river) else ""
    return "{:<12} {:>4} km {}".format(_normalize(river), length, mark).rstrip()


def build_report(rivers) -> str:
    lines = [format_row(name) for name in rivers]
    total = total_length_km(rivers)
    lines.append("{:<12} {:>4} km total".format("", total) if total < 10000
                 else "{:<12} {:>5} km total".format("", total))
    return "\n".join(lines)


def main() -> None:
    requested = ["Amazon", "nile", "Yangtze", "Mississippi", "Amur", "Danube"]
    print(build_report(requested))
    print()
    for name in ("Nile", "Amazon", "Ob"):
        print("{:<12} {:>6.1f} days adrift at 5 km/h".format(
            _normalize(name), drift_days(name, 5.0)))
    print()
    print("Longest known:", max(RIVER_LENGTHS_KM, key=RIVER_LENGTHS_KM.get))
    print("All eight combined:", total_length_km(RIVER_LENGTHS_KM), "km")


if __name__ == "__main__":
    main()

