ITEM_PRICES = {
    'Health Potion': 1200,
    'Mana Potion': 1500,
    'Iron Sword': 3500,
    'Steel Shield': 5500,
    'Elven Bow': 8500,
    'Mithril Armor': 15000,
    'Dragon Helm': 25000,
    'Excalibur': 75000,
}

STARTING_GOLD = 10000
MERCHANT_STOCK_LIMIT = 100000


def get_item_cost(item_type: str) -> int:
    """Return the price of an item, or 0 if the merchant does not sell it."""
    if not isinstance(item_type, str):
        return 0
    return ITEM_PRICES.get(item_type.strip(), 0)


def total_cost(items: list) -> int:
    """Sum the price of every item in the shopping list."""
    return sum(get_item_cost(item) for item in items)


def purchase_items(gold: int, items: list) -> int:
    """Return the gold left after buying items, or -1 when unaffordable."""
    if gold < 0:
        return -1
    cost = total_cost(items)
    if cost > gold:
        return -1
    return gold - cost


def affordable_items(gold: int) -> list:
    """List the names of items that can be bought with the given gold."""
    return sorted(name for name, price in ITEM_PRICES.items() if price <= gold)


def format_price(amount: int) -> str:
    """Format a price, using a 'k' suffix for large amounts."""
    if amount >= 1000:
        return "{:,} gold".format(amount)
    return "%d gold" % amount


def price_catalogue() -> str:
    """Build a printable catalogue sorted from cheapest to most expensive."""
    lines = []
    for name, price in sorted(ITEM_PRICES.items(), key=lambda pair: pair[1]):
        stock = MERCHANT_STOCK_LIMIT // price
        lines.append("{:<14} {:>12}  (stock {})".format(name, format_price(price), stock))
    return "\n".join(lines)


def main() -> None:
    print(price_catalogue())
    print()
    basket = ['Iron Sword', 'Health Potion', 'Health Potion', 'Rusty Spoon']
    print("Basket cost:", format_price(total_cost(basket)))
    remaining = purchase_items(STARTING_GOLD, basket)
    print("Gold after purchase:", remaining)
    print("Still affordable:", ", ".join(affordable_items(remaining)))

    hero_gold = 1000000
    print("Rich hero buys everything:", purchase_items(hero_gold, list(ITEM_PRICES)))
    print("Broke hero buys Excalibur:", purchase_items(500, ['Excalibur']))
    print("Excalibur alone:", get_item_cost('Excalibur'))


if __name__ == '__main__':
    main()

