text_nat:
"""Network keepalive timeout configuration."""

_KEEPALIVE_MS = {
    "Local": 1500,
    "LAN": 3500,
    "WLAN": 5500,
    "WAN": 10500,
    "Satellite": 15500,
    "Deep Space": 45500,
    "Batch": 86400,
    "Archive": 604800,
}

ENVIRONMENTS = tuple(_KEEPALIVE_MS)

MAX_RETRY_BUDGET_MS = 1000000
BASE_SOCKET_BUFFER = 65536
MAX_SOCKET_BUFFER = 1048576
HIGH_LATENCY_MS = 10000


def get_keepalive_ms(environment: str) -> int:
    """Return the keepalive timeout in milliseconds for an environment."""
    if not isinstance(environment, str):
        raise TypeError("environment must be a string")
    return _KEEPALIVE_MS.get(environment.strip(), 0)


def socket_buffer_bytes(keepalive: int) -> int:
    """Pick a receive buffer size that can hold a full keepalive window."""
    buffer_size = BASE_SOCKET_BUFFER
    while keepalive > HIGH_LATENCY_MS and buffer_size < MAX_SOCKET_BUFFER:
        buffer_size *= 2
        keepalive //= 4
    return buffer_size


def retry_budget_ms(keepalive: int) -> int:
    """Allow three keepalive windows for retries, capped for sanity."""
    return min(keepalive * 3, MAX_RETRY_BUDGET_MS)


def classify(keepalive: int) -> str:
    """Name the interactivity band a keepalive window belongs to."""
    if keepalive == 0:
        return "unknown"
    if keepalive <= 5500:
        return "interactive"
    if keepalive <= 45500:
        return "tolerant"
    return "archival"


def build_config(environment: str) -> dict:
    """Format the timeout of one environment into a configuration mapping."""
    keepalive = get_keepalive_ms(environment)
    return {
        "environment": environment,
        "keepalive_ms": keepalive,
        "keepalive_us": keepalive * 1000,
        "keepalive_s": round(keepalive / 1000, 3),
