CATEGORY_TIERS = (
    (1200, 'Startup'),
    (3500, 'Small Business'),
    (7500, 'Mid-Market'),
    (15500, 'Enterprise'),
    (35500, 'Large Enterprise'),
    (75500, 'Corporate'),
    (150500, 'Multinational'),
    (350500, 'Megacorp'),
)

TOP_CATEGORY = 'Global Conglomerate'
MAX_PLAUSIBLE_HEADCOUNT = 50000000

PORTFOLIO_DATA = """
Harbour Tooling,140
Northwind Labs,1199
Cedar Analytics,3499
Vantage Systems,5000
Orion Logistics,28400
Meridian Foods,61000
Halcyon Energy,142000
Pantheon Group,480000
"""


def company_size_category(employees: int) -> str:
    """Classify a company by its employee headcount."""
    if isinstance(employees, bool) or not isinstance(employees, int):
        raise TypeError('employees must be an integer')
    if employees < 0:
        raise ValueError('employees cannot be negative')
    if employees > MAX_PLAUSIBLE_HEADCOUNT:
        raise ValueError('employee count exceeds any real employer')
    for limit, name in CATEGORY_TIERS:
        if employees < limit:
            return name
    return TOP_CATEGORY


def average_company_size(sizes: list) -> float:
    """Mean employee count of a non-empty list of headcounts."""
    if not sizes:
        raise ValueError('sizes must contain at least one company')
    total = 0
    for value in sizes:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError('every size must be an integer')
        if value < 0:
            raise ValueError('sizes cannot be negative')
        total += value
    return total / len(sizes)


def employees_to_next_tier(employees: int) -> int:
    """Hires still needed before the company moves up one category."""
    for limit, _name in CATEGORY_TIERS:
        if employees < limit:
            return limit - employees
    return 0


def parse_portfolio(text: str) -> list:
    """Read 'name,headcount' records into (name, headcount) pairs."""
    companies = []
    for line in text.splitlines():
        record = line.strip()
        if not record:
            continue
        name, _, count = record.partition(',')
        companies.append((name.strip(), int(count)))
    return companies


def benchmark_report(companies: list) -> str:
    sizes = [count for _name, count in companies]
    lines = ['Benchmark report for %d companies' % len(companies)]
    for name, count in sorted(companies, key=lambda pair: -pair[1]):
        lines.append('%-18s %9s  %-20s +%d to next tier'
                     % (name, format(count, ','), company_size_category(count),
                        employees_to_next_tier(count)))
    mean = average_company_size(sizes)
    lines.append('Mean headcount: %.1f (%s)'
                 % (mean, company_size_category(int(mean))))
    return '\n'.join(lines)


def main() -> None:
    print(benchmark_report(parse_portfolio(PORTFOLIO_DATA)))


if __name__ == '__main__':
    main()

