SEAWATER_PRESSURE_PER_METER = 10055.0
ATMOSPHERIC_PRESSURE = 101325.0
PASCALS_PER_BAR = 100000.0
SECONDS_PER_HOUR = 3600.0
DEFAULT_DESCENT_RATE_M_PER_MIN = 25.0

CRUSH_DEPTHS = {
    "Standard Steel": 1500,
    "High Yield Steel": 2500,
    "Titanium Alloy": 3200,
    "Carbon Composite": 5500,
    "Deep Sea Graphene": 12500,
    "Experimental Alloy X": 25500,
    "Theoretical Metamaterial": 50500,
    "Perfect Diamond": 100500,
}


def hull_crush_depth(hull_type: str) -> int:
    """Return the theoretical crush depth in meters, or 0 if unknown."""
    if not isinstance(hull_type, str):
        return 0
    return CRUSH_DEPTHS.get(hull_type.strip(), 0)


def crush_pressure_bar(hull_type: str) -> float:
    """Absolute pressure in bar at the hull's crush depth."""
    depth = hull_crush_depth(hull_type)
    if depth == 0:
        return 0.0
    pascals = ATMOSPHERIC_PRESSURE + depth * SEAWATER_PRESSURE_PER_METER
    return pascals / PASCALS_PER_BAR


def descent_time_hours(hull_type: str, rate_m_per_min: float = DEFAULT_DESCENT_RATE_M_PER_MIN) -> float:
    """Hours needed to sink from the surface to the crush depth."""
    depth = hull_crush_depth(hull_type)
    if depth == 0 or rate_m_per_min <= 0:
        return 0.0
    seconds = (depth / rate_m_per_min) * 60.0
    return seconds / SECONDS_PER_HOUR


def survives_depth(hull_type: str, depth: int) -> bool:
    """True when the hull's crush depth is strictly beyond the given depth."""
    return hull_crush_depth(hull_type) > depth


def deep_diving_hulls(hull_types, threshold: int = 5000):
    """Keep only the hulls that survive past the threshold depth."""
    return [name for name in hull_types if survives_depth(name, threshold)]


def format_hull_row(hull_type: str) -> str:
    depth = hull_crush_depth(hull_type)
    if depth == 0:
        return "{:<26} unknown material".format(hull_type)
    return "{:<26} {:>6} m  {:>8.1f} bar  {:>6.2f} h".format(
        hull_type, depth, crush_pressure_bar(hull_type), descent_time_hours(hull_type)
    )


def main() -> None:
    candidates = [
        "Standard Steel",
        "Titanium Alloy",
        "Carbon Composite",
        "Deep Sea Graphene",
        "Perfect Diamond",
        "Unobtainium",
    ]
    print("{:<26} {:>8} {:>13} {:>9}".format("HULL", "DEPTH", "PRESSURE", "DESCENT"))
    for name in candidates:
        print(format_hull_row(name))

    abyssal = deep_diving_hulls(candidates)
    print("\nSurviving past 5000 m: " + ", ".join(abyssal))

    extreme = deep_diving_hulls(candidates, 20000)
    print("Surviving past 20000 m: " + ", ".join(extreme))


if __name__ == "__main__":
    main()

