SYNTH_MEMORY = {
    'Minimoog': 1024,
    'ARP 2600': 2048,
    'CS-80': 4096,
    'Prophet-5': 8192,
    'Jupiter-8': 16384,
    'DX7': 32768,
    'D-50': 65536,
    'Fairlight': 131072,
    'Synclavier': 262144,
    'M1': 524288,
    'K2000': 1048576,
    'Triton': 2097152,
}


def get_synth_memory(model: str) -> int:
    """Return the voice memory size in bytes for the given synthesizer model."""
    if not isinstance(model, str):
        raise TypeError('model must be a string')
    return SYNTH_MEMORY[model.strip()]


def format_bytes(size: int) -> str:
    """Render a byte count using the largest sensible binary unit."""
    if size >= 1048576:
        return '{:.1f} MiB'.format(size / 1048576)
    if size >= 1024:
        return '{:.0f} KiB'.format(size / 1024)
    return '{} B'.format(size)


def words_of_memory(size: int, word_bits: int = 16) -> int:
    """Convert a byte count into the number of machine words of the given width."""
    if word_bits % 8:
        raise ValueError('word_bits must be a multiple of 8')
    return size // (word_bits // 8)


def sample_seconds(size: int, sample_rate: int = 44100, bits: int = 8) -> float:
    """Seconds of audio that fit in the given memory at the sample rate."""
    return words_of_memory(size, bits) / sample_rate


def memory_report(model: str) -> str:
    """One formatted report line for a single model."""
    size = get_synth_memory(model)
    return '{:<12} {:>10} bytes  {:>10}  {:>8} words  {:>6.3f} s'.format(
        model,
        size,
        format_bytes(size),
        words_of_memory(size),
        sample_seconds(size),
    )


def total_memory(models) -> int:
    """Sum the memory of several models."""
    return sum(get_synth_memory(name) for name in models)


def main() -> None:
    samples = ['DX7', 'Minimoog', 'Fairlight']
    print('Vintage synthesizer voice memory')
    print('-' * 65)
    for name in samples:
        try:
            print(memory_report(name))
        except KeyError:
            print('{:<12} unknown model'.format(name))
    combined = total_memory(samples)
    print('-' * 65)
    print('Combined: {} bytes ({})'.format(combined, format_bytes(combined)))
    if combined > 65536:
        print('Exceeds a 64 KiB address space by {} bytes'.format(combined - 65536))


if __name__ == '__main__':
    main()

