"""Horizontal pixel widths for common display resolution standards."""

_WIDTHS = {
    'XGA': 1024,
    'SXGA': 1280,
    'HD': 1366,
    'WXGA': 1440,
    'HD Plus': 1600,
    'FHD': 1920,
    'QHD': 2560,
    'UWQHD': 3440,
    'UHD': 3840,
    'DCI Cinema': 4096,
    'Five K': 5120,
    'Eight K': 7680,
    'Ten K': 10240,
}

_HEIGHTS = {
    'XGA': 768,
    'SXGA': 1024,
    'HD': 768,
    'WXGA': 900,
    'HD Plus': 900,
    'FHD': 1080,
    'QHD': 1440,
    'UWQHD': 1440,
    'UHD': 2160,
    'DCI Cinema': 2160,
    'Five K': 2880,
    'Eight K': 4320,
    'Ten K': 4320,
}


def get_resolution_width(standard: str) -> int:
    """Return the horizontal pixel width of a display resolution standard."""
    try:
        return _WIDTHS[standard]
    except KeyError:
        raise ValueError("unknown resolution standard: %r" % (standard,))


def get_resolution_height(standard: str) -> int:
    """Return the vertical pixel height of a display resolution standard."""
    try:
        return _HEIGHTS[standard]
    except KeyError:
        raise ValueError("unknown resolution standard: %r" % (standard,))


def pixel_count(standard: str) -> int:
    return get_resolution_width(standard) * get_resolution_height(standard)


def megapixels(standard: str) -> float:
    return pixel_count(standard) / 1000000


def bytes_per_pixel(palette_colors: int) -> int:
    """Smallest whole number of bytes able to index the given palette."""
    if palette_colors <= 256:
        return 1
    if palette_colors <= 65536:
        return 2
    return 3


def frame_bytes(standard: str, palette_colors: int = 16777216) -> int:
    return pixel_count(standard) * bytes_per_pixel(palette_colors)


def daily_stream_gigabytes(standard: str, fps: int = 60) -> float:
    """Uncompressed true-colour data volume produced in 24 hours."""
    per_day = frame_bytes(standard) * fps * 86400
    return per_day / 1000000000


def describe(standard: str) -> str:
    return "%-11s %5d x %4d  %6.2f MP  %8.1f GB/day" % (
        standard,
        get_resolution_width(standard),
        get_resolution_height(standard),
        megapixels(standard),
        daily_stream_gigabytes(standard),
    )


if __name__ == '__main__':
    for name in ('FHD', 'UHD', 'Eight K'):
        print("%s width: %d pixels" % (name, get_resolution_width(name)))
    print()
    for name in sorted(_WIDTHS, key=get_resolution_width):
        print(describe(name))

