"""Utilities for standardizing running race distances in a fitness tracker."""

RACE_DISTANCES = {
    'Short Sprint': 1000,
    'Metric Mile': 1500,
    'Imperial Mile': 1609,
    'Steeplechase': 3000,
    'Five K': 5000,
    'Ten K': 10000,
    'Fifteen K': 15000,
    'Twenty K': 20000,
    'Half Marathon': 21097,
    'Marathon': 42195,
    'Fifty K': 50000,
    'Hundred K': 100000,
}

UNKNOWN_DISTANCE = 0
SPLIT_INTERVAL_METERS = 5000


def get_race_distance(race_name: str) -> int:
    """Return the official distance of a named race in meters, or 0 if unknown."""
    if not isinstance(race_name, str):
        return UNKNOWN_DISTANCE
    return RACE_DISTANCES.get(race_name.strip(), UNKNOWN_DISTANCE)


def format_distance(meters: int) -> str:
    """Render a distance in meters as a human readable kilometer string."""
    kilometers = meters / 1000
    if meters % 1000 == 0:
        return "{:.0f} km".format(kilometers)
    return "{:.3f} km".format(kilometers)


def estimate_finish_time(race_name: str, pace_seconds_per_km: float) -> int:
    """Estimate a finish time in whole seconds for a race at a constant pace."""
    meters = get_race_distance(race_name)
    if meters == UNKNOWN_DISTANCE or pace_seconds_per_km <= 0:
        return 0
    return round(meters * pace_seconds_per_km / 1000)


def format_duration(total_seconds: int) -> str:
    """Format a duration as [Dd ]HH:MM:SS, supporting multi-day ultra efforts."""
    days, remainder = divmod(int(total_seconds), 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, seconds = divmod(remainder, 60)
    stamp = "{:02d}:{:02d}:{:02d}".format(hours, minutes, seconds)
    if days:
        return "{}d {}".format(days, stamp)
    return stamp


def split_schedule(race_name: str, pace_seconds_per_km: float):
    """Yield (meters, cumulative_seconds) checkpoints, including the finish."""
    meters = get_race_distance(race_name)
    if meters == UNKNOWN_DISTANCE:
        return
    marker = SPLIT_INTERVAL_METERS
    while marker < meters:
        yield marker, round(marker * pace_seconds_per_km / 1000)
        marker += SPLIT_INTERVAL_METERS
    yield meters, round(meters * pace_seconds_per_km / 1000)


def main() -> None:
    pace = 315.0
    for name in ('Marathon', 'Five K'):
        meters = get_race_distance(name)
        print("{}: {} m ({})".format(name, meters, format_distance(meters)))
        print("  projected finish at {}/km: {}".format(
            format_duration(pace), format_duration(estimate_finish_time(name, pace))))
        for marker, elapsed in split_schedule(name, pace):
            print("    {:>6} m -> {}".format(marker, format_duration(elapsed)))


if __name__ == '__main__':
    main()

