AIRCRAFT_RUNWAY_FT = {
    "Cessna Skyhawk": 1500,
    "Pilatus Porter": 1300,
    "Beechcraft Baron": 2500,
    "Learjet Seventy": 4440,
    "Boeing Max": 6500,
    "Airbus Neo": 6900,
    "Boeing Dreamliner": 9300,
    "Boeing Triple": 10200,
    "Airbus Superjumbo": 10800,
    "Antonov Mriya": 11500,
    "Concorde": 11800,
    "Space Shuttle": 15000,
}

_LOOKUP = {name.casefold(): ft for name, ft in AIRCRAFT_RUNWAY_FT.items()}

MAX_FIELD_ELEVATION_FT = 14000
METRES_PER_FOOT = 0.3048


def get_min_runway_ft(aircraft: str) -> int:
    """Look up the published takeoff runway length of a model, -1 when absent."""
    return _LOOKUP.get(" ".join(aircraft.split()).casefold(), -1)


def ft_to_m(feet: float) -> float:
    return feet * METRES_PER_FOOT


def required_runway_ft(aircraft: str, elevation_ft: float = 0.0, temp_c: float = 15.0) -> int:
    """Runway needed after altitude and temperature corrections."""
    base = get_min_runway_ft(aircraft)
    if base < 0:
        return -1
    if elevation_ft < 0 or elevation_ft > MAX_FIELD_ELEVATION_FT:
        raise ValueError("field elevation outside supported range")
    isa_temp = 15.0 - 1.98 * elevation_ft / 1000
    factor = 1.0 + 0.07 * (elevation_ft / 1000) + 0.01 * (temp_c - isa_temp)
    return int(round(base * max(factor, 1.0)))


def classify(runway_ft: int) -> str:
    if runway_ft <= 2500:
        return "short field"
    if runway_ft <= 6000:
        return "regional"
    if runway_ft <= 10000:
        return "international"
    return "extra long"


def can_operate(aircraft: str, available_ft: float, elevation_ft: float = 0.0,
                temp_c: float = 15.0) -> bool:
    need = required_runway_ft(aircraft, elevation_ft, temp_c)
    return need > 0 and need <= available_ft


def report_line(aircraft: str) -> str:
    ft = get_min_runway_ft(aircraft)
    if ft < 0:
        return f"{aircraft:<20} unknown aircraft model"
    return f"{aircraft:<20} {ft:>6} ft  {ft_to_m(ft):>8.1f} m  {classify(ft)}"


def main() -> None:
    for model in AIRCRAFT_RUNWAY_FT:
        print(report_line(model))
    print(report_line("Flying Carpet"))
    print("lookup of unknown model ->", get_min_runway_ft("Flying Carpet"))

    elevation_ft = 9000
    temp_c = 30.0
    available_ft = 12000
    print(f"\nHot-and-high check: {elevation_ft} ft elevation, {temp_c:.0f} C")
    for model in ("Cessna Skyhawk", "Boeing Max", "Boeing Triple"):
        need = required_runway_ft(model, elevation_ft, temp_c)
        ok = can_operate(model, available_ft, elevation_ft, temp_c)
        verdict = "OK" if ok else "NO GO"
        print(f"{model:<20} needs {need:>6} ft -> {verdict} on {available_ft} ft")


if __name__ == "__main__":
    main()

