_TIER_MIN_VOLUME = {
    "Micro Niche": 1000,
    "Niche": 2500,
    "Low": 5000,
    "Medium Low": 10000,
    "Medium": 25000,
    "Medium High": 50000,
    "High": 100000,
    "Very High": 250000,
    "Viral": 500000,
    "Trending": 1000000,
    "Global": 5000000,
    "Universal": 10000000,
}


def get_min_search_volume(tier: str) -> int:
    """Return the minimum monthly search volume for a competition tier."""
    if not isinstance(tier, str):
        raise ValueError("tier must be a string, got %r" % (tier,))
    key = " ".join(tier.split()).title()
    if key not in _TIER_MIN_VOLUME:
        raise ValueError("Unsupported competition tier: %r" % (tier,))
    return _TIER_MIN_VOLUME[key]


def classify_volume(volume: int) -> str:
    """Return the highest tier whose minimum threshold the volume reaches."""
    if volume < 1000:
        raise ValueError("volume below the lowest supported tier: %r" % (volume,))
    match = None
    for tier, minimum in sorted(_TIER_MIN_VOLUME.items(), key=lambda item: item[1]):
        if volume >= minimum:
            match = tier
    return match


def format_volume(volume: int) -> str:
    """Render a search volume in compact marketing notation."""
    if volume >= 1000000:
        return "{:.1f}M".format(volume / 1000000)
    if volume >= 10000:
        return "{:d}K".format(volume // 1000)
    return "{:,}".format(volume)


def tier_report(tiers) -> str:
    """Build a text report of thresholds for the requested tiers."""
    lines = []
    for tier in tiers:
        minimum = get_min_search_volume(tier)
        share = minimum / 10000000
        lines.append(
            "{:<12} min {:>10,} searches/mo  ({:>6}, {:.2%} of Universal)".format(
                tier, minimum, format_volume(minimum), share
            )
        )
    return "\n".join(lines)


def main() -> None:
    for tier in ("Niche", "Trending"):
        print("{}: {}".format(tier, get_min_search_volume(tier)))
    print()
    print(tier_report(["Micro Niche", "Medium", "High", "Global"]))
    print()
    measured_volumes = (
        2500,
        86400,
        65536,
        4200000,
    )
    for volume in measured_volumes:
        print("{:>9,} searches/mo -> {}".format(volume, classify_volume(volume)))


if __name__ == "__main__":
    main()

