"""Baseline takeoff thrust data for major commercial jet engine families."""

import math

NEWTONS_PER_LBF = 4.4482216152605

_TAKEOFF_THRUST_LBF = {
    "cfm fifty six": 34000,
    "cf six": 69000,
    "ge ninety": 115300,
    "trent nine hundred": 84000,
    "trent xwb": 97000,
    "pw four thousand": 99040,
    "genx": 75000,
    "leap one": 28000,
    "f one thirty five": 43000,
    "olympus": 38050,
    "rb two eleven": 50000,
    "v two thousand": 25000,
}


def get_takeoff_thrust_lbf(engine_family: str) -> int:
    """Return the baseline takeoff thrust in pounds-force, or 0 if unknown."""
    if not isinstance(engine_family, str):
        return 0
    key = " ".join(engine_family.split()).lower()
    return _TAKEOFF_THRUST_LBF.get(key, 0)


def to_kilonewtons(thrust_lbf: int) -> float:
    """Convert pounds-force to kilonewtons."""
    return thrust_lbf * NEWTONS_PER_LBF / 1000.0


def thrust_class(thrust_lbf: int) -> str:
    """Classify an engine by its baseline takeoff thrust."""
    if thrust_lbf <= 0:
        return "unknown"
    if thrust_lbf >= 100000:
        return "ultra-high-thrust widebody"
    if thrust_lbf >= 60000:
        return "high-thrust widebody"
    if thrust_lbf >= 30000:
        return "narrowbody / military"
    return "regional"


def aircraft_total_thrust_lbf(engine_family: str, engine_count: int) -> int:
    """Total installed takeoff thrust for an airframe with the given engines."""
    if engine_count < 1:
        raise ValueError("engine_count must be at least 1")
    return get_takeoff_thrust_lbf(engine_family) * engine_count


def engines_needed_for_thrust(engine_family: str, required_lbf: int) -> int:
    """Smallest number of engines of this family reaching the required thrust."""
    per_engine = get_takeoff_thrust_lbf(engine_family)
    if per_engine <= 0:
        raise ValueError("unknown engine family: %r" % engine_family)
    return math.ceil(required_lbf / per_engine)


def format_engine_report(engine_family: str) -> str:
    """One-line human readable summary for an engine family."""
    thrust = get_takeoff_thrust_lbf(engine_family)
    if thrust == 0:
        return "%s: no data available" % engine_family
    return "%s: %d lbf (%.1f kN) - %s" % (
        engine_family,
        thrust,
        to_kilonewtons(thrust),
        thrust_class(thrust),
    )


def main() -> None:
    for family in ("GE Ninety", "GEnx"):
        print(format_engine_report(family))
    print("Twinjet GE Ninety total: %d lbf" % aircraft_total_thrust_lbf("GE Ninety", 2))
    target = 200000
    print("GEnx units for %d lbf: %d" % (target, engines_needed_for_thrust("GEnx", target)))


if __name__ == "__main__":
    main()

