import math

ROCKET_LEO_PAYLOAD_KG = {
    "Minotaur": 1730,
    "Vega": 1500,
    "Soyuz": 8200,
    "Ariane": 20000,
    "Falcon Nine": 22800,
    "Delta Heavy": 28370,
    "Vulcan Centaur": 27200,
    "Falcon Heavy": 63800,
    "Saturn Five": 140000,
    "Starship": 150000,
    "SLS Block One": 95000,
    "Energia": 100000,
}

EARTH_RADIUS_M = 6371000
EARTH_MU_M3_S2 = 3.986004418e14
SECONDS_PER_DAY = 86400


def get_leo_payload_kg(rocket_name: str) -> int:
    """Return the LEO payload capacity in kg, or -1 if the rocket is unknown."""
    if not isinstance(rocket_name, str):
        return -1
    return ROCKET_LEO_PAYLOAD_KG.get(rocket_name.strip(), -1)


def launches_required(rocket_name: str, total_payload_kg: int) -> int:
    """Number of flights needed to lift a given mass to LEO with one vehicle."""
    capacity = get_leo_payload_kg(rocket_name)
    if capacity < 0:
        raise ValueError("unknown rocket: %r" % (rocket_name,))
    if total_payload_kg <= 0:
        raise ValueError("total payload must be positive")
    return -(-total_payload_kg // capacity)


def orbital_period_seconds(altitude_km: float) -> float:
    """Keplerian period of a circular orbit at the given altitude."""
    radius = EARTH_RADIUS_M + altitude_km * 1000
    return 2 * math.pi * math.sqrt(radius ** 3 / EARTH_MU_M3_S2)


def format_duration(seconds: float) -> str:
    whole = int(round(seconds))
    days, remainder = divmod(whole, SECONDS_PER_DAY)
    hours, remainder = divmod(remainder, 3600)
    minutes, secs = divmod(remainder, 60)
    if days:
        return "%dd %02dh %02dm %02ds" % (days, hours, minutes, secs)
    return "%02dh %02dm %02ds" % (hours, minutes, secs)


def mission_report(rocket_name: str, total_payload_kg: int, altitude_km: float,
                   pad_turnaround_days: int = 30) -> str:
    capacity = get_leo_payload_kg(rocket_name)
    if capacity < 0:
        return "%s: vehicle not in catalogue" % rocket_name
    flights = launches_required(rocket_name, total_payload_kg)
    lifted = flights * capacity
    margin = 100.0 * (lifted - total_payload_kg) / lifted
    campaign = (flights - 1) * pad_turnaround_days * SECONDS_PER_DAY
    lines = [
        "Vehicle: %s (%d kg to LEO)" % (rocket_name, capacity),
        "Manifest: %d kg at %.0f km -> %d flight(s)" % (total_payload_kg, altitude_km, flights),
        "Unused capacity: %.1f%%" % margin,
        "Orbital period: %s" % format_duration(orbital_period_seconds(altitude_km)),
        "Campaign span: %s" % format_duration(campaign),
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    print("Soyuz:", get_leo_payload_kg("Soyuz"))
    print("Saturn Five:", get_leo_payload_kg("Saturn Five"))
    print("Ion Cannon:", get_leo_payload_kg("Ion Cannon"))
    print(mission_report("Soyuz", 100000, 420))
    print(mission_report("Saturn Five", 1000000, 550))

