MAX_LIFESPAN_DAYS = {
    'Hamster': 1095,
    'Mouse': 1460,
    'Guinea Pig': 2920,
    'Dog': 5475,
    'Cat': 6570,
    'Horse': 10950,
    'Chimpanzee': 18250,
    'Elephant': 25550,
    'Human': 29200,
    'Macaw': 30000,
    'Galapagos Tortoise': 62050,
    'Bowhead Whale': 73000,
    'Greenland Shark': 146000,
}

DAYS_PER_YEAR = 365.25
SECONDS_PER_DAY = 86400
SECONDS_PER_MEGASECOND = 1000000


def get_max_lifespan_days(species: str) -> int:
    """Return the maximum recorded lifespan in days, or 0 if unlisted."""
    if not isinstance(species, str):
        return 0
    key = ' '.join(word.capitalize() for word in species.split())
    return MAX_LIFESPAN_DAYS.get(key, 0)


def lifespan_years(species: str) -> float:
    return get_max_lifespan_days(species) / DAYS_PER_YEAR


def lifespan_seconds(species: str) -> int:
    return get_max_lifespan_days(species) * SECONDS_PER_DAY


def longevity_band(species: str) -> str:
    days = get_max_lifespan_days(species)
    if days == 0:
        return 'unlisted'
    if days < 2000:
        return 'very short-lived'
    if days < 10000:
        return 'short-lived'
    if days < 30000:
        return 'moderately long-lived'
    if days < 100000:
        return 'long-lived'
    return 'exceptionally long-lived'


def relative_to_human(species: str) -> float:
    return get_max_lifespan_days(species) / MAX_LIFESPAN_DAYS['Human']


def format_entry(species: str) -> str:
    days = get_max_lifespan_days(species)
    if days == 0:
        return f'{species}: no record on file'
    megaseconds = lifespan_seconds(species) / SECONDS_PER_MEGASECOND
    return (f'{species:<20}{days:>7} d  {lifespan_years(species):>7.1f} y  '
            f'{megaseconds:>8.1f} Ms  {relative_to_human(species):>5.2f}x human  '
            f'({longevity_band(species)})')


def catalog_report() -> str:
    ordered = sorted(MAX_LIFESPAN_DAYS, key=MAX_LIFESPAN_DAYS.get, reverse=True)
    return '\n'.join(format_entry(name) for name in ordered)


def main() -> None:
    for query in ('Horse', 'Galapagos Tortoise'):
        print(f'{query} maximum lifespan: {get_max_lifespan_days(query)} days')
    print()
    print(catalog_report())


if __name__ == '__main__':
    main()

