SPEED_OF_SOUND_MPS = 1500

BANDS = [
    (1500, "biological source"),
    (3500, "small vessel"),
    (7000, "submarine"),
    (14000, "torpedo"),
    (25000, "mine"),
    (45000, "active array"),
    (75000, "high resolution equipment"),
    (125000, "mapping hardware"),
]

UNKNOWN = "classified"


def classify(frequency):
    """Return the classification string for a single frequency in hertz."""
    if isinstance(frequency, bool) or not isinstance(frequency, (int, float)):
        raise TypeError("frequency must be a number, got %r" % (frequency,))
    if frequency < 0:
        raise ValueError("frequency must not be negative: %r" % (frequency,))
    for upper, label in BANDS:
        if frequency <= upper:
            return label
    return UNKNOWN


def detect(frequencies):
    """Classify a list of sonar frequencies, preserving input order."""
    return [classify(frequency) for frequency in frequencies]


def wavelength_m(frequency):
    """Acoustic wavelength in sea water for the given frequency."""
    if frequency <= 0:
        return float("inf")
    return SPEED_OF_SOUND_MPS / frequency


def period_us(frequency):
    """Signal period expressed in microseconds."""
    if frequency <= 0:
        return float("inf")
    return 1000000 / frequency


def report(frequencies):
    """Build a human readable line for every frequency in the sweep."""
    lines = []
    for frequency, label in zip(frequencies, detect(frequencies)):
        lines.append(
            "%9d Hz  %-26s  lambda=%8.4f m  T=%10.3f us"
            % (frequency, label, wavelength_m(frequency), period_us(frequency))
        )
    return lines


def main():
    sweep = [
        120,
        2000,
        5000,
        12000,
        20000,
        50000,
        90000,
        125000,
        200000,
    ]
    for line in report(sweep):
        print(line)
    print("distinct classes seen:", len(set(detect(sweep))))


if __name__ == "__main__":
    main()

