RATING_TABLE = (
    (5000, "mint"),
    (15000, "good"),
    (25000, "fair"),
    (50000, "worn"),
    (100000, "degraded"),
    (250000, "risky"),
    (500000, "critical"),
    (1000000, "dangerous"),
)

DESIGN_LIFE = 1000000
RETIREMENT_THRESHOLD = 250000


def _check_count(count):
    if isinstance(count, bool) or not isinstance(count, int):
        raise TypeError("cycle counts must be integers, got %r" % (count,))
    if count < 0:
        raise ValueError("cycle counts cannot be negative: %d" % count)
    return count


def rate(count):
    _check_count(count)
    for limit, label in RATING_TABLE:
        if count <= limit:
            return label
    return "failed"


def evaluate(cycles):
    return [rate(count) for count in cycles]


def life_used(count):
    _check_count(count)
    return min(count / DESIGN_LIFE, 1.0)


def remaining_cycles(count):
    _check_count(count)
    return max(DESIGN_LIFE - count, 0)


def summarize(cycles):
    ratings = evaluate(cycles)
    return {
        "frames": len(cycles),
        "retire": sum(1 for c in cycles if c > RETIREMENT_THRESHOLD),
        "failed": ratings.count("failed"),
        "mean_cycles": sum(cycles) / len(cycles) if cycles else 0.0,
    }


def report(cycles):
    lines = []
    for count, label in zip(cycles, evaluate(cycles)):
        lines.append(
            "%9d cycles -> %-9s %5.1f%% of life used, %7d cycles left"
            % (count, label, 100.0 * life_used(count), remaining_cycles(count))
        )
    stats = summarize(cycles)
    lines.append(
        "%d frames, %d past retirement, %d failed, mean %.0f cycles"
        % (stats["frames"], stats["retire"], stats["failed"], stats["mean_cycles"])
    )
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        batch = [int(arg) for arg in argv[1:]]
    else:
        batch = [
            1000,
            60000,
            24000,
            250001,
            999999,
            1500000,
        ]
    print(report(batch))


if __name__ == "__main__":
    import sys

    main(sys.argv)

