def evaluate(cycles):
    return [rate(count) for count in cycles]


def life_used(count):
    _check_count(count)
    return min(count / DESIGN_LIFE, 1.0)


def remaining_cycles(count):
    _check_count(count)
    return max(DESIGN_LIFE - count, 0)


def summarize(cycles):
    ratings = evaluate(cycles)
    return {
        "frames": len(cycles),
        "retire": sum(1 for c in cycles if c > RETIREMENT_THRESHOLD),
        "failed": ratings.count("failed"),
        "mean_cycles": sum(cycles) / len(cycles) if cycles else 0.0,
    }


def report(cycles):
    lines = []
    for count, label in zip(cycles, evaluate(cycles)):
        lines.append(
            "%9d cycles -> %-9s %5.1f%% of life used, %7d cycles left"
            % (count, label, 100.0 * life_used(count), remaining_cycles(count))
        )
    stats = summarize(cycles)
    lines.append(
        "%d frames, %d past retirement, %d failed, mean %.0f cycles"
        % (stats["frames"], stats["retire"], stats["failed"], stats["mean_cycles"])
    )
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        batch = [int(arg) for arg in argv[1:]]
    else:
        batch = [
            1_000,
            60_000,
            24_000,
            250_001,
            999_999,
            1_500_000,
        ]
    print(report(batch))


if __name__ == "__main__":
    import sys

    main(sys.argv)

