CLASS_LIMITS = (
    (2500, "m class"),
    (3500, "k class"),
    (5000, "g class"),
    (6000, "f class"),
    (7500, "a class"),
    (10000, "b class"),
    (25000, "o class"),
    (50000, "wr class"),
)
EXOTIC_CLASS = "exotic"


def classify(temperature):
    """Return the spectral class name for a single temperature in Kelvin."""
    for limit, name in CLASS_LIMITS:
        if temperature <= limit:
            return name
    return EXOTIC_CLASS


def parse_temperature(text):
    """Convert a textual temperature such as '30 000 K' or '1.2e4' to a number."""
    cleaned = text.strip().replace(",", "").replace(" ", "")
    if cleaned.upper().endswith("K"):
        cleaned = cleaned[:-1]
    value = float(cleaned)
    if value.is_integer():
        return int(value)
    return value


def validate(temperature):
    if not isinstance(temperature, (int, float)):
        raise TypeError("temperature must be a number, got %r" % (temperature,))
    if temperature <= 0:
        raise ValueError("temperature must be above absolute zero: %r" % (temperature,))
    return temperature


def spectral(temperatures):
    """Map a list of surface temperatures in Kelvin to spectral class names."""
    return [classify(validate(t)) for t in temperatures]


def peak_wavelength_nm(temperature):
    """Wien's displacement law: wavelength of peak emission, in nanometres."""
    return WIEN_CONSTANT_NM_K / validate(temperature)


def describe(temperature):
    name = classify(validate(temperature))
    peak = peak_wavelength_nm(temperature)
    if temperature > 50000:
        note = "hotter than any Wolf-Rayet star"
    elif temperature > 10000:
        note = "ultraviolet-dominated"
    else:
