        raise ValueError("pressure readings cannot be negative: %r" % (pressure,))
    for limit, status in STATUS_LIMITS:
        if pressure <= limit:
            return status
    return RUPTURE_STATUS


def monitor(pressures):
    return [classify(pressure) for pressure in pressures]


