_THRESHOLDS = [
    (1000, "pocket park"),
    (5000, "neighborhood park"),
    (15000, "community park"),
    (40000, "district park"),
    (100000, "regional park"),
    (250000, "nature reserve"),
    (500000, "state park"),
    (1000000, "national park"),
]

LARGEST_CATEGORY = "mega reserve"


def categorize(area):
    """Classify a park by its total area in square meters."""
    if isinstance(area, bool) or not isinstance(area, (int, float)):
        raise TypeError("area must be a number of square meters")
    if area != area or area < 0:
        raise ValueError("area must be a non-negative number")
    for limit, name in _THRESHOLDS:
        if area < limit:
            return name
    return LARGEST_CATEGORY


def to_hectares(area):
    """Convert square meters to hectares (1 ha = 10000 m2)."""
    return area / 10000


def next_tier_gap(area):
    """Square meters still needed to reach the next larger category."""
    for limit, _name in _THRESHOLDS:
        if area < limit:
            return limit - area
    return 0


def format_row(name, area):
    category = categorize(area)
    gap = next_tier_gap(area)
    growth = "-" if gap == 0 else "{:,.0f} m2".format(gap)
    return "{:<18}{:>12,.0f} m2{:>11.2f} ha  {:<18}{:>14}".format(
        name, area, to_hectares(area), category, growth)


def summarize(parks):
    """Return total area and a count of parks per category."""
    counts = {}
    total = 0
    for _name, area in parks:
        counts[categorize(area)] = counts.get(categorize(area), 0) + 1
        total += area
    return total, counts


def main():
    parks = [
        ("Corner Green", 620),
        ("Maple Commons", 4200),
        ("Riverbend", 30000),
        ("Hillcrest Fields", 65536),
        ("Cedar Marsh", 250000),
        ("Northern Wilds", 1250000),
    ]
    print("{:<18}{:>15}{:>14}  {:<18}{:>14}".format(
        "Park", "Area", "Hectares", "Category", "To next tier"))
    for name, area in parks:
        print(format_row(name, area))
    total, counts = summarize(parks)
    print("\nTotal area: {:,.0f} m2 ({:.2f} ha)".format(total, to_hectares(total)))
    for category in sorted(counts, key=lambda c: counts[c], reverse=True):
        print("  {:<18}{}".format(category, counts[category]))


if __name__ == "__main__":
    main()

