TIERS = [
    (1000, "home recipe"),
    (5000, "boutique bakery"),
    (15000, "local bakery"),
    (40000, "neighborhood supplier"),
    (100000, "town supplier"),
    (250000, "regional factory"),
    (500000, "state distributor"),
    (1000000, "national brand"),
]
TOP_LABEL = "international brand"
POUNDS_PER_TON = 2000
TRUCK_CAPACITY = 40000
SACK_WEIGHT = 50


def validate(weight):
    if isinstance(weight, bool) or not isinstance(weight, (int, float)):
        raise TypeError("flour usage must be a number")
    if weight < 0:
        raise ValueError("flour usage cannot be negative")
    return weight


def evaluate(weight):
    validate(weight)
    for limit, label in TIERS:
        if weight < limit:
            return label
    return TOP_LABEL


def annual_pounds(weight):
    return validate(weight) * 12


def annual_tons(weight):
    return annual_pounds(weight) / POUNDS_PER_TON


def truckloads(weight):
    pounds = validate(weight)
    full, remainder = divmod(pounds, TRUCK_CAPACITY)
    return int(full) + (1 if remainder else 0)


def sacks(weight):
    return validate(weight) / SACK_WEIGHT


def pounds_to_next_tier(weight):
    validate(weight)
    for limit, _label in TIERS:
