TIERS = (
    (1000, "personal study"),
    (5000, "reading room"),
    (15000, "local branch"),
    (40000, "town library"),
    (100000, "city archive"),
    (250000, "regional repository"),
    (500000, "state library"),
    (1000000, "national archive"),
)
LARGEST_LABEL = "global repository"

PAGES_PER_BOOK = 250
BYTES_PER_PAGE = 65536
BYTES_PER_MEGABYTE = 1048576
PAGES_PER_SECOND = 2.0
SECONDS_PER_DAY = 86400


def normalize_count(value):
    """Turn user input ("12,500", " 2000 ", 42) into a non-negative integer."""
    if isinstance(value, bool):
        raise TypeError("book count must be a number, not a boolean")
    if isinstance(value, str):
        cleaned = value.strip().replace(",", "").replace("_", "")
        count = int(cleaned)
    else:
        count = int(value)
    if count < 0:
        raise ValueError("book count cannot be negative")
    return count


def classify(books):
    """Name the kind of library implied by its physical book count."""
    count = normalize_count(books)
    for limit, label in TIERS:
        if count < limit:
            return label
    return LARGEST_LABEL


def books_until_next_tier(books):
    """How many more books before the classification changes (None at the top)."""
    count = normalize_count(books)
    for limit, _label in TIERS:
        if count < limit:
            return limit - count
    return None


def digitization_estimate(books):
    """Rough scanning workload for a collection: megabytes and days of work."""
    count = normalize_count(books)
    pages = count * PAGES_PER_BOOK
    megabytes = pages * BYTES_PER_PAGE / BYTES_PER_MEGABYTE
    days = pages / PAGES_PER_SECOND / SECONDS_PER_DAY
    return megabytes, days


def format_report(books):
    count = normalize_count(books)
    label = classify(count)
    megabytes, days = digitization_estimate(count)
    gap = books_until_next_tier(count)
    if gap is None:
        growth = "already in the largest tier"
    else:
        growth = "{} books to the next tier".format(gap)
    return "{:>9,} books -> {:<20} | {:10.1f} MB scanned, {:6.2f} days | {}".format(
        count, label, megabytes, days, growth
    )


def main():
    samples = [0, 999, "12,500"]
    samples.append(39999)
    samples.append(250000)
    samples.append(4000000)
    for sample in samples:
        print(format_report(sample))


if __name__ == "__main__":
    main()

