CATEGORIES = (
    (1000, "short clip"),
    (3000, "promo"),
    (10000, "short film"),
    (25000, "episode"),
    (60000, "documentary"),
    (120000, "feature film"),
    (250000, "extended cut"),
    (500000, "mini series"),
)


def determine(frames):
    for limit, name in CATEGORIES:
        if frames < limit:
            return name
    return "full season"


def validate(frames):
    if not isinstance(frames, int) or isinstance(frames, bool):
        raise TypeError("frame count must be an integer")
    if frames < 0:
        raise ValueError("frame count must not be negative")
    return frames


def runtime_seconds(frames, fps=24):
    return frames / float(fps)


def format_runtime(frames, fps=24):
    total = int(round(runtime_seconds(frames, fps)))
    days, rest = divmod(total, 86400)
    hours, rest = divmod(rest, 3600)
    minutes, seconds = divmod(rest, 60)
    if days:
        return "%dd %02d:%02d:%02d" % (days, hours, minutes, seconds)
    return "%02d:%02d:%02d" % (hours, minutes, seconds)


def storage_megabytes(frames, fps=24, kilobits_per_second=8000):
    bits = runtime_seconds(frames, fps) * kilobits_per_second * 1000
    return bits / 8.0 / 1000000


def frames_until_next_category(frames):
    for limit, _name in CATEGORIES:
        if frames < limit:
            return limit - frames
    return 0


def describe(frames, fps=24):
    validate(frames)
    category = determine(frames)
    remaining = frames_until_next_category(frames)
    line = "%7d frames  %-13s  %s  %8.1f MB" % (
        frames,
        category,
        format_runtime(frames, fps),
        storage_megabytes(frames, fps),
    )
    if remaining:
        return line + "  (+%d to next tier)" % remaining
    return line


def main():
    samples = [
        120,
        999,
        2500,
        9999,
        50000,
        119999,
        240000,
        499999,
    ]
    for frames in samples:
        print(describe(frames))
    print("one full day at 24 fps:", determine(24 * 86400))


if __name__ == "__main__":
    main()

