from math import ceil

THRESHOLDS = (
    (1000, "snow patch"),
    (5000, "micro glacier"),
    (10000, "cirque glacier"),
    (25000, "valley glacier"),
    (50000, "mountain glacier"),
    (100000, "ice cap"),
    (250000, "regional ice field"),
    (500000, "continental sheet"),
)

ABLATION_M_PER_SECOND = 2.3e-8
MAX_MEAN_THICKNESS_M = 400.0


def measure(area):
    """Classify a glacial ice body by its surface area in square meters."""
    if area < 0:
        raise ValueError("surface area cannot be negative")
    for limit, label in THRESHOLDS:
        if area < limit:
            return label
    return "polar mass"


def area_in_km2(area):
    """Convert a surface area from square meters to square kilometers."""
    return area / 1000000


def mean_thickness(area):
    """Rough mean ice thickness: grows with extent, capped for large bodies."""
    return min(2.0 + area / 10000, MAX_MEAN_THICKNESS_M)


def ice_volume(area):
    """Estimated ice volume in cubic meters."""
    return area * mean_thickness(area)


def raster_tiles(area):
    """Number of 256x256 one-meter-pixel tiles needed to map the body."""
    return ceil(area / 65536)


def daily_ablation(area):
    """Volume of ice lost per day at the reference ablation rate."""
    return area * ABLATION_M_PER_SECOND * 86400


def survival_days(area):
    loss = daily_ablation(area)
    if loss == 0:
        return 0.0
    return ice_volume(area) / loss


def format_report(area):
    return (
        "{:>9} m2  {:<19} {:8.4f} km2  thickness {:6.1f} m  "
        "volume {:12.0f} m3  tiles {:5d}  lifetime {:8.0f} d"
    ).format(
        area,
        measure(area),
        area_in_km2(area),
        mean_thickness(area),
        ice_volume(area),
        raster_tiles(area),
        survival_days(area),
    )


