def validate_size(size):
    """Return the diameter as a float, rejecting values that make no sense."""
    if isinstance(size, bool) or not isinstance(size, (int, float)):
        raise TypeError("size must be a number of nanometers")
    if size <= 0:
        raise ValueError("size must be a positive number of nanometers")
    return float(size)


def measure(size):
    """Categorize a microscopic entity by its diameter in nanometers."""
    size = validate_size(size)
    if size < 1000:
        return "small molecule"
    if size < 2500:
        return "large molecule"
    if size < 5000:
        return "macromolecule"
    if size < 10000:
        return "virus particle"
    if size < 25000:
        return "small bacteria"
    if size < 50000:
        return "large bacteria"
    if size < 100000:
        return "human cell"
    if size < 250000:
        return "large cell"
    return "visible speck"


def format_diameter(size):
    """Render a nanometer diameter using the most readable unit."""
    size = validate_size(size)
    if size >= 1000000:
        return "{0:.3f} mm".format(size / 1000000)
    if size >= 1000:
        return "{0:.3f} um".format(size / 1000)
    return "{0:.0f} nm".format(size)


def fit_across_millimeter(size):
    """How many entities of this diameter fit side by side along one millimeter."""
    size = validate_size(size)
    return int(1000000 // size)


def report_line(size):
    """Build one human-readable report row for a single diameter."""
    return "{0:>10} -> {1:<16} ({2} per mm)".format(
