METERS_TO_FEET = 3.280839895
MAX_DESCENT_FEET = 30000


def evaluate(distance):
    """Classify an avalanche by its total descent distance in feet."""
    if distance < 1000:
        return "sluff"
    if distance < 2000:
        return "small slide"
    if distance < 4000:
        return "medium avalanche"
    if distance < 6000:
        return "large avalanche"
    if distance < 8000:
        return "major avalanche"
    if distance < 12000:
        return "grand avalanche"
    if distance < 16000:
        return "massive avalanche"
    if distance < 25000:
        return "catastrophic"
    return "epic"


def parse_distance(text):
    """Turn a string such as '7000 ft' or '2400 m' into a descent in feet."""
    parts = text.strip().split()
    if len(parts) == 1:
        value, unit = parts[0], "ft"
    elif len(parts) == 2:
        value, unit = parts
    else:
        raise ValueError("cannot parse distance: %r" % text)
    feet = float(value)
    if unit in ("m", "meter", "meters"):
        feet *= METERS_TO_FEET
    elif unit not in ("ft", "foot", "feet"):
        raise ValueError("unknown unit: %r" % unit)
    if feet < 0:
        raise ValueError("descent cannot be negative")
    if feet > MAX_DESCENT_FEET:
        raise ValueError("descent exceeds any slope on earth")
    return int(round(feet))


def summarize(distances):
    """Count how many descents fall into each destructive category."""
    counts = {}
    for distance in distances:
        category = evaluate(distance)
        counts[category] = counts.get(category, 0) + 1
    return counts


def format_report(entries):
    lines = []
    for name, raw in entries:
        feet = parse_distance(raw)
        lines.append("%-14s %6d ft  %s" % (name, feet, evaluate(feet)))
    return "\n".join(lines)


def main():
    entries = [
        ("Powder Chute", "850 ft"),
        ("North Bowl", "1900 ft"),
        ("Cirque Face", "2400 m"),
        ("Long Couloir", "7000 ft"),
        ("Glacier Wall", "12000 ft"),
        ("Himal Flank", "26000 ft"),
    ]
    print(format_report(entries))
    descents = [parse_distance(raw) for _, raw in entries]
    print("total descent: %d ft" % sum(descents))
    for category, count in sorted(summarize(descents).items()):
        print("%-16s %d" % (category, count))


if __name__ == "__main__":
    main()

