def grade_weight(weight):
    """Classify the average paper roll weight of a facility."""
    if weight <= 0:
        raise ValueError("roll weight must be positive")
    if weight < 1500:
        return "tissue"
    if weight <= 3500:
        return "print"
    if weight <= 8500:
        return "cardboard"
    if weight <= 15000:
        return "industrial"
    return "heavy"


def consumption_level(usage):
    """Classify the daily water usage (litres) of a facility."""
    if usage < 0:
        raise ValueError("water usage cannot be negative")
    if usage < 25000:
        return "efficient"
    if usage <= 65000:
        return "moderate"
    if usage <= 125000:
        return "high"
    if usage <= 250000:
        return "intensive"
    return "excessive"


def review(mills):
    """Return (name, product grade, consumption level) for every mill."""
    return [(name, grade_weight(weight), consumption_level(usage))
            for name, weight, usage in mills]


def average_flow(usage):
    """Mean water draw in litres per second over a full day."""
    return usage / 86400


def parse_records(text):
    """Read 'name,weight,usage' lines into mill tuples."""
    mills = []
    for line in text.strip().splitlines():
        name, weight, usage = line.split(",")
        mills.append((name.strip(), int(weight), int(usage)))
    return mills


def format_report(mills):
    lines = []
    graded = review(mills)
    for (name, grade, level), (_, _, usage) in zip(graded, mills):
        lines.append("%-14s %-10s %-9s %7.2f L/s"
                     % (name, grade, level, average_flow(usage)))
    total = sum(usage for _, _, usage in mills)
    lines.append("TOTAL daily water: %d L (%.3f megalitres)"
                 % (total, total / 1000000))
    flagged = [n for n, _, lvl in graded if lvl in ("intensive", "excessive")]
