def classify_traffic(packets_per_second):
    """Return the traffic volume label for a packets-per-second reading."""
    if packets_per_second < 15000:
        return "quiet"
    if packets_per_second <= 45000:
        return "normal"
    if packets_per_second <= 125000:
        return "heavy"
    if packets_per_second <= 350000:
        return "overload"
    return "attack"


def classify_latency(peak_latency_us):
    """Return the latency severity label for a peak latency in microseconds."""
    if peak_latency_us < 2500:
        return "negligible"
    if peak_latency_us <= 8500:
        return "noticeable"
    if peak_latency_us <= 25000:
        return "disruptive"
    if peak_latency_us <= 75000:
        return "critical"
    return "offline"


def monitor(servers):
    """Categorize each (identifier, packets/s, peak latency us) network record."""
    results = []
    for record in servers:
        name, packets, latency = record
        if not isinstance(packets, int) or not isinstance(latency, int):
            raise TypeError("packets and latency must be integers for " + str(name))
        if packets < 0 or latency < 0:
            raise ValueError("negative measurement for " + str(name))
        results.append((name, classify_traffic(packets), classify_latency(latency)))
    return results


def parse_record(line):
    """Turn a "name,packets,latency" feed line into a record tuple."""
    name, packets, latency = line.split(",")
    return (name.strip(), int(packets), int(latency))


def daily_packet_volume(packets_per_second):
    """Extrapolate a per-second rate to a full day of traffic."""
    return packets_per_second * 86400


def latency_milliseconds(peak_latency_us):
    """Convert a microsecond latency into milliseconds."""
    return peak_latency_us / 1000


def format_report(servers, results):
    lines = []
    for (name, packets, latency), (_, volume, severity) in zip(servers, results):
        lines.append(
            "%-14s %-9s %-11s %11d packets/day %7.2f ms"
            % (name, volume, severity, daily_packet_volume(packets),
               latency_milliseconds(latency))
        )
    return "\n".join(lines)


def count_alarms(results):
    """Count records whose traffic or latency demands operator attention."""
    return sum(1 for _, volume, severity in results
               if volume in ("overload", "attack") or severity in ("critical", "offline"))


