Edge Cache,9800,1750
Auth Node,44500,8500
Relay Hub,126000,75000
Public API,351000,120000"""


def main():
    servers = [parse_record(line) for line in FEED.splitlines()]
    results = monitor(servers)
    print(format_report(servers, results))
    print("alarms: %d of %d servers" % (count_alarms(results), len(results)))


if __name__ == "__main__":
    main()

