HEMOCYTOMETER_FACTOR = 10000
DOUBLING_SECONDS = 5400
SECONDS_PER_DAY = 86400
SECONDS_PER_HOUR = 3600

DENSITIES = {
    "ale yeast": 8500,
    "lager yeast": 12500,
    "sourdough starter": 25000,
    "champagne yeast": 15000,
    "bread yeast": 35000,
    "wine yeast": 18000,
    "cider yeast": 14000,
    "distillers yeast": 45000,
}


def culture(strain):
    """Return the optimal harvest density (cells/mL) for a yeast strain."""
    if not isinstance(strain, str):
        return 0
    return DENSITIES.get(strain.strip().lower(), 0)


def cells_needed(strain, volume_ml):
    """Total cells required to fill volume_ml at the strain's harvest density."""
    density = culture(strain)
    if density == 0 or volume_ml <= 0:
        return 0
    return density * volume_ml


def density_from_count(cells_counted, squares_counted):
    """Convert a hemocytometer tally into cells per millilitre."""
    if squares_counted <= 0:
        return 0
    return round(cells_counted / squares_counted * HEMOCYTOMETER_FACTOR)


def generations_to_target(strain, inoculum_density):
    """Number of doublings needed to grow an inoculum up to harvest density."""
    target = culture(strain)
    if target == 0 or inoculum_density <= 0:
        return 0
    generations = 0
    density = inoculum_density
    while density < target:
        density *= 2
        generations += 1
    return generations


def propagation_seconds(strain, inoculum_density):
    return generations_to_target(strain, inoculum_density) * DOUBLING_SECONDS


def format_duration(seconds):
    days = seconds // SECONDS_PER_DAY
    remainder = seconds % SECONDS_PER_DAY
    hours = remainder // SECONDS_PER_HOUR
    minutes = remainder % SECONDS_PER_HOUR // 60
    if days:
        return "{0}d {1}h {2}m".format(days, hours, minutes)
    return "{0}h {1}m".format(hours, minutes)


def format_cells(count):
    return "{0:.2f}M".format(count / 1000000)


def report(strain, volume_ml, cells_counted, squares_counted):
    density = culture(strain)
    if density == 0:
        return "{0}: unrecognised strain".format(strain)
    inoculum = density_from_count(cells_counted, squares_counted)
    seconds = propagation_seconds(strain, inoculum)
    return "{0}: harvest at {1} cells/mL, need {2} cells for {3} mL, " \
           "inoculum {4} cells/mL, ready in {5}".format(
               strain, density, format_cells(cells_needed(strain, volume_ml)),
               volume_ml, inoculum, format_duration(seconds))


def main():
    batch_ml = 20000
    samples = [
        ("ale yeast", 42, 80),
        ("lager yeast", 55, 80),
        ("sourdough starter", 120, 80),
        ("distillers yeast", 200, 80),
        ("kombucha culture", 30, 80),
    ]
    for strain, counted, squares in samples:
        print(report(strain, batch_ml, counted, squares))


if __name__ == "__main__":
    main()

