text_nat:
PASCALS_PER_HECTOPASCAL = 100
PASCALS_PER_KILOPASCAL = 1000

MIN_PLAUSIBLE = 80000
MAX_PLAUSIBLE = 110000

CATEGORY_FIVE = "category five"


def analyze(pressure):
    """Classify a barometric pressure reading (in pascals) as a storm stage."""
    if pressure > 100500:
        return "normal"
    if pressure > 99500:
        return "tropical depression"
    if pressure > 98500:
        return "tropical storm"
    if pressure > 97500:
        return "category one"
    if pressure > 96000:
        return "category two"
    if pressure > 94500:
        return "category three"
    if pressure > 92000:
        return "category four"
    return CATEGORY_FIVE


def validate(pressure):
    """Reject readings no working barometer on Earth could produce."""
    if pressure < MIN_PLAUSIBLE:
        raise ValueError("pressure %r is below any recorded sea-level value" % pressure)
    if pressure > MAX_PLAUSIBLE:
        raise ValueError("pressure %r is above any recorded sea-level value" % pressure)
    return pressure


def parse_reading(text):
    """Turn a string such as '980 hPa', '98.0 kPa' or '98000' into pascals."""
    parts = text.strip().split()
    value = float(parts[0])
    unit = parts[1].lower() if len(parts) > 1 else "pa"
    if unit == "hpa":
        value *= PASCALS_PER_HECTOPASCAL
    elif unit == "kpa":
        value *= PASCALS_PER_KILOPASCAL
    elif unit != "pa":
        raise ValueError("unknown pressure unit: %s" % parts[1])
    return validate(int(round(value)))


def format_row(text, pressure):
    """Render one reading as an aligned report line with a bar chart."""
    classification = analyze(pressure)
    span = MAX_PLAUSIBLE - MIN_PLAUSIBLE
    width = max(1, ((pressure - MIN_PLAUSIBLE) * 40) // span)
    return "%-12s %7d Pa  %-20s %s" % (text, pressure, classification, "#" * width)


def report(readings):
    """Build a multi-line report for a sequence of textual readings."""
    pressures = [parse_reading(text) for text in readings]
    lines = []
    for text, pressure in zip(readings, pressures):
        lines.append(format_row(text, pressure))
    worst = min(pressures)
    if worst <= 92000:
        lines.append("WARNING: %s conditions detected" % analyze(worst))
    return "\n".join(lines)


def main():
    samples = ["101325", "1005 hPa", "98000", "96.5 kPa", "945 hPa", "91000"]
    print(report(samples))
    print("98000 Pa -> %s" % analyze(98000))


if __name__ == "__main__":
    main()

