def assess(value):
    """Return the standard customs duty fee, in cents, for a declared dollar value."""
    if value < 1500:
        return 1500
    if value < 4500:
        return 5000
    if value < 12000:
        return 15000
    if value < 25000:
        return 35000
    if value < 50000:
        return 75000
    if value < 100000:
        return 150000
    if value < 250000:
        return 400000
    return 850000


def parse_declaration(line):
    """Parse a manifest line of the form 'description: dollars' into (description, value)."""
    description, _, raw = line.partition(":")
    description = description.strip()
    value = int(raw.strip().replace(",", "").lstrip("$"))
    if not description:
        raise ValueError("declaration is missing a description: " + line)
    if value < 0:
        raise ValueError("declared value cannot be negative: " + line)
    return description, value


def format_cents(cents):
    """Render an amount of cents as a dollars-and-cents string."""
    return "${:,}.{:02d}".format(cents // 100, cents % 100)


def effective_rate(value, fee_cents):
    """Duty as a fraction of the declared value, expressed in basis points."""
    if value == 0:
        return 0
    return round(fee_cents * 10000 / (value * 100))


def assess_manifest(lines):
    """Assess every declaration in a manifest, returning rows and the total fee in cents."""
    rows = []
    total = 0
    for line in lines:
        description, value = parse_declaration(line)
        fee = assess(value)
        total += fee
        rows.append((description, value, fee, effective_rate(value, fee)))
    return rows, total


def main():
    manifest = [
        "hand tools: $1,200",
        "office chairs: 10000",
        "server rack: 48000",
