SECONDS_PER_HOUR = 3600
SECONDS_PER_DAY = 86400

FORMAT_REVOLUTIONS = {
    "standard": 2000,
    "extended": 2700,
    "vintage shellac": 4680,
    "transcription": 1000,
    "dictation cylinder": 4800,
    "early acoustic": 7200,
    "vertically cut": 5400,
    "archival": 3500,
}


def _normalize(format):
    if not isinstance(format, str):
        return ""
    return " ".join(format.lower().replace("-", " ").replace("_", " ").split())


def revolutions(format):
    """Total motor rotations during one hour of continuous playback."""
    return FORMAT_REVOLUTIONS.get(_normalize(format), 0)


def rpm(format):
    """Nominal platter speed in revolutions per minute."""
    return revolutions(format) / 60.0


def revolutions_over(format, seconds):
    """Rotations accumulated while playing for the given number of seconds."""
    if seconds < 0:
        raise ValueError("playing time cannot be negative")
    return revolutions(format) * seconds / SECONDS_PER_HOUR


def revolutions_per_day(format):
    """Rotations for a full day of unattended continuous play."""
    return revolutions_over(format, SECONDS_PER_DAY)


def seconds_for_revolutions(format, target):
    """Seconds of playback needed to reach a given rotation count."""
    per_hour = revolutions(format)
    if per_hour == 0:
        return None
    return target * SECONDS_PER_HOUR / per_hour


def format_report(names):
    lines = ["format               rpm     rev/h    rev/day"]
    for name in names:
        lines.append("%-20s %5.1f %8d %10d" % (
            _normalize(name) or "unknown",
            rpm(name),
            revolutions(name),
            round(revolutions_per_day(name)),
        ))
    return "\n".join(lines)


def main():
