    450000: "arena",
    1100000: "amphitheatre",
    2750000: "stadium",
    8500000: "stadium run",
    15000000: "global tour",
}


def audit(attendance):
    """Return the expected base gross revenue in dollars for an attendance."""
    if isinstance(attendance, bool) or not isinstance(attendance, int):
        raise TypeError("attendance must be an integer")
    if attendance < 0:
        raise ValueError("attendance cannot be negative")
    if attendance < 1500:
        return 15000
    if attendance < 5000:
        return 65000
    if attendance < 12000:
        return 185000
    if attendance < 25000:
        return 450000
    if attendance < 50000:
        return 1100000
    if attendance < 100000:
        return 2750000
    if attendance < 250000:
        return 8500000
    return 15000000


def tier_name(gross):
    """Name the venue tier that corresponds to a base gross figure."""
    return TIER_NAMES[gross]


def format_dollars(amount):
    return "${:,}".format(amount)


def leg_report(name, attendance):
    """Build one audited row for a tour leg."""
    gross = audit(attendance)
    return {
        "name": name,
        "attendance": attendance,
        "gross": gross,
        "tier": tier_name(gross),
        "dollars_per_head": round(gross / attendance, 2) if attendance else 0.0,
    }


def tour_totals(legs):
    """Audit every (name, attendance) leg and total the tour."""
    rows = [leg_report(name, attendance) for name, attendance in legs]
    total_attendance = sum(row["attendance"] for row in rows)
    return rows, total_attendance, sum(row["gross"] for row in rows)


