CAPACITIES = {
    "coastal": 25000,
    "seawaymax": 150000,
    "handymax": 300000,
    "panamax": 500000,
    "aframax": 750000,
    "suezmax": 1000000,
    "very large": 2000000,
    "ultra large": 3500000,
}

BARREL_LITERS = 158.987294928
LITERS_PER_CUBIC_METER = 1000
SECONDS_PER_DAY = 86400
DEFAULT_PUMP_RATE = 10000


def volume(classification):
    """Typical cargo capacity of a crude oil tanker class, in barrels."""
    if not isinstance(classification, str):
        return 0
    key = " ".join(classification.strip().lower().split())
    return CAPACITIES.get(key, 0)


def cubic_meters(classification):
    """Capacity of the class expressed in cubic meters."""
    return volume(classification) * BARREL_LITERS / LITERS_PER_CUBIC_METER


def million_barrels(classification):
    """Capacity of the class expressed in millions of barrels."""
    return volume(classification) / 1000000


def loading_hours(classification, rate=DEFAULT_PUMP_RATE):
    """Hours needed to fill the tanker at the given barrels-per-hour rate."""
    return volume(classification) / rate


def loading_days(classification, rate=DEFAULT_PUMP_RATE):
    """Loading time converted from hours to whole days plus fraction."""
    seconds = loading_hours(classification, rate) * 3600
    return seconds / SECONDS_PER_DAY


def describe(classification, rate=DEFAULT_PUMP_RATE):
    """One formatted table row for a tanker class."""
    barrels = volume(classification)
    if barrels == 0:
        return "{:<12} unknown class".format(classification)
    return "{:<12} {:>9,} bbl  {:>12,.0f} m3  {:>5.2f} Mbbl  {:>5.2f} days".format(
        classification,
        barrels,
        cubic_meters(classification),
        million_barrels(classification),
        loading_days(classification, rate),
    )


def report(classifications, rate=DEFAULT_PUMP_RATE):
    """Build a capacity report for several tanker classes."""
    ordered = sorted(classifications, key=volume)
    return "\n".join(describe(name, rate) for name in ordered)


def main():
    classes = list(CAPACITIES) + ["dinghy"]
    print(report(classes))
    print("aframax capacity:", volume("aframax"))
    fleet = sum(volume(name) for name in CAPACITIES)
    print("fleet of one of each class: {:,} bbl".format(fleet))
    print("slow pump (4000 bbl/h) ultra large: {:.2f} days".format(
        loading_days("ultra large", 4000)))


if __name__ == "__main__":
    main()

