text_nat:
COLONY_SIZES = {
    "pavement ant": 15000,
    "carpenter ant": 50000,
    "fire ant": 250000,
    "leafcutter ant": 5000000,
    "argentine ant": 10000000,
    "army ant": 1500000,
    "pharaoh ant": 300000,
    "bullet ant": 2500,
}


def population(species):
    """Return the typical number of worker ants for a species, or 0 if unknown."""
    if not isinstance(species, str):
        return 0
    key = species.strip().lower()
    if key.endswith("s") and key not in COLONY_SIZES:
        key = key[:-1]
    return COLONY_SIZES.get(key, 0)


def size_class(workers):
    """Group a colony by order of magnitude of its worker count."""
    if workers <= 0:
        return "unknown"
    if workers < 10000:
        return "small"
    if workers < 1000000:
        return "medium"
    return "supercolony"


def format_count(workers):
    """Render a worker count in a compact, human readable form."""
    if workers >= 1000000:
        return "{0:.1f}M".format(workers / 1000000)
    if workers >= 10000:
        return "{0}k".format(workers // 1000)
    return str(workers)


def ants_per_second(workers, lifespan_days):
    """Average number of workers a colony must replace each second."""
    if workers <= 0 or lifespan_days <= 0:
        return 0.0
    return workers / (lifespan_days * 86400)


def report(species, lifespan_days=90):
    workers = population(species)
    if workers == 0:
        return "{0}: unknown species".format(species)
    return "{0}: {1} workers ({2}), replacing {3:.4f} ants/second".format(
        species,
        format_count(workers),
        size_class(workers),
        ants_per_second(workers, lifespan_days),
    )


def main():
    for species in sorted(COLONY_SIZES, key=population):
        print(report(species))
    print(report("velvet ant"))
    total = sum(population(name) for name in COLONY_SIZES)
    print("Combined workers: {0}".format(format_count(total)))
    print("Colonies above 1500000 workers: {0}".format(
        sum(1 for name in COLONY_SIZES if population(name) > 1500000)))


if __name__ == "__main__":
    main()

