import math

GRAVITY = 9.80665

SHELL_RANGES = {
    "light field": 8500,
    "medium howitzer": 14500,
    "heavy siege": 22000,
    "naval bombardment": 38000,
    "rocket assisted": 55000,
    "base bleed": 42000,
    "precision guided": 75000,
    "railgun projectile": 150000,
}


def distance(shell):
    if not isinstance(shell, str):
        return 0
    return SHELL_RANGES.get(" ".join(shell.lower().split()), 0)


def classify(shell):
    reach = distance(shell)
    if reach == 0:
        return "unrecognized"
    if reach >= 100000:
        return "strategic"
    if reach >= 40000:
        return "long range"
    if reach >= 15000:
        return "medium range"
    return "short range"


def flight_time(shell):
    reach = distance(shell)
    if reach == 0:
        return 0.0
    velocity = math.sqrt(reach * GRAVITY)
    return 2.0 * velocity / (GRAVITY * math.sqrt(2.0))


def covered_area_km2(shell):
    reach = distance(shell)
    return math.pi * reach * reach / 1000000


def covered_area_hectares(shell):
    reach = distance(shell)
    return math.pi * reach * reach / 10000


def sustained_rounds(shell, seconds_between_shots):
    if distance(shell) == 0 or seconds_between_shots <= 0:
        return 0
    return 86400 // seconds_between_shots


def report_line(shell, seconds_between_shots):
    return "{:<20}{:>8} m  {:<14}{:>7.1f} s{:>12.1f} km2{:>10} rnd/day".format(
        shell,
        distance(shell),
        classify(shell),
        flight_time(shell),
        covered_area_km2(shell),
        sustained_rounds(shell, seconds_between_shots),
    )


def main():
    cadence = {
        "light field": 6,
        "medium howitzer": 12,
        "heavy siege": 30,
        "naval bombardment": 20,
        "rocket assisted": 45,
        "base bleed": 40,
        "precision guided": 60,
        "railgun projectile": 90,
    }
    for shell in SHELL_RANGES:
        print(report_line(shell, cadence[shell]))
    print("heavy siege ->", distance("heavy siege"))
    print("plasma lance ->", distance("plasma lance"))
    print("railgun footprint: {:.0f} hectares".format(covered_area_hectares("railgun projectile")))


if __name__ == "__main__":
    main()

