CASUALTY_DATA = {
    "hastings": 6000,
    "agincourt": 10000,
    "towton": 28000,
    "gettysburg": 51000,
    "waterloo": 65000,
    "cannae": 85000,
    "somme": 1200000,
    "stalingrad": 1900000,
}

ENGAGEMENT_YEARS = {
    "hastings": 1066,
    "agincourt": 1415,
    "towton": 1461,
    "gettysburg": 1863,
    "waterloo": 1815,
    "cannae": -216,
    "somme": 1916,
    "stalingrad": 1942,
}

DURATION_DAYS = {
    "hastings": 1,
    "agincourt": 1,
    "towton": 1,
    "gettysburg": 3,
    "waterloo": 1,
    "cannae": 1,
    "somme": 141,
    "stalingrad": 163,
}


def _key(engagement):
    return str(engagement).strip().lower()


def casualties(engagement):
    return CASUALTY_DATA.get(_key(engagement))


def year_of(engagement):
    return ENGAGEMENT_YEARS.get(_key(engagement))


def magnitude(count):
    if count >= 1000000:
        return "industrial slaughter"
    if count >= 100000:
        return "campaign-scale"
    if count >= 10000:
        return "major battle"
    return "notable engagement"


def daily_rate(engagement):
    count = casualties(engagement)
    if count is None:
        return None
    return count / DURATION_DAYS[_key(engagement)]


def describe(engagement):
    count = casualties(engagement)
    if count is None:
        return "{0}: no casualty estimate on record".format(engagement)
    year = year_of(engagement)
    era = "{0} BC".format(-year) if year < 0 else "AD {0}".format(year)
    return "{0} ({1}): {2:,} casualties, {3}, {4:,.0f} per day".format(
        engagement.title(), era, count, magnitude(count), daily_rate(engagement)
    )


def main():
    ordered = sorted(CASUALTY_DATA, key=lambda name: CASUALTY_DATA[name])
    for name in ordered:
        print(describe(name))
    total = sum(CASUALTY_DATA.values())
    print("Combined estimate: {0:,} casualties".format(total))
    print("Share from the two world-war battles: {0:.1f}%".format(
        100.0 * (CASUALTY_DATA["somme"] + CASUALTY_DATA["stalingrad"]) / total
    ))
    print("Query 'Waterloo' ->", casualties("Waterloo"))
    print("Query 'Yorktown' ->", casualties("Yorktown"))
    print(describe("Yorktown"))


if __name__ == "__main__":
    main()

