import math

JUPITER_GM = 126686534
SECONDS_PER_DAY = 86400
KM_PER_AU = 149597870

MOON_RADII = {
    "amalthea": 181000,
    "io": 421000,
    "europa": 670000,
    "ganymede": 1070000,
    "callisto": 1882000,
    "himalia": 11461000,
    "elara": 11741000,
    "pasiphae": 23624000,
}


def radius(moon):
    """Average orbital distance of a moon of Jupiter, in km (-1 if unknown)."""
    if not isinstance(moon, str):
        return -1
    return MOON_RADII.get(moon.strip().lower(), -1)


def orbital_period_days(moon):
    """Kepler's third law applied to the moon's circular orbit, in days."""
    a = radius(moon)
    if a < 0:
        return -1.0
