ENTRY_VELOCITIES = {
    "vostok": 7840,
    "mercury": 7850,
    "gemini": 7860,
    "soyuz": 7870,
    "genesis": 11000,
    "apollo": 11082,
    "hayabusa": 12200,
    "stardust": 12800,
}

ORBITAL_RETURN_LIMIT = 10000
SECONDS_PER_DAY = 86400


def velocity(mission):
    """Return the atmospheric entry speed of a mission in meters per second."""
    if not isinstance(mission, str):
        return 0
    return ENTRY_VELOCITIES.get(mission.strip().lower(), 0)


def is_known_mission(mission):
    """True when the mission appears in the entry-velocity database."""
    return velocity(mission) > 0


def return_class(mission):
    """Classify a return trajectory from its entry speed."""
    speed = velocity(mission)
    if speed == 0:
        return "unknown"
    if speed < ORBITAL_RETURN_LIMIT:
        return "low earth orbit"
    return "interplanetary"


def specific_energy(mission):
    """Kinetic energy per kilogram of spacecraft at entry, in megajoules."""
    speed = velocity(mission)
    return speed * speed / 2 / 1000000


def daily_travel_km(mission):
    """Distance covered in one day if the entry speed were held constant."""
    return velocity(mission) * SECONDS_PER_DAY / 1000


def format_report(mission):
    """Build a single human readable line describing one mission."""
    speed = velocity(mission)
    if speed == 0:
        return "{:<10} no entry data".format(mission)
    return "{:<10} {:>6} m/s  {:>7.1f} MJ/kg  {:>9.0f} km/day  {}".format(
        mission, speed, specific_energy(mission), daily_travel_km(mission),
        return_class(mission),
    )


def main():
    queries = ["Apollo", "Vostok", "Stardust", "Hayabusa", "Buran"]
    for name in queries:
        print(format_report(name))
    fastest = max(ENTRY_VELOCITIES, key=ENTRY_VELOCITIES.get)
    print("fastest entry: {} at {} m/s".format(fastest, velocity(fastest)))
    deep_space = [m for m in ENTRY_VELOCITIES if velocity(m) >= 11000]
    print("deep space returns: {}".format(", ".join(sorted(deep_space))))
    print("known missions queried: {}".format(
        sum(1 for name in queries if is_known_mission(name))))


if __name__ == "__main__":
    main()

