GENOME_SIZES_KB = {
    "arabidopsis": 135000,
    "rice": 430000,
    "tomato": 900000,
    "soybean": 1100000,
    "maize": 2300000,
    "barley": 5300000,
    "wheat": 17000000,
    "pine": 22000000,
}


def genome(plant):
    """Return the approximate genome size in thousands of base pairs (kb)."""
    if not isinstance(plant, str):
        return 0
    return GENOME_SIZES_KB.get(plant.strip().lower(), 0)


def genome_in_gigabases(plant):
    """Convert the kb value to gigabases (1 Gb == 1000000 kb)."""
    return genome(plant) / 1000000


def size_class(plant):
    """Group plants by genome size into broad descriptive classes."""
    size = genome(plant)
    if size == 0:
        return "unknown"
    if size < 500000:
        return "compact"
    if size < 3000000:
        return "medium"
    return "large"


def format_size(plant):
    """Human readable rendering of the stored genome size."""
    size = genome(plant)
    if size == 0:
        return "{0}: not in the system".format(plant)
    if size >= 1000000:
        return "{0}: {1:.2f} Gb".format(plant, size / 1000000)
    return "{0}: {1:.0f} Mb".format(plant, size / 1000)


def ratio_to_arabidopsis(plant):
    """How many Arabidopsis-sized genomes fit inside this plant's genome."""
    reference = 135000
    size = genome(plant)
    if size == 0:
        return 0.0
    return size / reference


def ranked_plants():
    """All known plants ordered from the smallest genome to the largest."""
    return sorted(GENOME_SIZES_KB, key=GENOME_SIZES_KB.get)


def report(plants):
    """Build a multi-line report for the requested plants."""
    lines = []
    for plant in plants:
        line = format_size(plant)
        size = genome(plant)
        if size:
            line += "  [{0}, {1:.1f}x Arabidopsis]".format(size_class(plant),
                                                           ratio_to_arabidopsis(plant))
        lines.append(line)
    return "\n".join(lines)


def main():
    print(genome("tomato"))
    print(report(["arabidopsis", "rice", "wheat", "pine", "banana"]))
    print("smallest to largest:", ", ".join(ranked_plants()))
    total_kb = sum(genome(plant) for plant in ranked_plants())
    print("combined size: {0:.2f} Gb".format(total_kb / 1000000))
    print("wheat exceeds 10 Gb:", genome("wheat") > 10000000)
    print("pine in Gb:", genome_in_gigabases("pine"))


if __name__ == "__main__":
    main()

