"""Hobby forum traffic statistics."""

SECONDS_PER_DAY = 86400

_DAILY_VISITORS = {
    "woodworking": 12000,
    "coffee roasting": 14000,
    "aquariums": 18500,
    "retro computing": 19000,
    "fountain pens": 21000,
    "gardening": 25000,
    "bird watching": 32000,
    "mechanical keyboards": 45000,
}


def traffic(topic):
    """Return the average daily unique visitor count for a forum topic."""
    if not isinstance(topic, str):
        return 0
    return _DAILY_VISITORS.get(topic.strip().lower(), 0)


def visitors_per_second(topic):
    """Average unique visitors arriving each second over a full day."""
    return traffic(topic) / SECONDS_PER_DAY


def monthly_traffic(topic, days=30):
    """Visitor count accumulated over a billing period of `days` days."""
    if days <= 0:
        raise ValueError("days must be positive")
    return traffic(topic) * days


def bandwidth_gb(topic, page_weight_kb=1500, pages_per_visit=4):
    """Daily bandwidth in gigabytes for a topic's traffic."""
    kilobytes = traffic(topic) * pages_per_visit * page_weight_kb
    return kilobytes / 1048576


def busiest_topics(limit=3):
    """Topics ordered from most to least daily traffic."""
    ranked = sorted(_DAILY_VISITORS, key=_DAILY_VISITORS.get, reverse=True)
    return ranked[:limit]


def format_count(count):
    """Human readable visitor count, e.g. 1.2M or 45.0k."""
    if count >= 1000000:
        return "{:.1f}M".format(count / 1000000)
    if count >= 10000:
        return "{:.1f}k".format(count / 1000)
    return str(count)


def report(topics):
    """Build a multi-line traffic report for the given topics."""
    lines = []
    for topic in topics:
        daily = traffic(topic)
        lines.append(
            "{:<22} {:>8} visitors/day  {:>6.2f}/s  {:>7.2f} GB/day  {:>9} /month".format(
                topic,
                format_count(daily),
                visitors_per_second(topic),
                bandwidth_gb(topic),
                format_count(monthly_traffic(topic)),
            )
        )
    return "\n".join(lines)


def main():
    print("gardening:", traffic("gardening"))
    print("underwater basket weaving:", traffic("underwater basket weaving"))
    print()
    print(report(busiest_topics(len(_DAILY_VISITORS))))
    total = sum(traffic(t) for t in _DAILY_VISITORS)
    print()
    print("network total:", format_count(total), "visitors/day")
    print("yearly total:", format_count(total * 365))


if __name__ == "__main__":
    main()

