import time

INTERVALS = {
    "scooter": 1500,
    "motorcycle": 3000,
    "performance car": 5000,
    "commuter car": 7500,
    "pickup truck": 10000,
    "diesel truck": 15000,
    "semi tractor": 25000,
    "transit bus": 35000,
}


def interval(vehicle):
    """Recommended maintenance interval in miles, or 0 for unknown classes."""
    if not isinstance(vehicle, str):
        return 0
    return INTERVALS.get(vehicle.strip().lower(), 0)


def next_service_mileage(odometer, vehicle):
    """Odometer reading at which the next service falls due."""
    step = interval(vehicle)
    if odometer < 0 or odometer > 1000000:
        raise ValueError("odometer reading out of supported range: %r" % (odometer,))
    if step == 0:
        return 0
    return (int(odometer) // step + 1) * step


def miles_remaining(odometer, vehicle):
    due_at = next_service_mileage(odometer, vehicle)
    if due_at == 0:
        return 0
    return due_at - odometer


def days_until_service(odometer, vehicle, annual_miles=12000):
    """Convert the remaining miles into calendar days at a yearly usage rate."""
    if annual_miles <= 0:
        return 0
    remaining = miles_remaining(odometer, vehicle)
    if remaining <= 0:
        return 0
    return int(round(remaining * 365.0 / annual_miles))


def due_date(days, now):
    return time.strftime("%Y-%m-%d", time.localtime(now + days * 86400))


def describe(vehicle, odometer, annual_miles, now):
    step = interval(vehicle)
    if step == 0:
        return "%-16s unknown classification, no interval published" % vehicle
    days = days_until_service(odometer, vehicle, annual_miles)
    return "%-16s every %6d mi | due at %7d mi (%5d mi, ~%4d days, %s)" % (
        vehicle,
        step,
        next_service_mileage(odometer, vehicle),
        miles_remaining(odometer, vehicle),
        days,
        due_date(days, now),
    )


def fleet_report(fleet, now):
    return [describe(v, odo, annual, now) for v, odo, annual in fleet]


def main():
    now = time.time()
    fleet = [
        ("motorcycle", 2400, 4000),
        ("commuter car", 68200, 12000),
        ("pickup truck", 154900, 18000),
        ("diesel truck", 412500, 60000),
        ("semi tractor", 988000, 120000),
        ("transit bus", 620000, 45000),
        ("hovercraft", 0, 1000),
    ]
    print("motorcycle interval:", interval("motorcycle"))
    for line in fleet_report(fleet, now):
        print(line)


if __name__ == "__main__":
    main()

