import re
from collections import Counter

MAX_TEXT_LENGTH = 1000000
MAX_HASHTAGS = 10000
CACHE_LIMIT = 65536
SECONDS_PER_DAY = 86400

_HASHTAG_RE = re.compile(r'#(\w+)')
_CACHE = {}


def extract_hashtags(text):
    """Return the hashtags found in `text`, stripped of the leading '#'."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text must not exceed %d characters" % MAX_TEXT_LENGTH)
    cached = _CACHE.get(text)
    if cached is not None:
        return list(cached)
    tags = _HASHTAG_RE.findall(text)
    if len(tags) > MAX_HASHTAGS:
        tags = tags[:MAX_HASHTAGS]
    if len(_CACHE) >= CACHE_LIMIT:
        _CACHE.clear()
    _CACHE[text] = tags
    return list(tags)


def count_hashtags(texts):
    """Count hashtag occurrences (case-insensitively) across many texts."""
    counter = Counter()
    for text in texts:
        counter.update(tag.lower() for tag in extract_hashtags(text))
    return counter


def top_hashtags(counter, limit=5):
    ordered = sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def daily_rate(counter, window_seconds):
    """Average hashtags per day, given the length of the sampling window."""
    if window_seconds <= 0:
        raise ValueError("window_seconds must be positive")
    return sum(counter.values()) * SECONDS_PER_DAY / window_seconds


def format_report(counter, window_seconds, limit=5):
    lines = ["distinct hashtags: %d" % len(counter)]
    total = sum(counter.values())
    for tag, hits in top_hashtags(counter, limit):
        share = hits * 10000 // total
        lines.append("  #%-10s %4d  (%5.2f%%)" % (tag, hits, share / 100.0))
    lines.append("rate: %.2f hashtags/day" % daily_rate(counter, window_seconds))
    return "\n".join(lines)


def main():
    posts = [
        'This is a #test with #python.',
        'No hashtags here.',
        '#Python and #python are the same tag, unlike #Testing',
        'Deploy day: #python #devops #test #devops',
    ]
    for post in posts:
        print(extract_hashtags(post))
    window = 172800
    counter = count_hashtags(posts)
    print(format_report(counter, window))


if __name__ == "__main__":
    main()

