import math

MICRODEGREES_PER_DEGREE = 1000000
EARTH_RADIUS_M = 6371000
TILE_SIZE_M = 65536
SECONDS_PER_DAY = 86400
MAX_OFFSET_M = 10000000

ROUTE_DATA = """
52.520000, 13.405000
50.110000, 8.682000
48.137000, 11.575000
47.370000, 8.541000
"""


def distance_2d(x1, y1, x2, y2):
    """Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def parse_point(text):
    """Read a "lat, lon" pair in degrees and return it in micro-degrees."""
    lat_text, lon_text = text.split(",")
    lat = round(float(lat_text) * MICRODEGREES_PER_DEGREE)
    lon = round(float(lon_text) * MICRODEGREES_PER_DEGREE)
    return lat, lon


def parse_route(block):
    return [parse_point(line) for line in block.splitlines() if line.strip()]


def project(lat_micro, lon_micro, ref_lat_micro, ref_lon_micro):
    """Turn micro-degree coordinates into local metres relative to a reference."""
    dlat = (lat_micro - ref_lat_micro) / MICRODEGREES_PER_DEGREE
    dlon = (lon_micro - ref_lon_micro) / MICRODEGREES_PER_DEGREE
    mean_lat = (lat_micro + ref_lat_micro) / (2 * MICRODEGREES_PER_DEGREE)
    y = math.radians(dlat) * EARTH_RADIUS_M
    x = math.radians(dlon) * EARTH_RADIUS_M * math.cos(math.radians(mean_lat))
    if abs(x) > MAX_OFFSET_M or abs(y) > MAX_OFFSET_M:
        raise ValueError("point lies outside the local projection window")
    return x, y


def tile_of(x, y):
    """Index of the square map tile holding a local metric coordinate."""
    return (math.floor(x / TILE_SIZE_M), math.floor(y / TILE_SIZE_M))


def segment_lengths(points):
    lengths = []
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        lengths.append(distance_2d(x1, y1, x2, y2))
    return lengths


def path_length(points):
    return sum(segment_lengths(points))


def travel_days(metres, speed_mps):
    if speed_mps <= 0:
        raise ValueError("speed must be positive")
    return metres / speed_mps / SECONDS_PER_DAY


def route_report(route_micro, speed_mps):
    ref_lat, ref_lon = route_micro[0]
    points = [project(lat, lon, ref_lat, ref_lon) for lat, lon in route_micro]
    lines = []
    for index, ((x, y), (lat, lon)) in enumerate(zip(points, route_micro)):
        tx, ty = tile_of(x, y)
        lines.append(
            "%2d  %+9.6f %+10.6f  x=%10.1f m  y=%10.1f m  tile=(%d,%d)"
            % (index, lat / MICRODEGREES_PER_DEGREE,
               lon / MICRODEGREES_PER_DEGREE, x, y, tx, ty)
        )
    for index, length in enumerate(segment_lengths(points)):
        lines.append("leg %d -> %d: %.1f m" % (index, index + 1, length))
    total = path_length(points)
    lines.append("total: %.1f m (%.3f days at %.1f m/s)"
                 % (total, travel_days(total, speed_mps), speed_mps))
    return "\n".join(lines)


def main():
    print(route_report(parse_route(ROUTE_DATA), 25.0))


if __name__ == "__main__":
    main()

