"""Bracket matching with input limits and a small reporting driver."""
import sys
import time

PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = frozenset(PAIRS.values())
MAX_INPUT_LENGTH = 1000000
MAX_NESTING_DEPTH = 65536
LONG_LABEL_THRESHOLD = 10000
DEEP_OPENERS = "(" * 20000


def check_input(s):
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    if len(s) > MAX_INPUT_LENGTH:
        raise ValueError("input of %d characters exceeds the %d character limit"
                         % (len(s), MAX_INPUT_LENGTH))
    return s


def is_valid_parentheses(s):
    """Return True if s is a balanced, correctly nested bracket string."""
    check_input(s)
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
            if len(stack) > MAX_NESTING_DEPTH:
                raise ValueError("nesting exceeds %d levels" % MAX_NESTING_DEPTH)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
        else:
            return False
    return not stack


def analyze(s):
    """Collect validity, size, nesting depth, character counts and timing."""
    check_input(s)
    counts = {}
    depth = 0
    max_depth = 0
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
        if ch in OPENERS:
            depth += 1
            if depth > max_depth:
                max_depth = depth
        elif ch in PAIRS:
            depth -= 1
    start = time.perf_counter()
    valid = is_valid_parentheses(s)
    elapsed_us = (time.perf_counter() - start) * 1000000
    return {"valid": valid, "length": len(s), "max_depth": max_depth,
            "counts": counts, "elapsed_us": elapsed_us}


def format_report(label, info):
    shape = ", ".join("%s=%d" % (ch, info["counts"][ch])
                      for ch in sorted(info["counts"]))
    return ("%-18s valid=%-5s length=%-6d depth=%-5d time=%8.1fus [%s]"
            % (label, info["valid"], info["length"], info["max_depth"],
               info["elapsed_us"], shape))


def label_for(s):
    if len(s) > LONG_LABEL_THRESHOLD:
        return "<%d chars>" % len(s)
    return repr(s)


def main(argv):
    deep = DEEP_OPENERS + ")" * len(DEEP_OPENERS)
    cases = argv[1:] or ["()[]{}", "([)]", "", "{[()]}", "(]", "([]{})[", deep]
    failures = 0
    for s in cases:
        try:
            info = analyze(s)
        except (TypeError, ValueError) as exc:
            failures += 1
            print("%-18s error: %s" % (label_for(s), exc))
            continue
        print(format_report(label_for(s), info))
    print("checked %d string(s), %d rejected by the limits"
          % (len(cases), failures))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

