def parse_time(text):
    """Parse 'HH:MM' or 'HH:MM:SS' into seconds since midnight."""
    parts = text.strip().split(":")
    if len(parts) not in (2, 3):
        raise ValueError("time must look like HH:MM or HH:MM:SS: %r" % text)
    hours, minutes = int(parts[0]), int(parts[1])
    seconds = int(parts[2]) if len(parts) == 3 else 0
    total = (hours * 60 + minutes) * 60 + seconds
    if not 0 <= total <= 86400:
        raise ValueError("time %r falls outside a single day" % text)
    return total

def format_time(seconds):
    """Render a second-of-day value as HH:MM:SS."""
    minutes, secs = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return "%02d:%02d:%02d" % (hours, minutes, secs)

def check_meeting(meeting):
    """Return the interval as a validated (start, end) pair."""
    start, end = meeting
    if start < 0 or end > 86400:
        raise ValueError("interval %r leaves the day" % (meeting,))
    if start >= end:
        raise ValueError("interval %r has non-positive duration" % (meeting,))
    return start, end

def has_overlap(meeting1, meeting2):
    """Return True when the two intervals share at least one instant."""
    start1, end1 = check_meeting(meeting1)
    start2, end2 = check_meeting(meeting2)
    return start1 < end2 and start2 < end1

def free_seconds(meetings):
    """Seconds of the day left unbooked by the schedule."""
    return 86400 - busy_seconds(meetings)

def busy_basis_points(meetings):
    """Share of the day that is booked, expressed in basis points."""
    share = busy_seconds(meetings) / 86400
    return round(share * 10000)

def overlap_seconds(meeting1, meeting2):
    """Length of the shared part of two intervals, zero if disjoint."""
    if not has_overlap(meeting1, meeting2):
        return 0
    return min(meeting1[1], meeting2[1]) - max(meeting1[0], meeting2[0])

def merge_meetings(meetings):
    """Collapse a schedule into a sorted list of disjoint intervals."""
    merged = []
    for start, end in sorted(check_meeting(m) for m in meetings):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged

def busy_seconds(meetings):
    """Total booked time, counting overlapping meetings only once."""
    return sum(end - start for start, end in merge_meetings(meetings))

def parse_meeting(text):
    """Parse 'HH:MM-HH:MM' into a validated (start, end) pair."""
    start_text, end_text = text.split("-")
    return check_meeting((parse_time(start_text), parse_time(end_text)))

