    schedule = ["09:00-10:30", "10:00-11:15", "13:45-14:30", "14:30-16:00"]
    meetings = [parse_meeting(text) for text in schedule]
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):
            if has_overlap(meetings[i], meetings[j]):
                clash = overlap_seconds(meetings[i], meetings[j])
                print("conflict: %s and %s share %d seconds"
                      % (schedule[i], schedule[j], clash))
    print("free time: %s" % format_time(free_seconds(meetings)))
    print("day booked: %d basis points" % busy_basis_points(meetings))

if __name__ == "__main__":
    main()

