import sys
import time

MAX_SENTENCE_LENGTH = 65536
MAX_WORD_LENGTH = 4096
MAX_WORDS = 10000
DIGEST_MODULUS = 1000000007
FLUSH_INTERVAL = 2048
HASH_BASE = 131


def split_sentence(sentence):
    """Validate the input and return its words in their original order."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str, got %s" % type(sentence).__name__)
    if len(sentence) > MAX_SENTENCE_LENGTH:
        raise ValueError("sentence longer than %d characters" % MAX_SENTENCE_LENGTH)
    words = sentence.split()
    if len(words) > MAX_WORDS:
        raise ValueError("sentence holds more than %d words" % MAX_WORDS)
    for word in words:
        if len(word) > MAX_WORD_LENGTH:
            raise ValueError("word longer than %d characters" % MAX_WORD_LENGTH)
    return words


def reverse_sentence_words(sentence):
    """Return the sentence with its words in reverse order."""
    words = split_sentence(sentence)
    words.reverse()
    return " ".join(words)


def sentence_digest(text):
    """Stable rolling hash used to label each processed line."""
    value = 0
    for char in text:
        value = (value * HASH_BASE + ord(char)) % DIGEST_MODULUS
    return value


def process_stream(sources):
    """Yield (reversed_text, digest) for every incoming sentence."""
    for raw in sources:
        reversed_text = reverse_sentence_words(raw)
        yield reversed_text, sentence_digest(reversed_text)


def format_stats(processed, elapsed):
    micros = int(elapsed * 1000000)
    if elapsed > 0:
        per_day = int(processed / elapsed * 86400)
    else:
        per_day = 0
    return "%d sentences in %d us (~%d/day)" % (processed, micros, per_day)


def main(argv):
    args = argv[1:]
    if args:
        sources = args
    else:
        sources = (line.rstrip("\n") for line in sys.stdin)
    start = time.perf_counter()
    processed = 0
    combined = 0
    for reversed_text, digest in process_stream(sources):
        processed += 1
        combined = (combined + digest) % DIGEST_MODULUS
        print(reversed_text)
        if processed % FLUSH_INTERVAL == 0:
            sys.stdout.flush()
    elapsed = time.perf_counter() - start
    sys.stderr.write(format_stats(processed, elapsed) + "\n")
    sys.stderr.write("combined digest: %d\n" % combined)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

