"""Body Mass Index helpers for clinic records.

A record stores mass in grams and stature in millimetres, so the module
keeps those integers for the range checks and the classification, and
only converts to kilograms and metres for the reported value.
"""

KG_PER_G = 0.001
M_PER_MM = 0.001
MIN_RECORD_WEIGHT_G = 20000
MAX_RECORD_WEIGHT_G = 500000
UNDERWEIGHT_MILLI_BMI = 18500
OVERWEIGHT_MILLI_BMI = 25000
OBESE_MILLI_BMI = 30000


def calculate_bmi(weight_kg, height_m):
    """Return the BMI for a mass in kilograms and a height in metres."""
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    if height_m <= 0:
        raise ValueError("height must be positive")
    return round(weight_kg / (height_m * height_m), 2)


def milli_bmi_from_record(weight_g, height_mm):
    """Return the BMI in thousandths for a record's raw integer fields."""
    if not MIN_RECORD_WEIGHT_G <= weight_g <= MAX_RECORD_WEIGHT_G:
        raise ValueError("weight out of plausible range")
    if height_mm <= 0:
        raise ValueError("height must be positive")
    return round(weight_g * 1000000 / (height_mm * height_mm))


def classify_milli_bmi(milli_bmi):
    """Name the category of a BMI expressed in thousandths."""
    if milli_bmi < UNDERWEIGHT_MILLI_BMI:
        return "underweight"
    if milli_bmi < OVERWEIGHT_MILLI_BMI:
        return "normal"
    if milli_bmi < OBESE_MILLI_BMI:
        return "overweight"
    return "obese"


def healthy_weight_range_g(height_mm):
    """Return the (min, max) healthy mass in grams for a height in mm."""
    square = height_mm * height_mm
    lowest = UNDERWEIGHT_MILLI_BMI * square / 1000000
    highest = (OVERWEIGHT_MILLI_BMI - 1) * square / 1000000
    return round(lowest), round(highest)


def parse_record(line):
    """Parse 'name,weight_g,height_mm' into (name, weight_g, height_mm)."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError("expected three fields: name, grams, millimetres")
    return parts[0], int(parts[1]), int(parts[2])


def build_report(lines):
    """Turn record lines into (name, bmi, category, min_g, max_g) rows."""
    rows = []
    for line in lines:
        name, weight_g, height_mm = parse_record(line)
        category = classify_milli_bmi(milli_bmi_from_record(weight_g, height_mm))
        bmi = calculate_bmi(weight_g * KG_PER_G, height_mm * M_PER_MM)
        low, high = healthy_weight_range_g(height_mm)
        rows.append((name, bmi, category, low, high))
    return rows


def main():
    records = ["Ada, 70000, 1750", "Grace, 90000, 1800", "Alan, 58500, 1680"]
    print(f"{'Name':8}{'BMI':>8}{'Category':>14}{'Healthy g':>16}")
    for name, bmi, category, low, high in build_report(records):
        print(f"{name:8}{bmi:>8.2f}{category:>14}{f'{low}-{high}':>16}")


if __name__ == "__main__":
    main()

