import time

MAX_ITEMS = 1000000
DEFAULT_CHUNK_SIZE = 10000
SAMPLE_SIZE = 25000


def validate_inputs(string_list, min_length):
    """Check the arguments accepted by filter_by_length."""
    if not isinstance(string_list, list):
        raise TypeError("string_list must be a list of str")
    if len(string_list) > MAX_ITEMS:
        raise ValueError("string_list may hold at most %d items" % MAX_ITEMS)
    if isinstance(min_length, bool) or not isinstance(min_length, int):
        raise TypeError("min_length must be an int")
    if min_length < 0:
        raise ValueError("min_length must not be negative")


def filter_by_length(string_list, min_length):
    """Return the strings of string_list that are longer than min_length."""
    validate_inputs(string_list, min_length)
    kept = []
    for item in string_list:
        if not isinstance(item, str):
            raise TypeError("string_list must contain only str, got %s" % type(item).__name__)
        if len(item) > min_length:
            kept.append(item)
    return kept


def filter_in_chunks(string_list, min_length, chunk_size=DEFAULT_CHUNK_SIZE):
    """Filter a long list piece by piece so peak memory stays bounded."""
    if chunk_size < 1:
        raise ValueError("chunk_size must be positive")
    kept = []
    for start in range(0, len(string_list), chunk_size):
        kept.extend(filter_by_length(string_list[start:start + chunk_size], min_length))
    return kept


def summarize(input_count, kept, elapsed):
    chars = sum(len(s) for s in kept)
    return {
        "input": input_count,
        "kept": len(kept),
        "chars": chars,
        "average": chars / len(kept) if kept else 0.0,
        "elapsed": elapsed,
    }


def format_report(summary):
    lines = [
        "input items    : %d" % summary["input"],
        "kept items     : %d" % summary["kept"],
        "kept chars     : %d" % summary["chars"],
        "average length : %.2f" % summary["average"],
        "elapsed (us)   : %.0f" % (summary["elapsed"] * 1000000),
    ]
    if summary["input"]:
        per_item = summary["elapsed"] / summary["input"]
        lines.append("per item (ns)  : %.1f" % (per_item * 1000000000))
    return "\n".join(lines)


def main():
    print(filter_by_length(['apple', 'cat', 'banana'], 4))
    print(filter_by_length(['a', 'b', 'c'], 2))

    words = ['apple', 'cat', 'banana', 'fig', 'strawberry', 'kiwi']
    sample = [words[i % len(words)] for i in range(SAMPLE_SIZE)]
    started = time.perf_counter()
    kept = filter_in_chunks(sample, 4)
    print(format_report(summarize(len(sample), kept, time.perf_counter() - started)))


if __name__ == "__main__":
    main()

