MAX_LINE_BYTES = 65536
MAX_ROWS = 10000


def parse_csv_line(line):
    """Split a single CSV row on commas, preserving empty fields."""
    if not isinstance(line, str):
        raise TypeError("line must be a string")
    if len(line.encode("utf-8")) > MAX_LINE_BYTES:
        raise ValueError("row exceeds %d bytes" % MAX_LINE_BYTES)
    stripped = line.rstrip("\r\n")
    if stripped == "":
        return []
    return stripped.split(",")


def parse_csv_rows(lines):
    """Parse an iterable of raw lines into (line number, fields) pairs."""
    rows = []
    for lineno, raw in enumerate(lines, 1):
        fields = parse_csv_line(raw)
        if not fields:
            continue
        if len(rows) >= MAX_ROWS:
            raise ValueError("input holds more than %d rows" % MAX_ROWS)
        rows.append((lineno, fields))
    return rows


def parse_record(lineno, fields):
