MAX_PERMUTATIONS = 1000000
MAX_OUTPUT_CHARS = 65536
MAX_OUTPUT_LINES = 10000
MICROS_PER_SECOND = 1000000
SECONDS_PER_DAY = 86400


def count_permutations(n):
    """Return n! -- the number of orderings of n distinct positions."""
    if n < 0:
        raise ValueError("length cannot be negative")
    total = 1
    for k in range(2, n + 1):
        total *= k
    return total


def _permute(items):
    if len(items) <= 1:
        return [list(items)]
    result = []
    for index, value in enumerate(items):
        rest = items[:index] + items[index + 1:]
        for tail in _permute(rest):
            result.append([value] + tail)
    return result


def generate_permutations(lst):
    """Return a list with every ordering of the elements of lst."""
    items = list(lst)
    expected = count_permutations(len(items))
    if expected > MAX_PERMUTATIONS:
        raise ValueError("refusing to materialise %d permutations" % expected)
    return _permute(items)


def format_permutations(perms, max_lines=MAX_OUTPUT_LINES,
                        max_chars=MAX_OUTPUT_CHARS):
    """Render permutations as text, truncating at the given limits."""
    lines = []
    used = 0
    for position, perm in enumerate(perms):
        line = "%d: %s" % (position, " ".join(str(item) for item in perm))
        if len(lines) >= max_lines or used + len(line) + 1 > max_chars:
            lines.append("... %d more omitted" % (len(perms) - position))
            break
        lines.append(line)
        used += len(line) + 1
    return "\n".join(lines)


def estimate_enumeration(n, micros_per_item):
    """Estimate the cost of listing all orderings of n items."""
    total = count_permutations(n)
    seconds = total * micros_per_item / float(MICROS_PER_SECOND)
    return total, seconds, seconds / SECONDS_PER_DAY


def describe_estimate(n, micros_per_item):
    total, seconds, days = estimate_enumeration(n, micros_per_item)
    if days >= 1:
        cost = "%.2f days" % days
    elif seconds >= 1:
        cost = "%.2f seconds" % seconds
    else:
        cost = "%.0f microseconds" % (seconds * MICROS_PER_SECOND)
    return "n=%d at %d us/item -> %d permutations, about %s" % (
        n, micros_per_item, total, cost
    )


def main():
    print(generate_permutations([1, 2]))
    print(generate_permutations(['a']))
    print(format_permutations(generate_permutations(['x', 'y', 'z'])))
    print(format_permutations(generate_permutations(list(range(4))),
                              max_lines=6))
    for size in (3, 8, 12, 15):
        print(describe_estimate(size, 45))


if __name__ == "__main__":
    main()

