import sys

HASH_MOD = 1000000007
HASH_BASE = 1000003
CHUNK_SIZE = 65536
BLOCK_SIZE = 10000
PER_MILLION = 1000000
MAX_REPORTED = 2000


def _string_hash(s):
    h = 0
    for ch in s:
        h = (h * HASH_BASE + ord(ch)) % HASH_MOD
    return h


def find_all_occurrences(text, pattern):
    """Return the starting indices of every (possibly overlapping) match."""
    if not pattern:
        return []
    n, m = len(text), len(pattern)
    if m > n:
        return []
    target = _string_hash(pattern)
    high_weight = pow(HASH_BASE, m - 1, HASH_MOD)
    rolling = _string_hash(text[:m])
    result = []
    for i in range(n - m + 1):
        if rolling == target and text[i:i + m] == pattern:
            result.append(i)
        if i + m < n:
            rolling = (rolling - ord(text[i]) * high_weight) % HASH_MOD
            rolling = (rolling * HASH_BASE + ord(text[i + m])) % HASH_MOD
    return result


def density(count, length):
    """Matches per million characters of text."""
    if length == 0:
        return 0.0
    return count * PER_MILLION / length


def block_histogram(indices, length):
    """Count matches inside every fixed-size block of the text."""
    blocks = []
    for start in range(0, length, BLOCK_SIZE):
        hits = sum(1 for i in indices if start <= i < start + BLOCK_SIZE)
        if hits:
            blocks.append((start, hits))
    return blocks


def search_stream(stream, pattern, chunk_size=CHUNK_SIZE):
    """Scan a text stream chunk by chunk; return (indices, total_length)."""
    indices = []
    carry = ""
    offset = 0
    total = 0
    overlap = max(len(pattern) - 1, 0)
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        total += len(chunk)
        buf = carry + chunk
        for i in find_all_occurrences(buf, pattern):
            indices.append(offset + i)
        if len(buf) > overlap:
            carry = buf[len(buf) - overlap:] if overlap else ""
            offset += len(buf) - len(carry)
        else:
            carry = buf
    return indices, total


def format_report(pattern, indices, length, limit=MAX_REPORTED):
    lines = [
        "pattern: %r" % pattern,
        "text length: %d" % length,
        "occurrences: %d" % len(indices),
        "density: %.3f per million characters" % density(len(indices), length),
        "indices: " + ", ".join(str(i) for i in indices[:limit]),
    ]
    if len(indices) > limit:
        lines.append("... %d further indices omitted" % (len(indices) - limit))
    for start, hits in block_histogram(indices, length):
        lines.append("block %d-%d: %d" % (start, start + BLOCK_SIZE - 1, hits))
    return "\n".join(lines)


def main(argv):
    if len(argv) < 2:
        print("usage: %s PATTERN [FILE]" % argv[0], file=sys.stderr)
        return 2
    pattern = argv[1]
    if len(argv) > 2:
        with open(argv[2], encoding="utf-8") as handle:
            indices, total = search_stream(handle, pattern)
    else:
        text = sys.stdin.read()
        indices, total = find_all_occurrences(text, pattern), len(text)
    print(format_report(pattern, indices, total))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

