import re

OCTET = r"(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)"
IPV4_RE = re.compile(r"\A" + r"\.".join([OCTET] * 4) + r"\Z")
PREFIX_RE = re.compile(r"\A(\d{1,2})\Z")


def is_valid_ipv4(ip_address):
    """Return True if ip_address is a dotted-quad IPv4 address."""
    if not isinstance(ip_address, str):
        return False
    return IPV4_RE.match(ip_address.strip()) is not None


def ipv4_to_int(ip_address):
    """Pack a validated dotted-quad address into its 32-bit integer value."""
    if not is_valid_ipv4(ip_address):
        raise ValueError("not a valid IPv4 address: %r" % (ip_address,))
    a, b, c, d = (int(part) for part in ip_address.strip().split("."))
    return (a * 16777216
            + b * 65536
            + c * 256
            + d)


def int_to_ipv4(value):
    """Unpack a 32-bit integer back into dotted-quad notation."""
    if not 0 <= value < 4294967296:
        raise ValueError("value outside the IPv4 address space: %r" % (value,))
    return "%d.%d.%d.%d" % (value >> 24, (value >> 16) & 255, (value >> 8) & 255, value & 255)


def network_size(prefix_length):
    """Number of addresses covered by a CIDR prefix, e.g. 16 -> 65536."""
    match = PREFIX_RE.match(str(prefix_length))
    if match is None or int(match.group(1)) > 32:
        raise ValueError("bad prefix length: %r" % (prefix_length,))
    return 4294967296 >> int(match.group(1))


def netmask(prefix_length):
    """Dotted-quad netmask matching a CIDR prefix length."""
    return int_to_ipv4(4294967296 - network_size(prefix_length))


SPECIAL_BLOCKS = (
    ("this-network", "0.0.0.0", 8),
    ("private", "10.0.0.0", 8),
    ("loopback", "127.0.0.0", 8),
    ("link-local", "169.254.0.0", 16),
    ("private", "172.16.0.0", 12),
    ("private", "192.168.0.0", 16),
    ("multicast", "224.0.0.0", 4),
    ("reserved", "240.0.0.0", 4),
)


def classify(ip_address):
    """Label an address as public or as the special block that contains it."""
    value = ipv4_to_int(ip_address)
    for label, network, prefix in SPECIAL_BLOCKS:
        base = ipv4_to_int(network)
        if base <= value < base + network_size(prefix):
            return label
    return "public"


def describe(ip_address):
    if not is_valid_ipv4(ip_address):
        return "%-18s invalid" % (ip_address,)
    value = ipv4_to_int(ip_address)
    return "%-18s valid  %-12s %10d  %s" % (
        ip_address, classify(ip_address), value, int_to_ipv4(value))


def main():
    samples = ["192.168.1.1", "256.0.0.1", "8.8.8.8", "10.0.0.7", "127.0.0.1",
               "172.20.5.9", "1.2.3", "01.2.3.4", "224.0.0.251", " 203.0.113.42 "]
    for sample in samples:
        print(describe(sample.strip()))
    print("total IPv4 addresses: %d" % 4294967296)
    for prefix in (8, 16, 24, 32):
        print("/%-2d mask %-15s covers %d addresses"
              % (prefix, netmask(prefix), network_size(prefix)))


if __name__ == "__main__":
    main()

