import re
from collections import Counter

MAX_TEXT_LENGTH = 65536
SECONDS_PER_DAY = 86400
BASIS_POINTS = 10000
DEFAULT_WINDOW_SECONDS = 43200
HASHTAG_RE = re.compile(r"#([A-Za-z0-9]+)")


def extract_hashtags(text):
    """Return every hashtag in `text`, without the '#', in original casing."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text exceeds %d characters" % MAX_TEXT_LENGTH)
    return HASHTAG_RE.findall(text)


def tally(texts):
    """Count hashtags case-insensitively, keeping the first casing seen."""
    counts = Counter()
    casing = {}
    for text in texts:
        for tag in extract_hashtags(text):
            key = tag.lower()
            counts[key] += 1
            casing.setdefault(key, tag)
    return counts, casing


def density_per_million(counts, texts):
    """Hashtag occurrences per million characters of analysed text."""
    total_chars = sum(len(text) for text in texts)
    if total_chars == 0:
        return {}
    return {tag: n * 1000000 / float(total_chars)
            for tag, n in counts.items()}


def daily_rate(counts, window_seconds):
    """Extrapolate each hashtag's count to a rate per 24 hours."""
    if window_seconds <= 0:
        raise ValueError("window_seconds must be positive")
    factor = SECONDS_PER_DAY / float(window_seconds)
    return {tag: n * factor for tag, n in counts.items()}


def format_report(texts, window_seconds=DEFAULT_WINDOW_SECONDS):
    """Build a table of hashtag counts, share, density and daily rate."""
    counts, casing = tally(texts)
    density = density_per_million(counts, texts)
    rates = daily_rate(counts, window_seconds)
    total = sum(counts.values())
    lines = ["tag              count   share(bp)   per 1e6 chars   per day"]
    for tag, n in counts.most_common():
        share = n * BASIS_POINTS // total
        lines.append("%-15s %6d %11d %15.1f %9.1f"
                     % (casing[tag], n, share, density[tag], rates[tag]))
    return "\n".join(lines)


def main():
    posts = [
        "This is a #test with #Python.",
        "No hashtags here!",
        "#python is fun, #Test2 passed, #python again",
        "Long thread about #Rust and #python performance",
    ]
    print(extract_hashtags(posts[0]))
    print(extract_hashtags(posts[1]))
    print(format_report(posts))


if __name__ == "__main__":
    main()

