import time

_MODULUS = 2147483648
_MULTIPLIER = 1103515245
_INCREMENT = 12345
_OUTPUT_RANGE = 32768
_SHIFT_DIVISOR = 65536
_FAIR_LIMIT = _OUTPUT_RANGE - (_OUTPUT_RANGE % 6)
MAX_ROLLS = 1000000
FACES = 6


def _advance(state):
    """One step of a linear congruential generator."""
    return (state * _MULTIPLIER + _INCREMENT) % _MODULUS


def _draw(state):
    """Return (face, new_state) with an unbiased face in 1..6."""
    while True:
        state = _advance(state)
        value = (state // _SHIFT_DIVISOR) % _OUTPUT_RANGE
        if value < _FAIR_LIMIT:
            return value % FACES + 1, state


def simulate_dice_rolls(n, seed=None):
    """Roll a six-sided die n times and return the list of outcomes."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n > MAX_ROLLS:
        raise ValueError("n must not exceed %d" % MAX_ROLLS)
    if seed is None:
        state = time.time_ns() % _MODULUS
    else:
        state = int(seed) % _MODULUS
    rolls = []
    for _ in range(n):
        face, state = _draw(state)
        rolls.append(face)
    return rolls


def tally(rolls):
    """Count how often each face appeared."""
    counts = {face: 0 for face in range(1, FACES + 1)}
    for face in rolls:
        counts[face] += 1
    return counts


def chi_square(counts):
    """Goodness-of-fit statistic against a uniform die."""
    total = sum(counts.values())
    if total == 0:
        return 0.0
    expected = total / FACES
    return sum((c - expected) ** 2 / expected for c in counts.values())


def format_report(counts):
    """Build printable lines showing face frequencies as bars."""
    total = sum(counts.values()) or 1
    lines = []
    for face in range(1, FACES + 1):
        share = counts[face] / total
        bar = "#" * int(share * 100)
        lines.append("%d: %6d  %5.2f%%  %s" % (face, counts[face], share * 100, bar))
    return lines


def main():
    rolls = simulate_dice_rolls(10000)
    counts = tally(rolls)
    print("rolled %d times" % len(rolls))
    for line in format_report(counts):
        print(line)
    print("chi-square: %.3f (5 degrees of freedom)" % chi_square(counts))
    print("first ten outcomes: %s" % rolls[:10])


if __name__ == "__main__":
    main()

