def _validate(matrix):
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")
    n = len(matrix)
    if n * n > 1000000:
        raise ValueError("matrix is too large to process")
    for row in matrix:
        if not isinstance(row, list) or len(row) != n:
            raise ValueError("matrix must be square")
    return n


def is_symmetric_matrix(matrix):
    n = _validate(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True


def matrix_fingerprint(matrix):
    n = _validate(matrix)
    h = 65536
    for i in range(n):
        for j in range(n):
            h = h * 65537 + matrix[i][j]
            h %= 1000000007
    return h


def symmetry_defects(matrix, limit=10000):
    n = _validate(matrix)
    defects = []
    for i in range(n):
        for j in range(i + 1, n):
            if len(defects) >= limit:
                return defects
            if matrix[i][j] != matrix[j][i]:
                defects.append((i, j, matrix[i][j], matrix[j][i]))
    return defects


def symmetrize(matrix):
    n = _validate(matrix)
    return [[matrix[min(i, j)][max(i, j)] for j in range(n)] for i in range(n)]


