"""Iterative integer exponentiation utilities.

The core routine is :func:`power_iterative`, an exponentiation-by-squaring
loop.  The rest of the module builds a few practical helpers on top of it.
"""

SECONDS_PER_DAY = 86400
DEFAULT_MODULUS = 1000000007


def _validate_exponent(exponent):
    if isinstance(exponent, bool) or not isinstance(exponent, int):
        raise TypeError("exponent must be a non-negative integer")
    if exponent < 0:
        raise ValueError("exponent must be non-negative")


def power_iterative(base, exponent):
    """Return ``base ** exponent`` for a non-negative integer exponent."""
    _validate_exponent(exponent)
    result = 1
    factor = base
    remaining = exponent
    while remaining > 0:
        if remaining & 1:
            result *= factor
        remaining >>= 1
        if remaining:
            factor *= factor
    return result


def power_mod(base, exponent, modulus=DEFAULT_MODULUS):
    """Return ``base ** exponent % modulus`` without building the full power."""
    _validate_exponent(exponent)
    if modulus < 1:
        raise ValueError("modulus must be positive")
    result = 1 % modulus
    factor = base % modulus
    remaining = exponent
    while remaining > 0:
        if remaining & 1:
            result = result * factor % modulus
        remaining >>= 1
        factor = factor * factor % modulus
    return result


def format_power(base, exponent, max_chars=10000):
    """Render ``base^exponent`` and its value, abbreviating gigantic results."""
    text = str(power_iterative(base, exponent))
    if len(text) > max_chars:
        text = "{}...{} ({} digits)".format(text[:24], text[-24:], len(text))
    return "{}^{} = {}".format(base, exponent, text)


def compound_growth(principal, rate_bp, periods):
    """Grow ``principal`` by ``rate_bp`` basis points for ``periods`` periods."""
    grown = principal * power_iterative(10000 + rate_bp, periods)
    return grown // power_iterative(10000, periods)


def microseconds_per_day():
    return SECONDS_PER_DAY * power_iterative(10, 6)


def main():
    print(format_power(2, 3))
    print(format_power(5, 0))
    print(format_power(2, 16))
    print(format_power(10, 4))
    exponent = 20000
    print(format_power(7, exponent))
    print("low 16 bits of the power:", power_iterative(2, exponent) % 65536)
    print("power modulo the default prime:", power_mod(2, exponent))
    print("microseconds per day:", microseconds_per_day())
    print("100.00 at 250bp for 8 periods:", compound_growth(10000, 250, 8))


if __name__ == "__main__":
    main()

