import random
from collections import Counter

MAX_INPUT_STRINGS = 1000000
MAX_MIN_LENGTH = 65536
DEFAULT_BATCH_SIZE = 32768


def filter_by_length(strings: list[str], min_length: int) -> list[str]:
    """Return the strings whose length is strictly greater than min_length."""
    if len(strings) > MAX_INPUT_STRINGS:
        raise ValueError(f"at most {MAX_INPUT_STRINGS} strings can be filtered at once")
    if isinstance(min_length, bool) or not isinstance(min_length, int):
        raise TypeError("min_length must be an int")
    if min_length < 0 or min_length > MAX_MIN_LENGTH:
        raise ValueError(f"min_length must be between 0 and {MAX_MIN_LENGTH}")
    kept = []
    for item in strings:
        if not isinstance(item, str):
            raise TypeError(f"expected str, got {type(item).__name__}")
        if len(item) > min_length:
            kept.append(item)
    return kept


def filter_in_batches(strings: list[str], min_length: int,
                      batch_size: int = DEFAULT_BATCH_SIZE) -> list[str]:
    """Filter a very long list in slices, so no single call exceeds the cap."""
    if batch_size < 1 or batch_size > MAX_INPUT_STRINGS:
        raise ValueError("batch_size out of range")
    kept = []
    for start in range(0, len(strings), batch_size):
        kept.extend(filter_by_length(strings[start:start + batch_size], min_length))
    return kept


def length_histogram(strings: list[str]) -> Counter:
    """Count how many strings have each length."""
    return Counter(len(item) for item in strings)


def filter_report(strings: list[str], min_length: int) -> str:
    """Human readable summary of what filter_by_length keeps and drops."""
    kept = filter_by_length(strings, min_length)
    total = len(strings)
    basis_points = (len(kept) * 10000) // total if total else 0
    lines = [
        f"input strings : {total}",
        f"min_length    : {min_length}",
        f"kept          : {len(kept)} ({basis_points / 100:.2f}%)",
        f"dropped       : {total - len(kept)}",
    ]
    histogram = length_histogram(strings)
    for length, count in sorted(histogram.items())[:5]:
        marker = "keep" if length > min_length else "drop"
        lines.append(f"  length {length:>3}: {count:>6} strings -> {marker}")
    return "\n".join(lines)


def random_words(count: int, seed: int = 20260918) -> list[str]:
    """Build a reproducible sample of lowercase words for the driver."""
    rng = random.Random(seed)
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    return ["".join(rng.choice(alphabet) for _ in range(rng.randint(1, 12)))
            for _ in range(count)]


def main() -> None:
    print(filter_by_length(['apple', 'bat', 'catamaran'], 4))
    print(filter_by_length(['a', 'bb', 'ccc'], 5))

    sample = random_words(100000)
    long_words = filter_in_batches(sample, 8)
    print(f"words longer than 8 chars: {len(long_words)} of {len(sample)}")
    print(filter_report(sample, 8))


if __name__ == "__main__":
    main()

