"""Geometric sequence utilities: generation, summation and reporting."""

import math


def geometric_sequence(a: float, r: float, n: int) -> list[float]:
    """Return the first n terms of the geometric sequence a, a*r, a*r^2, ..."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n > 10000:
        raise ValueError("n must not exceed 10000 terms")
    terms = []
    value = float(a)
    for _ in range(n):
        terms.append(value)
        value *= r
    return terms


def nth_term(a: float, r: float, k: int) -> float:
    """Return the k-th term (1-based) without building the whole sequence."""
    if k < 1 or k > 10000:
        raise ValueError("k must lie between 1 and 10000")
    return float(a) * float(r) ** (k - 1)


def geometric_sum(a: float, r: float, n: int) -> float:
    """Sum of the first n terms."""
    if r == 1:
        return float(a) * n
    return float(a) * (1.0 - float(r) ** n) / (1.0 - float(r))


def terms_to_reach(a: float, r: float, target: float) -> int:
    """Smallest 1-based index whose term reaches target, or 0 if unreachable."""
    if a == 0 or r <= 0 or (r <= 1 and abs(a) < abs(target)):
        return 0
    steps = math.log(abs(target) / abs(a)) / math.log(r)
    return max(1, math.ceil(steps) + 1)


def format_term(x: float) -> str:
    """Render a single term, switching to scientific notation at the extremes."""
    if x != 0 and (abs(x) >= 1000000 or abs(x) < 0.0001):
        return f"{x:.6e}"
    return f"{x:.4f}".rstrip("0").rstrip(".")


def format_sequence(a: float, r: float, n: int) -> str:
    """Render a whole sequence together with the sum of its terms."""
    terms = geometric_sequence(a, r, n)
    body = ", ".join(format_term(t) for t in terms)
    return f"[{body}]  (sum = {format_term(geometric_sum(a, r, n))})"


def buffer_report() -> str:
    """Describe a buffer that doubles until it can hold a full mebibyte."""
    start = 65536
    count = terms_to_reach(start, 2, 1048576)
    sizes = [int(s) for s in geometric_sequence(start, 2, count)]
    return (f"buffers {sizes}, term {count} = {int(nth_term(start, 2, count))}"
            f" bytes, allocated in total {int(geometric_sum(start, 2, count))}")


def main() -> None:
    print(geometric_sequence(2, 3, 4))
    print(geometric_sequence(10, 0.5, 3))
    print("doubling from 1:", format_sequence(1, 2, 12))
    print("repeatedly halved daily sample count:",
          format_sequence(86400, 0.5, 5))
    print(buffer_report())


if __name__ == "__main__":
    main()

