"""Group words into families of anagrams, ignoring letter case.

The grouping is driven by a *letter signature*: the sorted, case-folded
letters of a word.  Signatures are indexed through a small hash table so
that long signatures are compared only inside a single bucket.
"""

import sys

MAX_WORD_LENGTH = 10000


def letter_signature(word: str) -> str:
    """Return the canonical, case-insensitive signature of ``word``."""
    if len(word) > MAX_WORD_LENGTH:
        raise ValueError("word longer than %d characters" % MAX_WORD_LENGTH)
    return "".join(sorted(word.casefold()))


def signature_hash(signature: str) -> int:
    """Polynomial hash of a signature, base 65536 (one BMP code unit)."""
    value = 0
    for char in signature:
        value = value * 65536 + ord(char)
        value %= 1000000007
    return value


def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group ``words`` so that each inner list holds mutual anagrams."""
    if len(words) > 1000000:
        raise ValueError("input list too large to group in memory")
    table: dict[int, list[tuple[str, list[str]]]] = {}
    groups: list[list[str]] = []
    for word in words:
        signature = letter_signature(word)
        bucket = table.setdefault(signature_hash(signature) & 65535, [])
        for stored_signature, group in bucket:
            if stored_signature == signature:
                group.append(word)
                break
        else:
            group = [word]
            bucket.append((signature, group))
            groups.append(group)
    return groups


def largest_group(groups: list[list[str]]) -> list[str]:
    """Return the biggest anagram family (empty list if there is none)."""
    return max(groups, key=len, default=[])


def format_report(groups: list[list[str]]) -> str:
    """Render the groups, biggest first, with each family's share."""
    if not groups:
        return "no words to group"
    total = sum(len(group) for group in groups)
    lines = ["%d word(s) in %d anagram group(s)" % (total, len(groups))]
    for group in sorted(groups, key=lambda g: (-len(g), g[0].casefold())):
        basis_points = len(group) * 10000 // total
        lines.append("%6.2f%%  %s" % (basis_points / 100.0, ", ".join(group)))
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    words = argv[1:]
    if not words:
        words = ["eat", "tea", "tan", "ate", "nat", "bat",
                 "listen", "Silent", "hello"]
    groups = group_anagrams(words)
    print(format_report(groups))
    biggest = largest_group(groups)
    if biggest:
        print("largest family: %s (%d words)" % (biggest[0], len(biggest)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

