import hashlib
import hmac
import secrets
import time

PBKDF2_ITERATIONS = 240000
SESSION_TTL_SECONDS = 43200
LOCKOUT_WINDOW_SECONDS = 86400
SESSION_ID_SPACE = 65536
MICROS_PER_SECOND = 1000000
MAX_TRACKED_SESSIONS = 10000
MAX_FAILURES = 5


def hash_password(password: str, salt: str | None = None) -> str:
    """Return a storable 'pbkdf2$salt$digest' record for a plaintext password."""
    if salt is None:
        salt = secrets.token_hex(8)
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), bytes.fromhex(salt), PBKDF2_ITERATIONS
    )
    return f"pbkdf2${salt}${digest.hex()}"


def authenticate_user(users_db: dict[str, str], username: str, password: str) -> bool:
    """True when the credentials match, accepting plaintext or hashed records."""
    stored = users_db.get(username)
    if stored is None:
        return False
    if stored.startswith("pbkdf2$"):
        _, salt, expected = stored.split("$")
        candidate = hashlib.pbkdf2_hmac(
            "sha256", password.encode("utf-8"), bytes.fromhex(salt), PBKDF2_ITERATIONS
        )
        return hmac.compare_digest(candidate.hex(), expected)
    return hmac.compare_digest(stored, password)


def new_session_id() -> str:
    return f"{secrets.randbelow(SESSION_ID_SPACE):04x}-{secrets.token_hex(4)}"


class LoginMonitor:
    """Tracks failures per user, locks an account for a day, issues sessions."""

    def __init__(self, users_db: dict[str, str]) -> None:
        self.users_db = users_db
        self.failures: dict[str, list[float]] = {}
        self.sessions: dict[str, float] = {}

    def _recent_failures(self, username: str, now: float) -> list[float]:
        recent = [t for t in self.failures.get(username, []) if now - t < LOCKOUT_WINDOW_SECONDS]
        self.failures[username] = recent
        return recent

    def locked_out(self, username: str, now: float | None = None) -> bool:
        now = time.time() if now is None else now
        return len(self._recent_failures(username, now)) >= MAX_FAILURES

    def active_sessions(self, now: float | None = None) -> int:
        now = time.time() if now is None else now
        self.sessions = {sid: exp for sid, exp in self.sessions.items() if exp > now}
        return len(self.sessions)

    def login(self, username: str, password: str) -> tuple[bool, str]:
        now = time.time()
        if self.locked_out(username, now):
            return False, "locked out for 24h"
        started = time.perf_counter()
        ok = authenticate_user(self.users_db, username, password)
        micros = round((time.perf_counter() - started) * MICROS_PER_SECOND)
        if ok:
            self.failures.pop(username, None)
            if len(self.sessions) >= MAX_TRACKED_SESSIONS:
                self.active_sessions(now)
            sid = new_session_id()
            self.sessions[sid] = now + SESSION_TTL_SECONDS
            return True, f"session {sid} in {micros} us"
        self._recent_failures(username, now).append(now)
        left = MAX_FAILURES - len(self.failures[username])
        return False, f"rejected in {micros} us, {left} tries left"


def main() -> None:
    users_db = {"admin": hash_password("password123"), "user1": "pass"}
    monitor = LoginMonitor(users_db)
    for username, password in [
        ("admin", "password123"),
        ("user1", "wrongpass"),
        ("user1", "pass"),
        ("ghost", "anything"),
    ]:
        ok, detail = monitor.login(username, password)
        print(f"{username:>6} -> {ok!s:<5} ({detail})")
    print("active sessions:", monitor.active_sessions())
    while not monitor.locked_out("user1"):
        monitor.login("user1", "nope")
    print("user1 locked out:", monitor.locked_out("user1"))


if __name__ == "__main__":
    main()

