"""Triangular numbers: computation, recognition and a small report."""

from math import isqrt

REPORT_LIMIT = 10000
UINT16_STATES = 65536
SECONDS_PER_DAY = 86400
ONE_MILLION = 1000000
ONE_BILLION = 1000000000


def triangular_number(n: int) -> int:
    """Return the nth triangular number, 1 + 2 + ... + n."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return n * (n + 1) // 2


def is_triangular(value: int) -> bool:
    """Return True if value is a triangular number."""
    if value < 0:
        return False
    root = isqrt(8 * value + 1)
    return root * root == 8 * value + 1


def triangular_index(value: int) -> int:
    """Return n such that triangular_number(n) == value, or -1 if none."""
    if not is_triangular(value):
        return -1
    return (isqrt(8 * value + 1) - 1) // 2


def triangular_numbers_below(limit: int) -> list:
    """Return every triangular number strictly smaller than limit."""
    result = []
    n = 1
    while True:
        t = triangular_number(n)
        if t >= limit:
            return result
        result.append(t)
        n += 1


def first_triangular_at_least(limit: int) -> tuple:
    """Return (n, triangular_number(n)) for the first value >= limit."""
    n = max(0, (isqrt(8 * max(limit, 0) + 1) - 1) // 2)
    while triangular_number(n) < limit:
        n += 1
    return n, triangular_number(n)


def format_thousands(value: int) -> str:
    """Format an integer with commas between groups of three digits."""
    digits = str(abs(value))
    groups = []
    while len(digits) > 3:
        groups.append(digits[-3:])
        digits = digits[:-3]
    groups.append(digits)
    sign = "-" if value < 0 else ""
    return sign + ",".join(reversed(groups))


def describe(value: int) -> str:
    """Report whether value is triangular, naming the nearest index."""
    index = triangular_index(value)
    if index < 0:
        n, t = first_triangular_at_least(value)
        return (f"{format_thousands(value)} is not triangular; "
                f"next is T({n}) = {format_thousands(t)}")
    return f"{format_thousands(value)} is triangular: T({index})"


def main() -> None:
    for n in (1, 4, 10, 100):
        print(f"T({n}) = {format_thousands(triangular_number(n))}")

    small = triangular_numbers_below(REPORT_LIMIT)
    print(f"{len(small)} triangular numbers below {format_thousands(REPORT_LIMIT)}")
    print(f"largest of them: {format_thousands(small[-1])}")
    print(f"their sum: {format_thousands(sum(small))}")

    for value in (UINT16_STATES, SECONDS_PER_DAY, ONE_MILLION, ONE_BILLION):
        print(describe(value))


if __name__ == "__main__":
    main()

