import sys
from collections import Counter

VOWELS = "aeiou"
VOWEL_SET = frozenset(VOWELS)
MAX_TEXT_LENGTH = 1000000
CHUNK_SIZE = 65536
PROGRESS_STEP = 10000


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitively."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text is too long for count_vowels; use count_vowels_in_stream")
    lowered = text.lower()
    vowel_count = sum(1 for ch in lowered if ch in VOWEL_SET)
    return vowel_count


def vowel_histogram(text):
    """Return a Counter mapping each vowel to how often it occurs in text."""
    lowered = text.lower()
    return Counter(ch for ch in lowered if ch in VOWEL_SET)


def vowel_density_ppm(text):
    """Vowels per million letters, a scale-free way to compare texts."""
    letters = sum(1 for ch in text if ch.isalpha())
    if letters == 0:
        return 0
    return round(count_vowels(text) * 1000000 / letters)


def count_vowels_in_stream(stream, chunk_size=CHUNK_SIZE, progress=None):
    """Count vowels in a text stream of any size; returns (chars, letters, vowels)."""
    chars = letters = vowels = 0
    next_mark = PROGRESS_STEP
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        lowered = chunk.lower()
        vowels += sum(1 for ch in lowered if ch in VOWEL_SET)
        letters += sum(1 for ch in lowered if ch.isalpha())
        chars += len(chunk)
        if progress is not None and chars >= next_mark:
            progress(chars, vowels)
            next_mark = chars + PROGRESS_STEP
    return chars, letters, vowels


def format_report(label, chars, letters, vowels):
    ppm = 0 if letters == 0 else round(vowels * 1000000 / letters)
    return "%s: %d chars, %d letters, %d vowels (%d per million letters)" % (
        label, chars, letters, vowels, ppm)


def show_progress(chars, vowels):
    sys.stderr.write("  ...%d chars scanned, %d vowels so far\n" % (chars, vowels))


def main(argv):
    paths = argv[1:]
    if paths:
        for path in paths:
            with open(path, encoding="utf-8", errors="replace") as handle:
                chars, letters, vowels = count_vowels_in_stream(handle, progress=show_progress)
            print(format_report(path, chars, letters, vowels))
        return 0
    for sample in ("Hello World", "Python"):
        histogram = vowel_histogram(sample)
        detail = ", ".join("%s=%d" % (v, histogram[v]) for v in VOWELS if histogram[v])
        print("%r -> %d vowels (%s)" % (sample, count_vowels(sample), detail))
        print("   density: %d vowels per million letters" % vowel_density_ppm(sample))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

