import sys
import time

MAX_TEXT_LENGTH = 1000000
CHUNK_SIZE = 65536
CATEGORIES = ('uppercase', 'lowercase', 'digits')


def count_char_types(text):
    """Count uppercase letters, lowercase letters and digits in *text*."""
    if not isinstance(text, str):
        raise TypeError('text must be a str, got %s' % type(text).__name__)
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError('text longer than %d characters; use count_stream'
                         % MAX_TEXT_LENGTH)
    counts = {'uppercase': 0, 'lowercase': 0, 'digits': 0}
    for ch in text:
        if ch.isupper():
            counts['uppercase'] += 1
        elif ch.islower():
            counts['lowercase'] += 1
        elif ch.isdigit():
            counts['digits'] += 1
    return counts


def merge_counts(left, right):
    """Add the per-category totals of two count dictionaries."""
    return {key: left[key] + right[key] for key in CATEGORIES}


def count_stream(stream, chunk_size=CHUNK_SIZE):
    """Count character types in a text stream of arbitrary size."""
    totals = {key: 0 for key in CATEGORIES}
    scanned = 0
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        totals = merge_counts(totals, count_char_types(chunk))
        scanned += len(chunk)
    return totals, scanned


def format_report(counts, scanned, elapsed):
    """Render the counts as aligned lines with percentages and a timing line."""
    lines = []
    for key in CATEGORIES:
        value = counts[key]
        basis_points = (value * 10000) // scanned if scanned else 0
        lines.append('%-9s %8d  %3d.%02d%%'
                     % (key + ':', value, basis_points // 100, basis_points % 100))
    lines.append('%-9s %8d' % ('scanned:', scanned))
    lines.append('%-9s %8d us' % ('elapsed:', int(elapsed * 1000000)))
    return '\n'.join(lines)


def estimate_daily_capacity(chars, seconds):
    """Characters this scanning rate would process in a full day."""
    if seconds <= 0:
        return 0
    return int(chars / seconds * 86400)


def main(argv):
    totals = {key: 0 for key in CATEGORIES}
    scanned = 0
    started = time.perf_counter()
    if len(argv) > 1:
        for path in argv[1:]:
            with open(path, 'r', encoding='utf-8', errors='replace') as handle:
                part, size = count_stream(handle)
            totals = merge_counts(totals, part)
            scanned += size
    else:
        totals, scanned = count_stream(sys.stdin)
    elapsed = time.perf_counter() - started
    print(format_report(totals, scanned, elapsed))
    print('capacity: %d chars/day' % estimate_daily_capacity(scanned, elapsed))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

