    "0": _english_registrant_width,
    "1": _english_registrant_width,
    "2": _french_registrant_width,
}


def _clean(isbn):
    return isbn.replace("-", "").replace(" ", "").upper()


def _digit_values(cleaned):
    values = []
    for index, char in enumerate(cleaned):
        if char.isdigit():
            values.append(int(char))
        elif char == "X" and index == 9:
            values.append(10)
        else:
            return None
    return values


