    cleaned = _clean(isbn)
    if not is_valid_isbn10(cleaned):
        raise ValueError("not a valid ISBN-10: %r" % isbn)
    width_of = WIDTH_BY_GROUP.get(cleaned[0])
    if width_of is None:
        return cleaned
    body = cleaned[1:9]
    width = width_of(body)
    return "-".join([cleaned[0], body[:width], body[width:], cleaned[9]])


