ZIP_LENGTH = 5
PLUS_FOUR_LENGTH = 4
DIGITS = "0123456789"

REGION_BOUNDS = (
    (10000, "Northeast"),
    (20000, "Mid-Atlantic"),
    (40000, "Southeast"),
    (60000, "Midwest"),
    (80000, "South Central"),
    (90000, "Mountain"),
    (100000, "Pacific"),
)

LOWEST_ASSIGNED = 501
HIGHEST_ASSIGNED = 99950

import sys


def is_valid_us_zip(zip_code_str):
    """Return True when the string is exactly five decimal digits."""
    if len(zip_code_str) != ZIP_LENGTH:
        return False
    return all(character in DIGITS for character in zip_code_str)


def normalize_zip(text):
    """Pad a loosely written numeric code to canonical 5-digit form."""
    candidate = text.strip()
    if candidate.isdigit() and len(candidate) <= ZIP_LENGTH:
        return candidate.zfill(ZIP_LENGTH)
    return None


def is_valid_zip_plus_four(zip_code_str):
    """Validate the 'NNNNN-NNNN' extended form."""
    if zip_code_str.count("-") != 1:
        return False
    base, extension = zip_code_str.split("-")
    if not is_valid_us_zip(base):
        return False
    if len(extension) != PLUS_FOUR_LENGTH or not extension.isdigit():
        return False
    return int(extension) < 10000


def is_assigned_zip(zip_code_str):
    """Codes outside the assigned postal window are well formed but unused."""
    if not is_valid_us_zip(zip_code_str):
        return False
    return LOWEST_ASSIGNED <= int(zip_code_str) <= HIGHEST_ASSIGNED


def zip_region(zip_code_str):
    if not is_valid_us_zip(zip_code_str):
        return None
    numeric = int(zip_code_str)
    for upper_bound, region_name in REGION_BOUNDS:
        if numeric < upper_bound:
            return region_name
    return None


def describe(text):
    canonical = normalize_zip(text)
    if canonical is None:
        if is_valid_zip_plus_four(text):
            base = text.split("-")[0]
            return "%s  valid ZIP+4, region %s" % (text, zip_region(base))
        return "%s  not a usable ZIP code" % text
    if not is_assigned_zip(canonical):
        return "%s  well formed but unassigned" % canonical
    return "%s  valid, region %s" % (canonical, zip_region(canonical))


def main(argv):
    if len(argv) < 2:
        print("usage: %s ZIP [ZIP ...]" % argv[0], file=sys.stderr)
        return 2
    for item in argv[1:]:
        print(describe(item))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

