import time

CHOICES = ('Rock', 'Paper', 'Scissors')
BEATS = {'Rock': 'Scissors', 'Paper': 'Rock', 'Scissors': 'Paper'}
OUTCOMES = ('Player 1 wins', 'Player 2 wins', "It's a tie!")

LCG_MULTIPLIER = 1103515245
LCG_INCREMENT = 12345
LCG_MODULUS = 2147483648
LCG_DISCARD_LOW = 65536
DEFAULT_SEED = 20240918


def _normalize(choice: str) -> str:
    if not isinstance(choice, str):
        raise TypeError('choices must be strings, got %r' % type(choice).__name__)
    name = choice.strip().capitalize()
    if name not in BEATS:
        raise ValueError('invalid choice: %r' % choice)
    return name


def rock_paper_scissors_winner(p1_choice: str, p2_choice: str) -> str:
    first = _normalize(p1_choice)
    second = _normalize(p2_choice)
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return 'Player 1 wins'
    return 'Player 2 wins'


def lcg_choices(seed: int, count: int):
    state = seed % LCG_MODULUS
    for _ in range(count):
        state = (LCG_MULTIPLIER * state + LCG_INCREMENT) % LCG_MODULUS
        yield CHOICES[(state // LCG_DISCARD_LOW) % 3]


def play_series(rounds: int = 10000, seed: int = DEFAULT_SEED) -> dict:
    if rounds < 1:
        raise ValueError('rounds must be a positive integer')
    tally = dict.fromkeys(OUTCOMES, 0)
    stream = lcg_choices(seed, 2 * rounds)
    for p1, p2 in zip(stream, stream):
        tally[rock_paper_scissors_winner(p1, p2)] += 1
    return tally


def format_report(tally: dict, rounds: int, elapsed: float) -> str:
    lines = []
    for outcome in OUTCOMES:
        basis_points = 10000 * tally[outcome] // rounds
        lines.append('%-14s %7d  %6.2f%%' % (outcome, tally[outcome], basis_points / 100))
    per_round_us = elapsed / rounds * 1000000
    lines.append('%d rounds in %.4f s (%.2f us per round)' % (rounds, elapsed, per_round_us))
    daily = int(rounds / elapsed * 86400)
    lines.append('projected throughput: %d rounds/day' % daily)
    return '\n'.join(lines)


def main() -> None:
    demos = [('Rock', 'Scissors'), ('Paper', 'Paper'), ('rock', 'paper'), ('Scissors', ' scissors ')]
    for left, right in demos:
        print('%-10s vs %-10s -> %s' % (left, right, rock_paper_scissors_winner(left, right)))
    try:
        rock_paper_scissors_winner('Rock', 'Lizard')
    except ValueError as exc:
        print('rejected:', exc)
    rounds = 50000
    start = time.perf_counter()
    tally = play_series(rounds)
    elapsed = time.perf_counter() - start
    print(format_report(tally, rounds, elapsed))


if __name__ == '__main__':
    main()

