import sys

MAX_TEXT_LENGTH = 1000000
CHUNK_SIZE = 65536
RATE_SCALE = 10000


def count_char_frequencies(text: str) -> dict:
    """Return a case-sensitive mapping of each character to its frequency."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text exceeds %d characters" % MAX_TEXT_LENGTH)
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def merge_counts(target: dict, extra: dict) -> dict:
    """Accumulate the frequencies of `extra` into `target` and return it."""
    for ch, n in extra.items():
        target[ch] = target.get(ch, 0) + n
    return target


def count_file_frequencies(path: str, encoding: str = "utf-8") -> dict:
    """Count the characters of a text file, reading it in fixed-size chunks."""
    totals = {}
    with open(path, "r", encoding=encoding) as handle:
        while True:
            chunk = handle.read(CHUNK_SIZE)
            if not chunk:
                break
            merge_counts(totals, count_char_frequencies(chunk))
    return totals


def rates_per_scale(counts: dict) -> dict:
    """Frequency of every character expressed per 10000 characters of input."""
    total = sum(counts.values())
    if total == 0:
        return {}
    return {ch: n * RATE_SCALE / total for ch, n in counts.items()}


def plane_of(codepoint: int) -> str:
    if codepoint < 128:
        return "ascii"
    if codepoint < 256:
        return "latin-1"
    if codepoint < 65536:
