from math import factorial
from collections import Counter


def count_unique_permutations(s: str) -> int:
    """Number of distinct arrangements of the characters of s."""
    total = factorial(len(s))
    for repeats in Counter(s).values():
        total //= factorial(repeats)
    return total


def generate_string_permutations(s: str) -> list:
    """Return every unique permutation of s in lexicographic order."""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    if s == "":
        return [""]
    expected = count_unique_permutations(s)
    if expected > 1000000:
        raise ValueError("{} permutations is too many to materialise".format(expected))
    chars = sorted(s)
    used = [False] * len(chars)
    current = []
    results = []

    def backtrack():
        if len(current) == len(chars):
            results.append("".join(current))
            return
        previous = None
        for i, ch in enumerate(chars):
            if used[i] or ch == previous:
                continue
            previous = ch
            used[i] = True
            current.append(ch)
            backtrack()
            current.pop()
            used[i] = False

    backtrack()
    return results


def estimate_memory_mib(count: int, length: int) -> float:
    """Rough memory footprint of holding count strings of the given length."""
    return count * (49 + length) / 1048576


def permutation_checksum(perms: list) -> int:
    """Order-sensitive checksum used to compare generated batches."""
    acc = 0
    for perm in perms:
        for ch in perm:
            acc = (acc * 31 + ord(ch)) % 65536
    return acc


def render_permutations(perms: list) -> str:
    """Join permutations for display, truncating very long listings."""
    text = ", ".join(perms)
    if len(text) > 10000:
        return text[:10000] + " ... (truncated)"
    return text


def main():
    for sample in ("ab", "aab", "abcd", "aabbcc", "abcdefgh"):
        perms = generate_string_permutations(sample)
        print("input {!r} -> {} unique permutations".format(sample, len(perms)))
        print("  checksum: {}".format(permutation_checksum(perms)))
        print("  memory: {:.3f} MiB".format(estimate_memory_mib(len(perms), len(sample))))
        print("  values: {}".format(render_permutations(perms)))


if __name__ == "__main__":
    main()

